def test_robots_refusal_says_whether_it_was_a_rule_or_a_status_code():
    """Run 20260921T100546Z said only 'robots.txt disallows'; the reason now says whether a rule
    or a status code decided it. ** AND THE STATUS VERDICTS FOLLOW RFC 9309 (2026-09-28), not the
    stdlib: 4xx (401/403 included) = unavailable = may access; 5xx and 429 = unreachable =
    complete disallow.** beaconcha.in's robots.txt answered 403 two runs running and was refused."""
    from fetch.base import USER_AGENT
    from fetch.scrape import robots_from_response

    url = "https://maple.finance/transparency"
    for code in (401, 403, 404, 410):
        rp, how = robots_from_response("https://maple.finance/robots.txt", code, "")
        assert rp.can_fetch(USER_AGENT, url), code
        assert f"answered HTTP {code}" in how and "UNAVAILABLE" in how and "s2.3.1.3" in how, how
    for code in (429, 500, 503):
        rp, how = robots_from_response("https://maple.finance/robots.txt", code, "")
        assert not rp.can_fetch(USER_AGENT, url), code
        assert ("UNREACHABLE" in how or "429" in how) and "s2.3.1.4" in how, how

    rp, how = robots_from_response("https://maple.finance/robots.txt", 200,
                                   "User-agent: *\nDisallow: /transparency\n")
    assert not rp.can_fetch(USER_AGENT, url) and "HTTP 200" in how

    rp, _ = robots_from_response("https://maple.finance/robots.txt", 200, "User-agent: *\nDisallow:\n")
    assert rp.can_fetch(USER_AGENT, url)

    # A NETWORK ERROR fetching robots.txt is "unreachable" too — complete disallow (s2.3.1.4).
    import fetch.scrape as scrape
    real = scrape._ROBOTS.copy()
    try:
        scrape._ROBOTS.clear()
        import requests as _rq
        orig = _rq.get
        _rq.get = lambda *a, **k: (_ for _ in ()).throw(ConnectionError("reset"))
        try:
            ok, why = scrape.robots_verdict("https://example.invalid/data")
        finally:
            _rq.get = orig
        assert not ok and "UNREACHABLE" in why and "s2.3.1.4" in why, why
    finally:
        scrape._ROBOTS.clear()
        scrape._ROBOTS.update(real)


def test_maple_page_run_stores_holdings_and_complete_months_only(monkeypatch, tmp_path):
    """Promoted 2026-09-24 on Jake's run (robots.txt "Allow: /"). The fetcher stores the holding
    as today's stock and each COMPLETE month of buybacks, dated to month-end; a month that has
    not ended is not stored. robots.txt is still checked on every run."""
    import pandas as pd

    from fetch import maple_transparency as mt
    from fetch import scrape
    from fetch.base import FetchOutput, today

    monkeypatch.setattr(scrape, "CACHE_DIR", tmp_path)
    monkeypatch.setattr(scrape, "robots_verdict", lambda url: (True, "test"))
    this_month = today().strftime("%b %Y")
    html = (f"<div>SYRUP Holdings</div><div>79.21M</div><div>Liquid Assets</div><div>$4.31M</div>"
            f"<p>Showing 1-5 of 13</p><table>"
            f"<tr><td>{this_month}</td><td>$10.00</td><td>100.00</td><td>$0.1000</td></tr>"
            f"<tr><td>Aug 2026</td><td>$147,098.00</td><td>676,293.73</td><td>$0.2175</td></tr>"
            f"</table>")
    out = FetchOutput()
    mt.MapleTransparency(get=lambda url: html).run([config.PROJECT_BY_NAME["Maple"]], None, out)
    df = out.frame()
    assert df[df.metric == "treasury_holding_tokens"]["value"].tolist() == [79_210_000]
    # measured rows only: a month between two visible rows is a MEASURED ZERO (newest-first table),
    # which from October 2026 includes September in this fixture
    measured = df[~df["source"].str.contains(r"\[zero")]
    tok = measured[measured.metric == "actual_buyback_tokens"]
    assert tok["value"].tolist() == [676_293.73], "the unfinished month must not be stored"
    assert tok["date"].iloc[0] == pd.Timestamp("2026-08-31"), "dated to month-end"
    assert measured[measured.metric == "actual_buyback_usd"]["value"].tolist() == [147_098.00]
    assert set(measured["source"]) == {"maple_page"}
    buys = df[df.metric.isin(["actual_buyback_tokens", "actual_buyback_usd"])]
    assert not (buys["date"] >= today().replace(day=1)).any(), "no buyback row for the month still running"
    assert any("2 of 13 rows" in e.message for e in out.log)

    monkeypatch.setattr(scrape, "robots_verdict", lambda url: (False, "a Disallow rule"))
    out = FetchOutput()
    mt.MapleTransparency(get=lambda url: html).run([config.PROJECT_BY_NAME["Maple"]], None, out)
    assert out.frame().empty and {g["metric"] for g in out.gaps} >= {"treasury_holding_tokens"}


class _NearBlocksHttp:
    """Answers each v3 stats path with rows in the shape NearBlocks' own SQL produces."""

    def __init__(self, rows_by_path):
        self.rows_by_path, self.calls = rows_by_path, []

    def get(self, url, params=None, headers=None):
        self.calls.append((url, params, headers))
        path = url.split("api.nearblocks.io")[1]
        return self.rows_by_path[path]


def _nearblocks_run(monkeypatch, rows_by_path, key="nb-secret-123"):
    from fetch import nearblocks, scrape
    from fetch.base import FetchOutput

    monkeypatch.setenv("NEARBLOCKS_API_KEY", key)
    monkeypatch.setattr(scrape, "robots_verdict", lambda url: (True, "test"))
    http = _NearBlocksHttp(rows_by_path)
    out = FetchOutput()
    nearblocks.NearBlocks(http=http).run([config.PROJECT_BY_NAME["Near"]], None, out)
    return out, http


class _NearFlowHttp:
    """Answers GET /v1/account/{account}/txns with one page per call, keyed by the `cursor`
    param (None for the first page) — pagination-aware, unlike _NearBlocksHttp's fixed body."""

    def __init__(self, pages, v3=None):
        self.pages, self.v3, self.calls = pages, v3 or {}, []

    def get(self, url, params=None, headers=None):
        self.calls.append((url, params, headers))
        if "/v1/account/" in url:
            return self.pages[params.get("cursor")]
        path = url.split("api.nearblocks.io")[1]
        return self.v3[path]


def _near_flow_action(sender, deposit_yocto, action="TRANSFER"):
    return {"predecessor_account_id": sender, "receiver_account_id": "buybacks.multisignature.near",
            "block_timestamp": str(int(pd.Timestamp("2026-09-10").value)),
            "actions": [{"action": action, "method": None, "deposit": str(deposit_yocto), "fee": 0, "args": None}]}


def test_near_account_flow_sums_inflow_excluding_internal_hops(monkeypatch):
    """The two other near-intents wallets are internal hops, not fresh buyback inflow — dropped
    client-side since NearBlocks' `from` filter is an exact match, not a NOT-IN."""
    import pandas as pd

    from fetch import nearblocks, scrape
    from fetch.base import FetchOutput

    monkeypatch.setenv("NEARBLOCKS_API_KEY", "nb-secret-123")
    monkeypatch.setattr(scrape, "robots_verdict", lambda url: (True, "test"))
    rows = [
        _near_flow_action("some-user.near", 5_000_000_000_000_000_000_000_000),   # 5 NEAR, counts
        _near_flow_action("fefundsadmin.sputnik-dao.near", 9_000_000_000_000_000_000_000_000),  # excluded
        _near_flow_action("1csfundsadmin.sputnik-dao.near", 1_000_000_000_000_000_000_000_000),  # excluded
        _near_flow_action("another-user.near", 2_500_000_000_000_000_000_000_000),  # 2.5 NEAR, counts
    ]
    http = _NearFlowHttp({None: {"cursor": None, "txns": rows}})
    out = FetchOutput()
    nearblocks.NearBlocks(http=http).run([config.PROJECT_BY_NAME["Near"]], 35, out)
    df = out.frame()
    flow = df[(df.metric == "actual_buyback_tokens") & (df.source == "nearblocks")]
    assert abs(flow["value"].iloc[0] - 7.5) < 1e-9, \
        f"expected 5 + 2.5 = 7.5 NEAR, excluding the two hops: {flow}"
    assert flow["date"].iloc[0] == pd.Timestamp("2026-09-10")
    url, params, headers = next(c for c in http.calls if "/v1/account/" in c[0])
    assert params["action"] == "TRANSFER" and headers == {"Authorization": "Bearer nb-secret-123"}
    assert "nb-secret-123" not in " ".join(e.message for e in out.log)
    print("near account flow ok: 7.5 NEAR summed, two internal hops excluded")


