def test_the_stage2_carve_out_takes_only_pause_proxy_burns_from_2026_09_10():
    """Sky's Pause Proxy burned 426,292,860.23 in the 2025-06-26 spell (emissions offset) and
    2,860,943.76 in the 2026-09-10 spell (the first Stage 2 burn). Only the second is Stage 2.
    The carve-out dates each Pause Proxy event by its own block, stores the stock, and writes an
    EVENT-DATED daily flow — so the first read already carries the burn into the A4 window."""
    ts_2025 = int(pd.Timestamp("2025-06-30 14:00", tz="UTC").timestamp())
    ts_2026 = int(pd.Timestamp("2026-09-13 15:00", tz="UTC").timestamp())
    ts_head = int(pd.Timestamp("2026-09-24 06:00", tz="UTC").timestamp())
    events = [
        {"from": PAUSE_PROXY, "value": 426_292_860_230_000_000_000_000_000, "block": 22_817_692},
        {"from": PAUSE_PROXY, "value": 2_860_943_760_000_000_000_000_000, "block": 23_400_100},
        {"from": CONVERTER, "value": int(250_000 * WAD), "block": 22_000_000},
    ]
    from_block = config.PROJECT_BY_NAME["Sky"]["contracts"]["burn_logs"]["burn_logs"]["from_block"]
    reader = _LogReader(events, timestamps={22_817_692: ts_2025, 23_400_100: ts_2026,
                                            from_block + 2_600_000: ts_head})
    c = Chain(prior_values={}, prior_dates={})
    c.reader = reader
    out = FetchOutput()
    c.run([_sky_log_probe()], None, out)
    f = out.frame()
    stock = f.query("metric == 'sky_stage2_burn_balance'")
    assert len(stock) == 1 and float(stock.value.iloc[0]) == 2_860_943.76, stock
    total = float(f.query("metric == 'burn_address_balance'").value.iloc[0])
    assert abs(total - 429_153_803.99) < 1e-6, total          # the whole Pause Proxy, still read
    flow = f.query("metric == 'sky_stage2_burn_tokens'").set_index("date")["value"]
    assert flow.index.min() == pd.Timestamp("2026-09-10") and flow.index.max() == pd.Timestamp("2026-09-24")
    assert flow[pd.Timestamp("2026-09-13")] == 2_860_943.76
    assert float(flow.sum()) == 2_860_943.76 and (flow.drop(pd.Timestamp("2026-09-13")) == 0).all()
    src = f.query("metric == 'sky_stage2_burn_tokens'").source.iloc[0]
    assert config.withdrawn_contract_keys("Sky", "sky_stage2_burn_tokens", src) == [], src

    # THE FLOOR IS THE KNOWN BURN. A carve-out that misses it stores nothing.
    c = Chain(prior_values={}, prior_dates={})
    c.reader = _LogReader(events[:1], timestamps={22_817_692: ts_2025})
    out = FetchOutput()
    c.run([_sky_log_probe()], None, out)
    assert out.frame().query("metric in ['sky_stage2_burn_balance', 'sky_stage2_burn_tokens']").empty
    gap = next(g for g in out.gaps if g["metric"] == "sky_stage2_burn_balance")
    assert "below the known first burn of 2,860,943.76" in gap["reason"], gap["reason"]
    print("stage2 ok: 2,860,943.76 carved out by date; the 2025 offset excluded; floor exact")


def test_a4_headline_reads_the_stage2_flow_for_sky_and_gross_burn_for_everyone_else():
    """Permanent Burn Yield, the crossover and both net-change columns compute from
    config.a4_burn_metric: Sky's Stage 2 flow (its gross_burn_tokens is blocked), everyone
    else's gross_burn_tokens exactly as before."""
    import build_workbook as bw
    R = bw.Refs(100, 10, ["2026-09"])
    burn = lambda r, p, w="q0": R.D(r, config.a4_burn_metric(p["name"]), w)  # noqa: E731
    specs = bw._a4_headline(R, burn)
    # (Uniswap issues nothing since 2026-09-30 and renders burn-only, so Ethereum is "everyone else")
    sky, uni = config.PROJECT_BY_NAME["Sky"], config.PROJECT_BY_NAME["Ethereum"]
    for head, fn, *rest in specs:
        if head.startswith(("PERMANENT BURN YIELD", "BURN ÷ ISSUANCE", "NET SUPPLY CHANGE")):
            s, u = fn(5, sky), fn(5, uni)
            if head.startswith("BURN ÷ ISSUANCE"):
                # Sky issues nothing since 2026-10-05 (rewards are released treasury SKY): burn-only,
                # checked against its measured issuance like Uniswap's
                assert "no issuance — burn only" in s and "BLOCKED" in s, (head, s)
                continue
            assert '|sky_stage2_burn_tokens"' in s and '|gross_burn_tokens"' not in s, (head, s)
            assert '|gross_burn_tokens"' in u and "sky_stage2" not in u, (head, u)
    yield_meta = specs[0][5]
    assert yield_meta["metric_fn"]("Sky") == "sky_stage2_burn_tokens"
    assert yield_meta["metric_fn"]("Uniswap") == "gross_burn_tokens"
    print("a4 ok: Sky's headline reads the Stage 2 flow; other projects unchanged")


def test_sky_five_way_split_footnotes_and_closure_states():
    """Emissions offset and the SKY<->MKR migration flows are FOOTNOTES, not figures. The
    migration footnote is titled "closed 2025" only on a recorded probe count of 0 — Sky.burn is
    permissionless, so closure is observed, never deduced."""
    import copy
    sky = config.PROJECT_BY_NAME["Sky"]
    notes = config.burn_footnotes("Sky")
    assert len(notes) == 2 and notes[0].startswith("Emissions offset, 426,292,860.23")
    assert "not netted" in notes[0]
    # THE RECORDED RESULT (probe read 2026-09-28): one residual sender, a CONTRACT that burned
    # 0.000000 SKY in three calls — PRACTICALLY closed, never titled "closed 2025".
    assert "closed 2025" not in notes[1], notes[1]
    assert notes[1].startswith(
        "SKY<->MKR migration flows — practically closed — no SKY burned outside the Pause Proxy "
        "since block 22,817,692; one contract made three zero-value burn calls on 2026-01-16. "), notes[1]
    assert "REVERSIBLE" in notes[1] and "4,769,188,384.88" in notes[1]
    chk = sky["burn_footnotes"][1]["closure_check"]
    assert chk["detail"]["kind"] == "CONTRACT" and chk["detail"]["blocks"] == [24_246_077, 24_246_146, 24_246_170]
    saved = copy.deepcopy(sky["burn_footnotes"])
    try:
        chk = sky["burn_footnotes"][1]["closure_check"]
        chk["detail"]["amount_sky"] = None
        assert ("1 residual sender confirmed active as of 2026-09-28 "
                "(0xe751bf33164b8786c71d59c48f668d22408e142d, 3 burn(s), amount not yet pulled)"
                ) in config.burn_footnotes("Sky")[1], "an unread amount is never called practically closed"
        chk["detail"]["amount_sky"] = 1234.5
        assert "3 burn(s), 1,234.50 SKY)" in config.burn_footnotes("Sky")[1]
        chk.update(result=0, checked_on="2026-09-25")
        assert config.burn_footnotes("Sky")[1].startswith(
            "SKY<->MKR migration flows, closed 2025 (probe 2026-09-25: 0 senders after block 22,817,692)")
        chk.update(result=None)
        assert "closure NOT YET CONFIRMED" in config.burn_footnotes("Sky")[1]
    finally:
        sky["burn_footnotes"] = saved
    # other_burn_balance's blocked reason names the resolution, not just the flag.
    r = config.classification_pending("Sky", "other_burn_balance")["reason"]
    assert "RESOLVED by the five-way split" in r and "footnote" in r, r
    assert config.burn_footnotes("Uniswap") == []
    print("split ok: two footnotes, closure only on a recorded zero, reason names the split")


def test_an_as_buyback_row_is_judged_against_the_series_it_was_copied_from():
    """GEODNET actual_buyback_tokens rendered WITHDRAWN with source
    chain:polygon:burn_polygon:delta:as-buyback. Not a parse fault: the markers strip and the key
    resolves to burn_polygon. burn_polygon serves burn_address_balance, and the guard knew only
    actual_buyback_tokens' own parents. A row carrying :as-buyback is the burn flow renamed, so
    it is judged against the burn flow's parents — for any marker order, and only with the marker."""
    import build_workbook as bw
    g = "chain:polygon:burn_polygon:delta:as-buyback"
    assert config.strip_source_annotations(g) == g           # markers are left for the key split
    assert config.withdrawn_contract_keys("GEODNET", "actual_buyback_tokens", g) == []
    assert config.withdrawn_contract_keys("GEODNET", "actual_buyback_tokens",
                                          "chain:polygon:burn_polygon:as-buyback:delta") == []
    # WITHOUT the marker the same contract still does not serve the buyback: the guard is intact.
    assert config.withdrawn_contract_keys("GEODNET", "actual_buyback_tokens",
                                          "chain:polygon:burn_polygon:delta") == ["burn_polygon"]
    # The split route (Sky) follows its supply-reduction leg — now the Stage 2 flow.
    assert config.relabelled_from("Sky", "actual_buyback_tokens") == "sky_stage2_burn_tokens"
    assert config.relabelled_from("GEODNET", "actual_buyback_tokens") == "gross_burn_tokens"
    assert config.relabelled_from("GEODNET", "gross_burn_tokens") is None
    s_src = "chain:ethereum:burn_logs[sky_stage2_burn_tokens][logs@1-2]:as-buyback:PARTIAL"
    assert config.withdrawn_contract_keys("Sky", "actual_buyback_tokens", s_src) == []

    rows = [dict(date=pd.Timestamp(d), project="GEODNET", metric="actual_buyback_tokens",
                 value=v, source=g, tier=2, is_manual=False)
            for d, v in [("2026-09-22", 1000.0), ("2026-09-23", 1200.0)]]
    o = bw.aggregate(pd.DataFrame(rows), pd.DataFrame(), pd.Timestamp("2026-09-24"))
    r = o[(o.project == "GEODNET") & (o.metric == "actual_buyback_tokens")].iloc[0]
    assert r["status"] != "withdrawn" and "WITHDRAWN" not in str(r["note"]), (r["status"], r["note"])
    print("relabel ok: :as-buyback rows judged by their origin; unmarked rows still guarded")


def _pin_sky_2026_08_stream(monkeypatch):
    """The two caveat tests below test their MECHANISM on Sky's August 2026 stream as it was declared then
    (96,903,706 SKY / 90 days as gross issuance, to 2026-11-10). Since 2026-10-05 Sky's stream is
    emissions-only and its issuance a declared zero; the mechanism is unchanged, so the old shape is pinned."""
    sky = config.PROJECT_BY_NAME["Sky"]
    monkeypatch.setitem(sky, "issuance_schedule", {
        "steps": [{"from": "2026-08-13", "tokens_per_day": 96_903_706 / 90, "until": "2026-11-10"}],
        "source_url": "https://messari.io/", "source_date": "2026-08-13", "status": "active",
        "also_emissions": True, "note": "the August 2026 stream, pinned for the test"})
    monkeypatch.delitem(sky, "declared_zero", raising=False)
    monkeypatch.delitem(sky, "issuance_declared_zero", raising=False)


def test_a4_window_caveat_says_why_the_crossover_is_not_yet_a_rate(monkeypatch):
    """Issuance (a continuous schedule) is short in proportion to the days of Q0 it has existed;
    a discrete monthly burn is simply in the window or not. Their ratio is what happened in the
    window, not a rate, until the window is full and holds >= 3 burns — and the sheet says so
    beside the two figures, with numbers. Sky, 2026-09-24: 42 of 90 days of 1,076,707.84/day,
    one Stage 2 burn of 2,860,943.76."""
    _pin_sky_2026_08_stream(monkeypatch)
    import build_workbook as bw
    asof = pd.Timestamp("2026-09-24")
    rows = [dict(date=d, project="Sky", metric="sky_stage2_burn_tokens",
                 value=2_860_943.76 if d == pd.Timestamp("2026-09-13") else 0.0,
                 source="chain:ethereum:burn_logs[sky_stage2_burn_tokens]", tier=2, is_manual=False)
            for d in pd.date_range("2026-09-10", "2026-09-24")]
    rows += [dict(date=d, project="Sky", metric="gross_issuance_tokens", value=96_903_706 / 90,
                  source="schedule:config", tier=1, is_manual=False)
             for d in pd.date_range("2026-08-13", "2026-09-23")]
    o = bw.aggregate(pd.DataFrame(rows), pd.DataFrame(), asof)
    by = {r["key"]: r for r in o.to_dict("records")}
    iss, burn = by["Sky|gross_issuance_tokens"], by["Sky|sky_stage2_burn_tokens"]
    assert iss["q0_covered_days"] == 42 and abs(iss["q0"] - 45_221_729.47) < 0.01, iss["q0"]
    assert burn["q0_events"] == 1 and burn["q0"] == 2_860_943.76
    assert abs(burn["q0"] / iss["q0"] - 0.0632648) < 1e-7          # the ratio on the sheet

    cav = bw._a4_window_caveat(config.PROJECT_BY_NAME["Sky"], by)
    assert cav.startswith("NOT A STABLE RATE YET"), cav
    assert "ISSUANCE covers 42 of 90 days" in cav and "183,399,236/yr" in cav and "392,998,363/yr" in cav
    assert "BURN is 1 discrete event(s) in the window, not a rate" in cav
    assert "no padding" in cav and "at least 3 burn events" in cav and "48 more day(s)" in cav
    assert "unaffected" not in cav

    # A FULL window holding three burns says nothing: the caveat is not a permanent label.
    full = {"Sky|gross_issuance_tokens": dict(iss, q0_covered_days=90),
            "Sky|sky_stage2_burn_tokens": dict(burn, q0_events=3, q0_covered_days=90)}
    assert bw._a4_window_caveat(config.PROJECT_BY_NAME["Sky"], full) == ""
    # A continuous daily burn (hundreds of events) never trips the burn half.
    assert bw._a4_window_caveat(config.PROJECT_BY_NAME["Uniswap"],
                                {"Uniswap|gross_burn_tokens": {"q0_events": 90, "q0_covered_days": 90}}) == ""
    print("caveat ok: 42/90-day issuance and a single burn are called what they are")


def test_issuance_stream_expiry_caveat_fires_after_the_declared_end_and_clears_90_days_later(monkeypatch):
    """The mirror of the part-filled window: once a schedule's declared end has passed, Q0 keeps
    summing its last days while the true rate is zero, so the annualised figure OVERSTATES. Sky's
    LSSKY stream: 1,076,707.84/day from 2026-08-13, last issuing day 2026-11-10 (until is
    inclusive). The end date is the schedule's own; the day count is computed."""
    _pin_sky_2026_08_stream(monkeypatch)
    import build_workbook as bw
    assert config.issuance_schedule_end("Sky") == "2026-11-10"
    assert config.issuance_schedule_end("Uniswap") is None
    assert config.issuance_schedule_end("Bitcoin") is None       # a schedule that runs on

    rows = [dict(date=d, project="Sky", metric="gross_issuance_tokens", value=96_903_706 / 90,
                 source="schedule:config", tier=1, is_manual=False)
            for d in pd.date_range("2026-08-13", "2026-11-10")]
    sky = config.PROJECT_BY_NAME["Sky"]

    def at(day):
        o = bw.aggregate(pd.DataFrame(rows), pd.DataFrame(), pd.Timestamp(day))
        by = {r["key"]: r for r in o.to_dict("records")}
        return by["Sky|gross_issuance_tokens"], bw._a4_window_caveat(sky, by)

    # 2026-11-10: the stream's LAST issuing day — not expired; the window is still one day short.
    row, cav = at("2026-11-10")
    assert row["schedule_end"] == "2026-11-10" and not (row["q0_pre_end_days"] == row["q0_pre_end_days"])
    assert "STREAM ENDED" not in cav and "ISSUANCE covers 89 of 90 days" in cav, cav
    # 2026-11-11: the first day with no issuance. Fires, with the exact wording, and the
    # run-rate clause (which assumes a running stream) does not.
    row, cav = at("2026-11-11")
    assert row["q0_pre_end_days"] == 89, row["q0_pre_end_days"]
    assert cav.startswith("ISSUANCE STREAM ENDED 2026-11-10 — Q0 window still includes 89 pre-expiry "
                          "day(s); annualised figure reflects a schedule that no longer applies, "
                          "not current issuance. Clears once the full 90-day window is entirely "
                          "post-expiry."), cav
    assert "run-rate" not in cav
    # Counting down — the last day it fires, and the day it clears (end + 90 days).
    assert at("2027-02-07")[0]["q0_pre_end_days"] == 1 and "STREAM ENDED" in at("2027-02-07")[1]
    row, cav = at("2027-02-08")
    assert row["q0_pre_end_days"] == 0 and cav == "", cav

    # NEVER on a project without a declared end: a continuous burn and an open-ended schedule.
    uni = [dict(date=d, project="Uniswap", metric="gross_burn_tokens", value=100_000.0,
                source="chain:ethereum:burn_dead:delta", tier=2, is_manual=False)
           for d in pd.date_range("2026-06-01", "2026-12-01")]
    btc = [dict(date=d, project="Bitcoin", metric="gross_issuance_tokens", value=450.0,
                source="schedule:config", tier=1, is_manual=False)
           for d in pd.date_range("2026-06-01", "2026-12-01")]
    o = bw.aggregate(pd.DataFrame(uni + btc), pd.DataFrame(), pd.Timestamp("2026-12-01"))
    by = {r["key"]: r for r in o.to_dict("records")}
    for k in ("Uniswap|gross_burn_tokens", "Bitcoin|gross_issuance_tokens"):
        assert by[k]["schedule_end"] != by[k]["schedule_end"] or by[k]["schedule_end"] is None, by[k]
    assert "STREAM ENDED" not in bw._a4_window_caveat(config.PROJECT_BY_NAME["Uniswap"], by)
    print("expiry ok: fires 2026-11-11 (89 days) to 2027-02-07 (1 day), clears 2027-02-08; "
          "silent without a declared end")


def test_program_silence_flags_ether_fi_and_annotates_its_a3_cells():
    """Ether.fi, run 20260925T084404Z: last counted inflow 2026-06-30, 87 days before the run;
    the trailing window is all zeros and that zero is REAL. It stays on the sheet, annotated
    'no inflow since 2026-06-30', and — past 2x the longest documented cadence (monthly, so 60
    days) — flagged SILENT on the buyback, protocol-yield and both retirement-rate cells."""
    import openpyxl
    import tempfile
    import build_workbook as bw
    import store as store_mod
    asof = pd.Timestamp("2026-09-25")
    serial = float((pd.Timestamp("2026-06-30") - pd.Timestamp("1899-12-30")).days)
    rows = [dict(date=d, project="Ether.fi", metric="actual_buyback_tokens", value=0.0,
                 source="explorer:buyback_wallet_inflow", tier=2, is_manual=False)
            for d in pd.date_range("2026-08-26", "2026-09-24")]
    rows.append(dict(date=asof, project="Ether.fi", metric="buyback_last_inflow_date", value=serial,
                     source="explorer:buyback_wallet_inflow", tier=2, is_manual=False))
    o = bw.aggregate(pd.DataFrame(rows), pd.DataFrame(), asof)
    by = {r["key"]: r for r in o.to_dict("records")}
    bb = by["Ether.fi|actual_buyback_tokens"]
    assert bb["q0"] == 0.0 and bb["status"] != "n/a"                   # the zero stays
    assert bb["last_nonzero_date"] == "2026-06-30" and bb["silent_days"] == 87
    assert bb["silence_flag"].startswith("silent since 2026-06-30 — 87 days against a documented "
                                         "weekly/monthly cadence"), bb["silence_flag"]
    suffix, note = bw._program_flag(config.PROJECT_BY_NAME["Ether.fi"], by)
    assert suffix == " · no inflow since 2026-06-30 · SILENT 87d" and "PROGRAM SILENT" in note

    # GEODNET (daily): a gap in OUR runs is staleness, not silence — no observation after the
    # last burn, no flag. A burn 5 days ago with zero rows since is silence.
    g = [dict(date=pd.Timestamp("2026-09-20"), project="GEODNET", metric="gross_burn_tokens",
              value=5000.0, source="chain:polygon:burn_polygon:delta", tier=2, is_manual=False)]
    r = {x["key"]: x for x in bw.aggregate(pd.DataFrame(g), pd.DataFrame(), asof).to_dict("records")}
    assert not isinstance(r["GEODNET|gross_burn_tokens"]["silence_flag"], str)
    g += [dict(date=pd.Timestamp(d), project="GEODNET", metric="gross_burn_tokens", value=0.0,
               source="chain:polygon:burn_polygon:delta", tier=2, is_manual=False)
          for d in ("2026-09-22", "2026-09-24")]
    r = {x["key"]: x for x in bw.aggregate(pd.DataFrame(g), pd.DataFrame(), asof).to_dict("records")}
    assert "against a documented daily cadence" in r["GEODNET|gross_burn_tokens"]["silence_flag"]
    # No documented cadence, no flag, whatever the gap.
    assert config.program_cadence("Uniswap") is None

    # AND IT REACHES THE CELLS. Build Ether.fi's workbook and read A3's formats and comments.
    with tempfile.TemporaryDirectory() as d:
        st = store_mod.Store(f"{d}/m.db")
        st.upsert(pd.DataFrame(rows)[["date", "project", "metric", "value", "source", "tier"]])
        try:
            path = bw.build_workbook(st, f"{d}/w.xlsx", asof=asof, only=["Ether.fi"])
        finally:
            bw._SCOPE = list(bw.PROJECTS)          # build(only=...) narrows module state; restore it
        ws = openpyxl.load_workbook(path)["A3 Revenue Buyback"]
        hr = next(i for i in range(1, 10) if ws.cell(row=i, column=1).value == "Project")
        hdr = {ws.cell(row=hr, column=c).value: c for c in range(1, ws.max_column + 1)}
        er = next(i for i in range(hr + 1, ws.max_row + 1) if ws.cell(row=i, column=1).value == "Ether.fi")
        for head in ("CIRCULATING RETIREMENT RATE", "FDV RETIREMENT RATE", "Actual buyback Q0 ($)",
                     "Actual buyback Q0 (tokens)", "PROTOCOL STAKING YIELD"):
            c = ws.cell(row=er, column=next(v for k, v in hdr.items() if k and k.startswith(head)))
            assert "no inflow since 2026-06-30 · SILENT 87d" in c.number_format, (head, c.number_format)
            assert c.comment and "PROGRAM SILENT" in c.comment.text, head
            # The comment names the tracked address: the flag clears only if inflows land THERE.
            assert "0x2f5301a3D59388c509C65f8698f521377D41Fd0F" in c.comment.text, head
            assert "restart at a different address would leave this flag and the zero" in c.comment.text
            if head == "PROTOCOL STAKING YIELD":
                assert c.number_format.count("recipients unconfirmed"), c.number_format
                assert ("new programme (passed 2026-09-03) splits purchases between treasury and "
                        "user rewards; recipient class unconfirmed") in c.comment.text
    print("silence ok: Ether.fi 87d SILENT on five A3 cells; GEODNET staleness is not silence")


def test_run_sql_resolves_the_update_target_in_sections_z_and_aj(capsys):
    """--delete AJ refused with "Could not tell which table this DELETE targets: UPDATE metrics
    SET metric = 'locked_tokens_shares' ..." — the same failure as Z. Only DELETE FROM was ever
    recognised; UPDATE on its own line with SET and WHERE indented beneath matched nothing. The
    table is the token after UPDATE whatever the layout. Tested on the EXACT text of both
    sections, read through run_sql's own parser from orphan_cleanup.sql."""
    import builtins
    import pathlib
    import sqlite3
    import tempfile
    import run_sql
    import store as store_mod

    sql = (pathlib.Path(run_sql.__file__).resolve().parent / "orphan_cleanup.sql").read_text(encoding="utf-8")
    sections = run_sql.parse_sections(sql)
    for letter in ("Z", "AJ"):
        writes = [st for st in run_sql.split_statements("\n".join(run_sql.uncommented_write(sections[letter]["text"])))
                  if run_sql.classify(st) == "write"]
        targets = [run_sql.write_target(w) for w in writes]
        assert [t[:2] for t in targets] == [("DELETE", "metrics"), ("UPDATE", "metrics")], (letter, targets)
        upd = targets[1][2]
        # The OUTER where, not SET's text and not a subquery's.
        assert upd.startswith("project = 'Pendle' AND metric = 'locked_tokens'"), (letter, upd)
        assert "SET" not in upd.upper().split("WHERE")[0], upd
        # The DELETE's where carries its subquery whole.
        assert "SELECT date FROM metrics" in targets[0][2], targets[0][2]

    # EVERY commented write in the file resolves to a real store table — so neither the missing
    # UPDATE pattern nor a prose line opening a bogus statement can come back in a new section.
    with tempfile.TemporaryDirectory() as d:
        tables = {r[0] for r in store_mod.Store(f"{d}/t.db").conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table'")}
    for letter, sec in sections.items():
        for w in run_sql.split_statements("\n".join(run_sql.uncommented_write(sec["text"]))):
            if run_sql.classify(w) == "write":
                t = run_sql.write_target(w)
                assert t and t[1] in tables, (letter, t, run_sql.strip_comments(w)[:90])

    # A WHERE opening an unindented line used to fall back to "1=1" — the WHOLE table.
    assert run_sql.write_target("DELETE FROM metrics\nWHERE project = 'X'")[2] == "project = 'X'"
    assert run_sql.write_target("UPDATE OR IGNORE gap_report SET a = 1")[:2] == ("UPDATE", "gap_report")
    assert run_sql.write_target("SELECT 1") is None

    # END TO END: AJ now PREVIEWS both statements against a store holding Jake's post-move state
    # (he applied AJ's UPDATE by hand — 9 rows moved), and a non-matching confirmation changes
    # nothing. Nothing is left to move, so both previews read 0 rows.
    with tempfile.TemporaryDirectory() as d:
        st = store_mod.Store(f"{d}/m.db")
        st.upsert(pd.DataFrame(
            [(pd.Timestamp("2026-09-%02d" % (11 + i)), "Pendle", "locked_tokens_shares", 31e6 + i,
              "chain:ethereum:spendle", 2) for i in range(9)]
            + [(pd.Timestamp("2026-09-24"), "Pendle", "locked_tokens", 35_459_772.88,
                "chain:ethereum:spendle_underlying", 2)],
            columns=["date", "project", "metric", "value", "source", "tier"]))
        real_input = builtins.input
        builtins.input = lambda *a: "no"
        try:
            rc = run_sql.main(["--delete", "AJ", "--db", f"{d}/m.db"])
        finally:
            builtins.input = real_input
        out = capsys.readouterr().out
        assert "Could not tell which table" not in out, out[-600:]
        assert "Rows this would remove from metrics (0)" in out, out[-900:]
        assert "Rows this UPDATE would change in metrics (0)" in out, out[-900:]
        assert rc == 1       # nothing matches: "already been run" — the correct answer post-move
        n = sqlite3.connect(f"{d}/m.db").execute(
            "SELECT COUNT(*) FROM metrics WHERE metric = 'locked_tokens_shares'").fetchone()[0]
        assert n == 9
    print("run_sql ok: UPDATE targets resolve in Z and AJ; AJ previews cleanly after the hand move")


def test_ether_fi_counts_cow_settlements_only_and_labels_the_other_inflow(monkeypatch):
    """Jake, 2026-09-28: Ether.fi's buyback is CoW Protocol purchases only. The other two
    senders (ether.fi deployer, unidentified Safe) are recorded as "other inflow, not counted",
    labelled, never summed. With run 20260925T084404Z's three senders that is 17,984,520.10."""
    spec = next(s for s in config.PROJECT_BY_NAME["Ether.fi"]["log_scans"] if s["key"] == "buyback_wallet_inflow")
    assert spec["attribution"] == "count_from"
    cow = "0x9008d19f58aabd9ed0d60971565aa8510560ab41"
    dep, safe = "0x9eac7114d1a1eabc4732a886795cfd9e6e35843f", "0x01e42ad3acd58584ffc1d1982ecbbe758996d601"
    assert spec["count_from"] == [cow] and set(spec["not_counted_labels"]) == {dep, safe}
    wallet = spec["holders"][0].lower()
    t0 = int(pd.Timestamp("2026-06-30").timestamp())
    E = 10 ** 16                                      # 0.01 ETHFI, so two-decimal figures are exact
    logs = _flow_logs(wallet, [(100, cow, 1_798_452_010 * E, t0 - 86_400 * 30),
                               (200, dep, 39_651_067 * E, t0 - 86_400 * 10),
                               (300, safe, 60_000_000 * E, t0 - 86_400 * 5),
                               (400, cow, 0 * E + 1, t0)])
    total = 1_798_452_010 * E + 39_651_067 * E + 60_000_000 * E + 1
    probe = dict(spec, token="0xtoken")
    out = _run_scan(monkeypatch, probe, logs, {wallet: total}, name="Ether.fi")
    got = out.frame()
    flow = got[got.metric == "actual_buyback_tokens"]
    assert abs(flow.value.sum() - 17_984_520.10) < 1e-6, flow.value.sum()
    line = next(e.message for e in out.log if "RECONCILED" in e.message)
    assert "Other inflow, not counted:" in line
    assert f"{safe} 600,000.00 [ether.fi-controlled Safe" in line and "internal transfer" in line, line
    assert f"{dep} 396,510.67 [ether.fi deployer EOA" in line, line
    # The last-inflow date is the last CoW settlement, not the last transfer of any kind.
    last = got[got.metric == "buyback_last_inflow_date"]
    assert float(last.value.iloc[0]) == float((pd.Timestamp("2026-06-30") - pd.Timestamp("1899-12-30")).days)
    print("ether.fi ok: CoW only = 17,984,520.10; deployer and Safe labelled, not counted")


def test_a_burn_route_buyback_is_a_view_of_the_whole_burn_series():
    """Hyperliquid, run 20260928T090446Z: burn Q0 379,892.53 vs buyback Q0 147,958.35 for ONE
    flow. The stored buyback copies began at the first run after the relabel route existed; the
    burn series is older. Read as a view, the two are identical — and the usd twin covers the same
    days, so the covered-days annualisation sees the burn's real history."""
    import build_workbook as bw
    bw._SCOPE = list(bw.PROJECTS)                  # never depend on another test's build scope
    asof = pd.Timestamp("2026-09-28")
    burn = [dict(date=d, project="Hyperliquid", metric="gross_burn_tokens", value=10_000.0,
                 source="hypercore_info:spotClearinghouseState:delta", tier=1, is_manual=False)
            for d in pd.date_range("2026-08-30", "2026-09-27")]
    copies = [dict(r, metric="actual_buyback_tokens", source=r["source"] + ":as-buyback")
              for r in burn if r["date"] >= pd.Timestamp("2026-09-11")]
    price = [dict(date=d, project="Hyperliquid", metric="price_usd", value=40.0, source="coingecko",
                  tier=1, is_manual=False) for d in pd.date_range("2026-08-01", "2026-09-27")]
    # 2026-09-29 (Jake): the buyback equals the TOTAL burn — Assistance Fund + Core burns. The
    # Core leg is rebuilt from the stored totalSupply (falling 2,000/day) where no core row exists.
    stock = [dict(date=d, project="Hyperliquid", metric="total_supply_gross",
                  value=999_000_000.0 - 2_000.0 * i, source="hypercore_info:tokenDetails", tier=1,
                  is_manual=False) for i, d in enumerate(pd.date_range("2026-08-29", "2026-09-27"))]
    o = bw.aggregate(pd.DataFrame(burn + copies + price + stock), pd.DataFrame(), asof)
    by = {r["key"]: r for r in o.to_dict("records")}
    b, t, u = by["Hyperliquid|gross_burn_tokens"], by["Hyperliquid|actual_buyback_tokens"], by["Hyperliquid|actual_buyback_usd"]
    tot = by["Hyperliquid|total_burn_tokens"]
    assert b["q0"] == 290_000.0, b["q0"]                              # the Fund leg, unchanged
    assert t["q0"] == tot["q0"] == 348_000.0, (t["q0"], tot["q0"])     # 29 days x (10,000 + 2,000)
    assert u["q0"] == 348_000.0 * 40 and u["q0_covered_days"] == b["q0_covered_days"] == 29
    assert "as-buyback" in str(t["source"])
    # GEODNET's buyback is no longer Dune-sourced (2026-09-28): it is this same view of its burn.
    assert config.dune_query_declared("GEODNET", "actual_buyback_tokens") is None
    print("view ok: Hyperliquid buyback == burn over the burn's whole history")


def test_headlines_annualise_continuous_flows_over_covered_days_and_discrete_ones_by_the_window():
    """Run 20260928T090446Z: Chainlink's ~60-day and Hyperliquid's ~17-day buyback series were
    annualised x365/90, reading 0.21% and 0.28%. CONTINUOUS flows now divide by covered days while
    coverage is short; DISCRETE ones (declared cadence > 1 day) keep x365/90 and their caveat."""
    import build_workbook as bw
    R = bw.Refs(100, 10, ["2026-09"])
    specs = bw._a3_headline(R, {})
    circ_fn = specs[0][1]
    cl = circ_fn(5, config.PROJECT_BY_NAME["Chainlink"])
    ef = circ_fn(5, config.PROJECT_BY_NAME["Ether.fi"])
    cov_col = bw.DC["q0_covered_days"]
    # tokens primary (2026-09-30): the headline pair reads buyback TOKENS
    assert f"${cov_col}$" in cl and '"|actual_buyback_tokens"' in cl and "/" in cl, cl
    usd = specs[2][1](5, config.PROJECT_BY_NAME["Chainlink"])
    assert f"${cov_col}$" in usd and '"|actual_buyback_usd"' in usd, usd
    assert f"${cov_col}$" not in ef, ef                                   # weekly/monthly: discrete
    assert bw._lumpy("Sky") and bw._lumpy("Ether.fi") and not bw._lumpy("Chainlink")
    assert not bw._lumpy("GEODNET")                                        # daily = continuous
    # The arithmetic the formula encodes, on the run's own numbers.
    before = 0.0021
    assert abs(before * 90 / 60 - 0.00315) < 1e-12                         # Chainlink, ~60 days
    assert abs(before / 0.0021 * 0.0028 * 90 / 17 - 0.0148) < 1e-4        # Hyperliquid, ~17 days
    # Every named headline uses it.
    a4 = bw._a4_headline(R, lambda r, p, w="q0": R.D(r, config.a4_burn_metric(p["name"]), w), {})
    assert f"${cov_col}$" in a4[0][1](5, config.PROJECT_BY_NAME["Uniswap"])
    assert f"${cov_col}$" not in a4[0][1](5, config.PROJECT_BY_NAME["Sky"])   # monthly Stage 2 burn
    print("annualise ok: continuous over covered days, discrete by the window")


def test_data_tab_writes_day_counts_as_numbers_so_formulas_can_read_them():
    """The appended day-count columns landed as TEXT ("14.0", "nan"), so ISNUMBER() on them was
    FALSE and the covered-days annualisation silently fell back to x365/90 on every real sheet —
    while formula-level tests passed. Found 2026-09-28 by recalculating a built workbook."""
    import openpyxl
    import tempfile
    import build_workbook as bw
    import store as store_mod
    asof = pd.Timestamp("2026-09-28")
    rows = [(d, "Chainlink", "actual_buyback_usd", 100_000.0, "derived:tokens*price", 2)
            for d in pd.date_range("2026-07-30", "2026-09-27")]
    with tempfile.TemporaryDirectory() as d:
        st = store_mod.Store(f"{d}/m.db")
        st.upsert(pd.DataFrame(rows, columns=["date", "project", "metric", "value", "source", "tier"]))
        try:
            path = bw.build_workbook(st, f"{d}/w.xlsx", asof=asof, only=["Chainlink"])
        finally:
            bw._SCOPE = list(bw.PROJECTS)
        ws = openpyxl.load_workbook(path)["Data"]
        col = bw.DATA_COLS.index("q0_covered_days") + 1
        row = next(i for i in range(2, ws.max_row + 1)
                   if ws.cell(row=i, column=1).value == "Chainlink|actual_buyback_usd")
        c = ws.cell(row=row, column=col)
        assert c.data_type == "n" and c.value == 60, (c.data_type, c.value)   # 07-30 .. asof 09-28
        blanks = {ws.cell(row=i, column=col).value for i in range(2, ws.max_row + 1)} - {None, ""}
        assert all(isinstance(v, int) for v in blanks), blanks                 # never "nan" text
    print("data ok: day counts are numbers, blanks are blank")


