def test_declared_or_first_party_issuance_is_primary_in_every_consumer():
    """Jake, 2026-09-28: A4's crossover kept reading DERIVED issuance after A1 moved to declared.
    NEAR derived Q0 265,367 vs declared 32.2M/yr -> burn/issuance 0.090 instead of ~0.003;
    Ethereum derived 9,106 ETH vs ~2,700 ETH/day -> 0.168 instead of ~0.013. The issuance series
    itself is now replaced at read time, so every consumer reads the same primary figure."""
    import build_workbook as bw

    asof = pd.Timestamp("2026-09-28")
    days = pd.date_range("2026-07-01", "2026-09-27")

    def rows(project, metric, values, source, dates=days):
        return [{"date": d, "project": project, "metric": metric, "value": v, "source": source,
                 "tier": 2, "is_manual": False, "entered_on": ""}
                for d, v in zip(dates, values if isinstance(values, list) else [values] * len(dates))]

    def agg(data):
        return bw.aggregate(pd.DataFrame(data), pd.DataFrame(), asof, gaps=pd.DataFrame(),
                            review=pd.DataFrame()).set_index(["project", "metric"])

    supply = 1_288_000_000.0
    # (a) NEAR, derived consistent with declared over its covered days -> declared shown
    base = rows("Near", "total_supply", supply, "near_rpc")
    near_obs = rows("Near", "gross_issuance_tokens", supply * 0.025 / 365,
                    "derived:d_total_supply_protocol+burn",
                    dates=days[-3:])
    out = agg(base + near_obs)
    r = out.loc[("Near", "gross_issuance_tokens")]
    assert r["status"] not in bw.WITHHELD_STATUSES, r["note"]
    assert abs(r["q0"] - supply * 0.025 / 365 * 89) / r["q0"] < 1e-9, "declared, every day of Q0"
    # (b) NEAR derived 30x low over a full window -> BLOCKED with both figures
    low = rows("Near", "gross_issuance_tokens", supply * 0.025 / 365 / 30,
               "derived:d_total_supply_protocol+burn")
    r = agg(base + low).loc[("Near", "gross_issuance_tokens")]
    assert r["status"] == "blocked" and "declared 32,200,000 vs observed 1,073,333" in r["note"], r["note"]
    # (c) Ethereum: CoinGecko-derived rows only -> BLOCKED waiting for Etherscan (A9, 2026-09-28:
    #     first-party is now d(total_supply_protocol) + d(BurntFees)); first-party -> shown
    eth_d = rows("Ethereum", "gross_issuance_tokens", 101.2, "derived:d_supply+burn")
    r = agg(eth_d).loc[("Ethereum", "gross_issuance_tokens")]
    assert r["status"] == "blocked" and "Etherscan ethsupply2" in r["note"]
    eth_b = rows("Ethereum", "gross_issuance_tokens", 2_700.0,
                 "derived:d_total_supply_protocol+burn", dates=days[-5:])
    r = agg(eth_d[:-5] + eth_b).loc[("Ethereum", "gross_issuance_tokens")]
    assert r["status"] not in bw.WITHHELD_STATUSES and r["q0"] == 5 * 2_700.0, (r["status"], r["q0"])
    # (d) GEODNET: derived release over a flat circulating figure -> BLOCKED; measured -> primary
    geo = (rows("GEODNET", "pool_release_tokens", 1_000.0, config.POOL_RELEASE_DERIVED_SOURCE)
           + rows("GEODNET", "circulating_supply", 462_370_402.0, "coingecko"))
    r = agg(geo).loc[("GEODNET", "pool_release_tokens")]
    assert r["status"] == "blocked" and "mining-wallet outflow" in r["note"]
    meas = rows("GEODNET", "pool_release_tokens", 250_000.0, "balance_flow:mining_wallets_release",
                dates=days[-10:])
    r = agg(geo[len(days):] + meas).loc[("GEODNET", "pool_release_tokens")]
    assert r["status"] not in bw.WITHHELD_STATUSES and r["q0"] == 2_500_000.0
    # (e) any project: derived release over flat circulating -> "circulating not updating"
    wm = (rows("World Mobile", "pool_release_tokens", 5.0, config.POOL_RELEASE_DERIVED_SOURCE)
          + rows("World Mobile", "circulating_supply", 1e9, "coingecko"))
    out = agg(wm)
    if ("World Mobile", "pool_release_tokens") in out.index:
        r = out.loc[("World Mobile", "pool_release_tokens")]
        assert r["status"] == "blocked" and "circulating not updating" in r["note"], r["note"]


def test_nearblocks_stats_run_first_and_calls_are_paced_to_the_free_plan(monkeypatch,
                                                                             _nearblocks_fake_clock):
    """Live run 20260928T090446Z: two v3 calls at limit=100 (4 credits each) then the buyback
    page, all inside a minute, against a 6-credit/min free plan -> 429 on the buyback. The
    buyback now goes first, and no 60s window ever carries more than 6 credits."""
    from fetch import nearblocks, scrape
    from fetch.base import FetchOutput

    monkeypatch.setenv("NEARBLOCKS_API_KEY", "nb-secret-123")
    monkeypatch.setattr(scrape, "robots_verdict", lambda url: (True, "test"))
    stamps = []

    class H(_NearFlowHttp):
        def get(self, url, params=None, headers=None):
            stamps.append((nearblocks._clock(), url))
            return super().get(url, params, headers)

    rows = [_near_flow_action("some-user.near", 10 ** 24)]
    http = H({None: {"cursor": "p2", "txns": rows}, "p2": {"cursor": None, "txns": rows}},
             v3={"/v3/txn-stats": {"data": []}, "/v3/address-stats": {"data": []}})
    nearblocks.NearBlocks(http=http).run([config.PROJECT_BY_NAME["Near"]], 35, FetchOutput())
    kinds = ["flow" if "/v1/account/" in u else "v3" for _, u in stamps]
    # ORDER REVERSED 2026-09-28: the once-a-day stats first (1 credit each), then the buyback
    # read, which resumes across runs — see NearBlocks.run.
    assert kinds == ["v3", "v3", "flow", "flow"], kinds
    # BILLED AS NEARBLOCKS BILLS: ceil(per_page/25), per_page defaulting to 25. The v3 calls send
    # `limit`, so they cost 1 (they were charged 4 until 2026-09-28).
    cost = {"flow": nearblocks.credits_for(nearblocks.FLOW_PER_PAGE), "v3": 1}
    assert cost == {"flow": 2, "v3": 1}
    for t0, _ in stamps:
        in_window = sum(cost[k] for (t, _), k in zip(stamps, kinds) if t0 <= t < t0 + 60)
        assert in_window <= nearblocks.CREDITS_PER_MINUTE, (t0, in_window, stamps)
    assert _nearblocks_fake_clock == [], "2+2+1+1 = 6 credits: nothing had to wait"


def test_http_429_without_retry_after_waits_the_configured_window(monkeypatch):
    """NearBlocks' limiter sends no Retry-After; its window is a minute, so Http waits that
    rather than its 2s exponential start. A Retry-After, when sent, is honoured, both RFC 9110
    forms (seconds and HTTP-date)."""
    import email.utils
    import time as _time

    from fetch import base

    naps = []
    monkeypatch.setattr(base.time, "sleep", lambda s: naps.append(s))

    class R:
        def __init__(self, code, headers=None):
            self.status_code, self.headers = code, headers or {}

        def json(self):
            return {"ok": 1}

        def raise_for_status(self):
            pass

    def run(responses, **kw):
        naps.clear()
        h = base.Http(retries=2, **kw)
        seq = iter(responses)
        monkeypatch.setattr(h.s, "get", lambda *a, **k: next(seq))
        assert h.get("https://api.example/x") == {"ok": 1}
        return list(naps)

    assert run([R(429), R(200)], rate_limit_wait=60.0) == [60.0]
    assert run([R(429), R(200)]) == [2.0], "no configured window: the old backoff"
    assert run([R(429, {"Retry-After": "7"}), R(200)], rate_limit_wait=60.0) == [7.0]
    date = email.utils.formatdate(_time.time() + 30, usegmt=True)
    assert 25 <= run([R(429, {"Retry-After": date}), R(200)])[0] <= 31
    assert base.retry_after("garbage") is None and base.retry_after(None) is None


def _incremental_setup(monkeypatch):
    E, t0 = 10 ** 18, int(pd.Timestamp("2026-09-01").timestamp())
    pay = "0x5680681ed3767b96914ce741a308155c7fb9171d"
    reserve = "0x9a709b7b69ea42d5eeb1cebc48674c69e1569ec6"
    spec = {"key": "reserve_inflow", "metric": "actual_buyback_tokens", "chain": "ethereum",
            "token": "0xtoken", "holders": [reserve], "direction": "in", "store": True,
            "count_from": [pay]}
    return E, t0, pay, reserve, spec


def test_log_scans_are_incremental_after_the_first_run(monkeypatch):
    """Run 20260928T090446Z: every scan re-read full history each run. The second run asks
    only for blocks after the first run's pinned block, and still reconciles the WHOLE history
    (cached + new) to balanceOf before storing."""
    from fetch.base import FetchOutput
    from fetch.logscan import LogScan, CONFIRMATIONS
    E, t0, pay, reserve, spec = _incremental_setup(monkeypatch)
    day = 86_400
    logs = _flow_logs(reserve, [(100, pay, 5 * E, t0), (300, pay, 3 * E, t0 + day),
                                (1_500, pay, 4 * E, t0 + 3 * day)])
    ex = _explorer(monkeypatch, logs, max_records=1000)

    out1 = FetchOutput()
    LogScan(explorer=ex, reader=_FakeReader({reserve: 8 * E}, head=1_000))._scan(
        {"name": "Chainlink"}, spec, None, out1)
    assert "full history read" in next(e.message for e in out1.log if "RECONCILED" in e.message)
    assert all(int(c[1]["fromBlock"]) == 0 for c in ex.http.calls)

    ex.http.calls.clear()
    out2 = FetchOutput()
    LogScan(explorer=ex, reader=_FakeReader({reserve: 12 * E}, head=2_000))._scan(
        {"name": "Chainlink"}, spec, None, out2)
    froms = {int(c[1]["fromBlock"]) for c in ex.http.calls}
    assert froms == {1_000 - CONFIRMATIONS + 1}, f"only newer blocks are asked for: {froms}"
    line = next(e.message for e in out2.log if "RECONCILED" in e.message)
    assert "incremental: 2 cached event(s) to block 980, 1 new to block 1,980" in line, line
    got = out2.frame()
    got = got[got.metric == "actual_buyback_tokens"]
    assert got.value.sum() == 12.0, "the whole history, cached + new, is the series"

    # THE CACHE IS NOT TRUSTED: a balance the cached + new events do not explain refuses, and
    # the proven cache is kept (not advanced) for the re-run.
    ex.http.calls.clear()
    out3 = FetchOutput()
    LogScan(explorer=ex, reader=_FakeReader({reserve: 12 * E + 1}, head=2_500))._scan(
        {"name": "Chainlink"}, spec, None, out3)
    assert out3.frame().empty
    assert "1 wei unaccounted" in next(g["reason"] for g in out3.gaps)
    ex.http.calls.clear()
    out4 = FetchOutput()
    LogScan(explorer=ex, reader=_FakeReader({reserve: 12 * E}, head=2_500))._scan(
        {"name": "Chainlink"}, spec, None, out4)
    assert {int(c[1]["fromBlock"]) for c in ex.http.calls} == {2_000 - CONFIRMATIONS + 1}, \
        "a failed reconciliation does not advance the cache"
    assert not out4.frame().empty


def test_a_seed_that_runs_out_of_budget_resumes_next_run(monkeypatch):
    """GEODNET's mining_wallets_outflow timed out inside 120s on every run, so it never stored
    anything. The seed now keeps the whole blocks it read and the next run continues from there;
    nothing is stored until the full history reconciles. A seed that then fails to reconcile is
    dropped — it was never proven."""
    from fetch import explorer as exmod
    from fetch.base import FetchOutput
    from fetch.logcache import LogCache
    from fetch.logscan import LogScan
    E, t0, pay, reserve, spec = _incremental_setup(monkeypatch)
    inflows = [(100 + 10 * i, pay, E, t0 + i * 3_600) for i in range(9)]   # 9 logs, 3 per page
    logs = _flow_logs(reserve, inflows)
    ex = _explorer(monkeypatch, logs, max_records=3)
    real_call, calls = exmod.ExplorerLogs._call, [0]

    def call_then_time_out(self, name, chain_id, params):
        calls[0] += 1
        if calls[0] == 3:
            raise exmod.ExplorerTimeout("explorer scan timed out after 120s, provider errors: none")
        return real_call(self, name, chain_id, params)
    monkeypatch.setattr(exmod.ExplorerLogs, "_call", call_then_time_out)

    out1 = FetchOutput()
    LogScan(explorer=ex, reader=_FakeReader({reserve: 9 * E}))._scan({"name": "Chainlink"}, spec, None, out1)
    assert out1.frame().empty
    g = next(g for g in out1.gaps if g["metric"] == "actual_buyback_tokens")
    # pages: blocks 100-120 | 120-140 (cursor now 140) | timeout -> blocks < 140 are whole
    assert "SEEDING, RESUMABLE" in g["reason"] and "to block 139 of 980" in g["reason"], g["reason"]

    monkeypatch.setattr(exmod.ExplorerLogs, "_call", real_call)
    ex.http.calls.clear()
    out2 = FetchOutput()
    LogScan(explorer=ex, reader=_FakeReader({reserve: 9 * E}))._scan({"name": "Chainlink"}, spec, None, out2)
    assert int(ex.http.calls[0][1]["fromBlock"]) == 140, "resumes where the seed stopped"
    got = out2.frame()
    assert got[got.metric == "actual_buyback_tokens"].value.sum() == 9.0

    # a seed that does not reconcile is removed, not kept to fail forever
    lc = LogCache()
    spec2 = dict(spec, key="reserve_inflow_b", holders=["0x00000000000000000000000000000000000000cc"])
    monkeypatch.setattr(exmod.ExplorerLogs, "_call", call_then_time_out)
    calls[0] = 0
    logs2 = _flow_logs(spec2["holders"][0], inflows)
    ex2 = _explorer(monkeypatch, logs2, max_records=3)
    LogScan(explorer=ex2, reader=_FakeReader({}))._scan({"name": "Chainlink"}, spec2, None, FetchOutput())
    assert list(lc.root.glob("*.json.gz")), "the partial seed was cached"
    before = {f.name for f in lc.root.glob("*.json.gz")}
    monkeypatch.setattr(exmod.ExplorerLogs, "_call", real_call)
    out3 = FetchOutput()
    LogScan(explorer=ex2, reader=_FakeReader({spec2["holders"][0]: 1})) \
        ._scan({"name": "Chainlink"}, spec2, None, out3)
    assert out3.frame().empty
    after = {f.name for f in lc.root.glob("*.json.gz")}
    from fetch.explorer import TRANSFER_TOPIC, pad_address
    from fetch.logcache import stream_id
    h2 = pad_address(spec2["holders"][0])
    seed = {lc.path(stream_id(1, "0xtoken", t)).name
            for t in ([TRANSFER_TOPIC, None, h2], [TRANSFER_TOPIC, h2, None])}
    assert seed & before and not (seed & after), (seed, before, after)
    assert before - seed == after, "the proven streams of the first scan are untouched"


def test_sky_burn_scan_is_incremental_and_caches_only_final_blocks():
    """Sky's burn_logs re-read ~2M blocks from 20,663,735 every run. Events BURN_CONFIRMATIONS
    deep are final and cached; the next run scans from the block after, and still returns the
    whole history. Blocks near the head are re-read, never cached."""
    import types

    from fetch import chain as chainmod
    token = "0x56072C95FAA701256059aa122697B133aDEd9279"
    sender = "0x" + "ab" * 20
    burns = {20_663_800: 5, 20_663_900: 7, 20_700_000: 11}   # block -> value

    class R(chainmod.ChainReader):
        head = 20_663_950

        def web3(self, chain):
            return types.SimpleNamespace(eth=types.SimpleNamespace(block_number=self.head))

        def scan_logs(self, chain, base, from_block, to_block, chunk=10_000):
            self.asked = (from_block, to_block)
            raw = [{"data": hex(v), "topics": [base["topics"][0], "0x" + "0" * 24 + sender[2:],
                                                base["topics"][2]], "blockNumber": b}
                   for b, v in burns.items() if from_block <= b <= to_block]
            return raw, 1, chunk

    r = R()
    ev, first, last, _ = r.burn_transfer_events("ethereum", token, "0x" + "0" * 40, 20_663_735)
    assert r.asked == (20_663_735, 20_663_950) and [e["value"] for e in ev] == [5, 7]
    assert "full history" in r.log_incremental["ethereum"]
    # 20_663_900 is <= head - 20, so cached; the next run starts at head - 20 + 1
    R.head = 20_700_010
    r2 = R()
    ev2, first2, _, _ = r2.burn_transfer_events("ethereum", token, "0x" + "0" * 40, 20_663_735)
    assert r2.asked == (20_663_950 - chainmod.BURN_CONFIRMATIONS + 1, 20_700_010), r2.asked
    assert [e["value"] for e in ev2] == [5, 7, 11] and first2 == 20_663_735
    assert "incremental: 2 cached event(s)" in r2.log_incremental["ethereum"]
    # a different from_block is a different stream: full read again
    r3 = R()
    r3.burn_transfer_events("ethereum", token, "0x" + "0" * 40, 20_663_000)
    assert r3.asked[0] == 20_663_000


def test_ethereum_base_fee_burn_is_not_a_buyback_and_near_gas_burn_is_not_relabelled():
    """Run 20260928T090446Z: Ethereum actual_buyback_tokens = 1,389.76 via
    derived:defillama_burned_fee_revenue/price:as-buyback. EIP-1559 buys nothing; the burn stays
    on A4, the buyback columns are n/a — including over rows already stored."""
    import build_workbook as bw
    from fetch import _derive_buyback
    from fetch.base import FetchOutput, point

    assert config.buyback_route("Ethereum")["route"] == "none"
    eth = config.PROJECT_BY_NAME["Ethereum"]
    assert "actual_buyback_tokens" not in config.metrics_for_project(eth)
    assert "gross_burn_tokens" in config.metrics_for_project(eth), "the burn stays on A4"
    out = FetchOutput()
    out.add(point("Ethereum", "gross_burn_tokens", 50.0,
                  "derived:defillama_burned_fee_revenue/price", 1, pd.Timestamp("2026-09-20")),
            "derived", "Ethereum", "burn", 1)
    _derive_buyback(out, [eth])
    assert out.frame().query("metric == 'actual_buyback_tokens'").empty, "no re-label"

    rows = [{"date": d, "project": "Ethereum", "metric": m, "value": v, "source": src, "tier": 2,
             "is_manual": False, "entered_on": ""}
            for d in pd.date_range("2026-09-01", "2026-09-27")
            for m, v, src in [("actual_buyback_tokens", 50.0,
                               "derived:defillama_burned_fee_revenue/price:as-buyback"),
                              ("actual_buyback_usd", 2e5, "derived:tokens*price"),
                              ("gross_burn_tokens", 50.0, "derived:defillama_burned_fee_revenue/price")]]
    agg = bw.aggregate(pd.DataFrame(rows), pd.DataFrame(), pd.Timestamp("2026-09-28"),
                       gaps=pd.DataFrame(), review=pd.DataFrame()).query("project == 'Ethereum'")
    by = agg.set_index("metric")
    for m in ("actual_buyback_tokens", "actual_buyback_usd"):
        assert by.loc[m, "status"] == "n/a" and "NOTHING IS BOUGHT" in by.loc[m, "note"], m
        assert "section AO" in by.loc[m, "note"]
    assert by.loc["gross_burn_tokens", "status"] == "ok" and by.loc["gross_burn_tokens", "q0"] == 1350.0
    assert "-- AO3." in open("orphan_cleanup.sql").read()

    # NEAR: the gas burn is not the buyback — the route is the buyback wallet's inflow
    assert config.buyback_route("Near")["route"] == "treasury_inflow"
    assert config.relabelled_from("Near", "actual_buyback_tokens") is None


