def test_plume_defillama_fees_is_declared_absent_and_rechecked_weekly(tmp_path):
    """summary/fees/plume answered 400 on every run. store.known_absent() keys on 404 and on
    (source, project) — Plume's other DefiLlama reads succeed — so it never parked. Declared in
    config; skipped while the last attempt failed within 7 days; any success ends it."""
    from datetime import datetime, timedelta, timezone

    import store as storemod
    from fetch.base import FetchOutput
    from fetch.llama import DefiLlama

    st = storemod.Store(tmp_path / "m.db")
    plume = config.PROJECT_BY_NAME["Plume"]
    assert st.declared_absent([plume]) == set(), "no attempt on record: call it"

    def attempt(days_ago, status, msg="plume:dailyFees: HTTP 400 from https://api.llama.fi/x"):
        ts = (datetime.now(timezone.utc) - timedelta(days=days_ago)).strftime("%Y-%m-%dT%H:%M:%SZ")
        st.conn.execute("INSERT INTO run_log(run_id, ts, source, tier, project, rows, status, "
                        "message) VALUES ('r', ?, 'defillama', 1, 'Plume', 0, ?, ?)",
                        (ts, status, msg))
        # an unrelated success on the same (source, project) must not end the skip
        st.conn.execute("INSERT INTO run_log(run_id, ts, source, tier, project, rows, status, "
                        "message) VALUES ('r', ?, 'defillama', 1, 'Plume', 5, 'ok', "
                        "'chain Plume Mainnet tvl')", (ts,))

    attempt(8, "failed")
    assert st.declared_absent([plume]) == set(), "8 days since the last attempt: re-check"
    attempt(2, "failed")
    absent = st.declared_absent([plume])
    assert absent == {("defillama:fees", "Plume")}

    out = FetchOutput()
    DefiLlama(known_absent=absent).fees(plume, 30, out)
    assert [e.status for e in out.log] == ["skipped"] and "KNOWN ABSENT (declared)" in out.log[0].message
    assert "HTTP 400" in out.log[0].message

    attempt(1, "ok", "plume:dailyFees")
    assert st.declared_absent([plume]) == set(), "a success ends the skip on its own"


# =====================================================================================
# 2026-09-28 — the beaconchain hang. Every HTTP call bounded; every source under a budget.
# =====================================================================================
def test_a_retry_after_longer_than_the_cap_fails_at_once_instead_of_sleeping(monkeypatch):
    """beaconcha.in's limiter (ratelimit/ratelimit.go) sets Retry-After to the seconds until its
    hourly or monthly quota resets. Http honoured it uncapped and the run slept for over an hour."""
    from fetch import base

    naps = []
    monkeypatch.setattr(base.time, "sleep", lambda s: naps.append(s))

    class R:
        status_code = 429
        headers = {"Retry-After": "3600", "x-ratelimit-remaining-month": "0"}

    h = base.Http(retries=2)
    monkeypatch.setattr(h.s, "get", lambda *a, **k: R())
    try:
        h.get("https://beaconcha.in/api/v1/ethstore/latest")
        raise AssertionError("must not return")
    except base.RateLimited as e:
        assert "3,600s" in str(e) and "NOT waited" in str(e) and "remaining-month" in str(e)
    assert naps == [], f"nothing is slept when the server asks for longer than the cap: {naps}"

    # a short Retry-After is still honoured, and a long backoff is capped
    class Short:
        status_code = 503
        headers = {"Retry-After": "5"}

    class Ok:
        status_code = 200
        headers = {}

        def json(self):
            return {"ok": 1}

        def raise_for_status(self):
            pass

    seq = iter([Short(), Ok()])
    monkeypatch.setattr(h.s, "get", lambda *a, **k: next(seq))
    assert h.get("https://x.example/") == {"ok": 1} and naps == [5.0]


def test_every_http_call_in_fetch_passes_an_explicit_timeout():
    """A2: no requests/urllib/httpx call in fetch/ without a timeout, and web3 providers carry
    one in request_kwargs. Static, so a new call without one fails here before it can hang."""
    import ast
    from pathlib import Path

    verbs = {"get", "post", "put", "delete", "head", "request", "patch", "urlopen"}
    offenders = []
    for path in sorted(Path("fetch").glob("*.py")):
        tree = ast.parse(path.read_text())
        for node in ast.walk(tree):
            if not isinstance(node, ast.Call):
                continue
            f = node.func
            name = f.attr if isinstance(f, ast.Attribute) else getattr(f, "id", "")
            owner = ast.unparse(f.value) if isinstance(f, ast.Attribute) else ""
            kw = {k.arg for k in node.keywords}
            # the HTTP clients fetch/ uses: the requests module, Http's session (self.s), and
            # urllib/httpx should either ever appear
            if name in verbs and (owner in ("requests", "httpx", "urllib.request", "self.s")
                                  or name == "urlopen"):
                if "timeout" not in kw:
                    offenders.append(f"{path}:{node.lineno} {ast.unparse(node)[:80]}")
            if name == "HTTPProvider":
                rk = next((k.value for k in node.keywords if k.arg == "request_kwargs"), None)
                if rk is None or "timeout" not in ast.unparse(rk):
                    offenders.append(f"{path}:{node.lineno} HTTPProvider without a timeout")
    assert not offenders, "HTTP calls without an explicit timeout:\n" + "\n".join(offenders)
    # and the backstop: a requests call that forgets one still gets the default
    import requests.adapters
    from fetch import base
    assert requests.adapters.HTTPAdapter.send.__name__ == "_instrumented_send"
    assert base.DEFAULT_TIMEOUT[0] <= 10 and base.DEFAULT_TIMEOUT[1] <= 60


def test_a_source_that_hangs_is_abandoned_at_its_budget_and_the_rest_merge_in_tier_order(monkeypatch):
    """A3: the dispatcher, not the adapter, enforces each source's wall clock. A hung source is
    abandoned with what it produced so far, gapped 'tier timed out', and the others are merged
    in TIER_ORDER however they finished — the collision guard stays deterministic."""
    import threading

    import fetch
    from fetch.base import point

    release = threading.Event()

    class Hangs:
        def run(self, projects, window_days, out):
            out.add(point("Ethereum", "price_usd", 1.0, "hangs", 1, pd.Timestamp("2026-09-20")),
                    "hangs", "Ethereum", "first figure", 1)
            release.wait(30)            # the beaconchain hang, in miniature

    class Slow:
        def run(self, projects, window_days, out):
            import time
            time.sleep(0.6)
            out.add(point("Ethereum", "tx_count", 5.0, "slow", 1, pd.Timestamp("2026-09-20")),
                    "slow", "Ethereum", "slow", 1)

    class Fast:
        def run(self, projects, window_days, out):
            out.add(point("Ethereum", "tx_count", 7.0, "fast", 2, pd.Timestamp("2026-09-20")),
                    "fast", "Ethereum", "fast", 2)

    # the hung source is named etherscan_supply so the timeout can be ATTRIBUTED to exactly what it
    # serves (served_by, 2026-09-28). (It was beaconchain, until beaconcha.in left routine runs.)
    monkeypatch.setattr(fetch, "TIER_ORDER", [("slow", 1, lambda c: Slow()),
                                              ("etherscan_supply", 1, lambda c: Hangs()),
                                              ("fast", 2, lambda c: Fast())])
    monkeypatch.setitem(fetch.TIER_BUDGET_S, "etherscan_supply", 1.5)
    import time as _t
    t0 = _t.monotonic()
    out = fetch.fetch_all([config.PROJECT_BY_NAME["Ethereum"]], 30)
    release.set()
    assert _t.monotonic() - t0 < 10, "the run must not wait on the hung source"
    df = out.frame()
    assert set(df.source) >= {"hangs", "slow"}, "what the hung source produced is kept"
    tx = df[(df.metric == "tx_count")]
    assert list(tx.source) == ["slow"], \
        "tier 1 'slow' finished LAST but was declared first, so it wins the collision"
    msg = next(e.message for e in out.log if e.source == "etherscan_supply" and e.status == "failed")
    assert "TIER TIMED OUT after 2s" in msg or "TIER TIMED OUT after 1s" in msg, msg
    assert out.timed_out["etherscan_supply"][0] == 1
    timed = {(g["project"], g["metric"]) for g in out.gaps
             if g["reason"].startswith("TIER TIMED OUT this run")}
    from fetch.gaps import served_by
    serves = {("Ethereum", m) for m in served_by("etherscan_supply", config.PROJECT_BY_NAME["Ethereum"])}
    assert timed and timed <= serves, f"only what the timed-out source SERVES is attributed to it: {timed}"


def test_the_heartbeat_names_the_source_and_host_of_a_long_wait(monkeypatch):
    """A4: a call outstanding for more than 30s is logged with its source and host."""
    import threading

    import fetch
    from fetch import base

    started, done = threading.Event(), threading.Event()

    def worker():
        with base.waiting_on("GET beaconcha.in"):
            started.set()
            done.wait(5)

    t = threading.Thread(target=worker, name="beaconchain")
    t.start()
    started.wait(2)
    try:
        hb = fetch.Heartbeat(every=0.0)
        lines = hb.beat()
        assert any("[beaconchain] GET beaconcha.in" in line for line in lines), lines
        assert fetch.HEARTBEAT_AFTER_S == 30.0
    finally:
        done.set()
        t.join()
    assert not [x for x in base.inflight() if x[0] == "beaconchain"], "cleared when it returns"


def test_nearblocks_three_two_credit_calls_do_not_wait_and_the_v3_stats_cost_one(_nearblocks_fake_clock):
    """B2, 2026-09-28: 6 credits per rolling 60s holds three 2-credit calls. The ~59s waits in the
    log were (a) the 4th and 7th pages of a 7-page read — unavoidable at 6/min, now gone because a
    routine read is one page — and (b) the v3 stats charged 4 credits each for limit=100 when
    NearBlocks bills ceil(per_page/25) with per_page defaulting to 25, i.e. 1."""
    from fetch import nearblocks

    class H:
        def get(self, url, params=None, headers=None):
            return {}

    nb = nearblocks.NearBlocks(http=H())
    for _ in range(3):
        nb._get("https://api.nearblocks.io/v1/account/x/txns", {"per_page": 50}, "k")
    assert _nearblocks_fake_clock == [], f"three 2-credit calls must not wait: {_nearblocks_fake_clock}"
    nb2 = nearblocks.NearBlocks(http=H())
    for _ in range(6):
        nb2._get("https://api.nearblocks.io/v3/txn-stats", {"limit": 100}, "k")
    assert _nearblocks_fake_clock == [], "six v3 calls are six credits, not twenty-four"
    nb2._get("https://api.nearblocks.io/v3/txn-stats", {"limit": 100}, "k")
    assert len(_nearblocks_fake_clock) == 1, "the seventh credit in a minute does wait"


def test_nearblocks_buyback_is_incremental_newest_first_and_daily_stats_run_once_a_day(monkeypatch):
    """B1/B3: the first read pages the window newest-first; the next run makes ONE call and stops
    at the newest transaction already seen, and still emits the whole window from the kept
    per-day totals. The v3 stats are skipped once yesterday is stored — and are NOT a gap."""
    import pytest

    from fetch import nearblocks, scrape
    from fetch.base import FetchOutput, today

    monkeypatch.setenv("NEARBLOCKS_API_KEY", "nb-secret-123")
    monkeypatch.setattr(scrape, "robots_verdict", lambda url: (True, "test"))
    E = 10 ** 24

    def tx(day_ago, h, near, sender="u.near"):
        ts = int((today() - pd.Timedelta(days=day_ago) + pd.Timedelta(hours=1)).value)
        return {"predecessor_account_id": sender, "block_timestamp": str(ts), "transaction_hash": h,
                "actions": [{"action": "TRANSFER", "deposit": str(near * E)}]}

    history = [tx(3, "c", 3), tx(5, "b", 2), tx(6, "a", 1)]            # newest first

    class H:
        def __init__(self, txns):
            self.txns, self.calls = txns, []

        def get(self, url, params=None, headers=None):
            self.calls.append(dict(params or {}))
            if "/v1/account/" not in url:
                return {"data": []}
            assert params["order"] == "desc"
            start = int(params.get("cursor") or 0)
            page = self.txns[start:start + 2]
            nxt = start + 2 if start + 2 < len(self.txns) else None
            return {"cursor": nxt and str(nxt), "txns": page}

    near = config.PROJECT_BY_NAME["Near"]
    h1 = H(history)
    out1 = FetchOutput()
    nearblocks.NearBlocks(http=h1).run([near], 35, out1)
    flows1 = [c for c in h1.calls if "action" in c]
    assert len(flows1) == 2, "first read: the whole window, newest first"
    got1 = out1.frame().query("metric == 'actual_buyback_tokens'")
    assert sorted(got1.value) == pytest.approx([1.0, 2.0, 3.0])

    h2 = H([tx(1, "d", 7)] + history)
    yesterday = today() - pd.Timedelta(days=1)
    out2 = FetchOutput()
    nearblocks.NearBlocks(http=h2, last_dates={("Near", "tx_count"): yesterday,
                                                ("Near", "active_addresses"): yesterday}).run([near], 35, out2)
    assert len(h2.calls) == 1, f"a routine run makes ONE call: {h2.calls}"
    got2 = out2.frame().query("metric == 'actual_buyback_tokens'")
    import pytest
    assert sorted(got2.value) == pytest.approx([1.0, 2.0, 3.0, 7.0]), "the window is re-emitted from kept totals"
    assert out2.current == {("Near", "tx_count"), ("Near", "active_addresses")}
    from fetch.gaps import detect
    gaps = detect([near], out2.frame(), out2.current, {}, [])
    assert not [g for g in gaps if g["metric"] in ("tx_count", "active_addresses")], \
        "a daily aggregate skipped because yesterday is stored is not a gap"


def test_maple_stores_every_visible_monthly_buyback_on_a_routine_run(monkeypatch, tmp_path):
    """Jake, 2026-09-28: the store held only Aug 2026 ($147,098) — a 30-day window over rows dated
    to month-end kept one of the five the page renders. Every visible month is stored now."""
    from fetch import maple_transparency as mt
