def test_defillama_reuses_the_days_responses_and_runs_its_checks_once_a_day(monkeypatch):
    """C2, 2026-09-28: check_restructure re-requested every dailyFees payload fees() had just
    fetched (~20 duplicate calls), and the restructure/recovery checks and the RWA rebuild ran on
    every run. The Plume check still called its declared-absent 400."""
    from fetch.base import FetchOutput
    from fetch.llama import DefiLlama

    monkeypatch.delenv("TOKEN_METRICS_DAILY_CHECKS", raising=False)
    chart = {"totalDataChart": [[TS1, 100.0], [TS2, 150.0]], "childProtocols": []}
    aave = {"name": "Aave", "defillama_fees_slug": "aave", "defillama_protocol": None,
            "defillama_chain": None, "archetypes": [3]}

    def run():
        dl = DefiLlama()
        dl.http = StubHttp({"/summary/fees/aave": chart})
        dl.run([aave], 30, FetchOutput())
        return [c for c in dl.http.calls if "/summary/fees/aave" in c[0]]

    first = run()
    kinds = [c[1]["dataType"] for c in first]
    assert sorted(kinds) == ["dailyFees", "dailyHoldersRevenue", "dailyRevenue"], \
        f"the restructure check reuses fees()'s dailyFees response: {kinds}"
    assert len(run()) == 3, "same day: fetched as before, the check is simply not re-run"

    plume = config.PROJECT_BY_NAME["Plume"]
    dl = DefiLlama(known_absent={("defillama:fees", "Plume")})
    dl.http = StubHttp({})
    dl.check_restructure(plume, FetchOutput())
    assert dl.http.calls == [], "a declared-absent listing costs no time in the check either"


def test_a_scrape_that_returns_nothing_backs_off_to_weekly_and_robots_is_read_before_chromium(monkeypatch):
    """C4, 2026-09-28: scrape spent 18s for 0 rows — entries that extract nothing were retried
    every run, and Chromium launched before robots.txt was read."""
    from fetch import scrape
    from fetch.base import FetchOutput, today

    entry = {"project": "Pendle", "metric": "locked_tokens_dashboard", "tier": 3,
             "url": "https://api-v2.pendle.finance/core/v1/spendle/data", "method": "xhr",
             "url_contains": "/v1/spendle/data", "json_path": "totalStakedInSpendle"}
    b = scrape._Backoff()
    assert b.waiting(entry) == ""
    b.failed(entry)
    b.failed(entry)            # same day: not a second consecutive failure
    assert b.waiting(entry) == ""
    rec = b._read()[scrape.cache_key(entry)]
    rec["last_try"] = str((today() - pd.Timedelta(days=1)).date())
    b._write({scrape.cache_key(entry): rec})
    b.failed(entry)
    assert "2 consecutive run-days" in b.waiting(entry) and "weekly" in b.waiting(entry)
    b.succeeded(entry)
    assert b.waiting(entry) == ""

    launched = []
    monkeypatch.setattr(scrape, "robots_verdict", lambda url: (False, "a Disallow rule"))
    monkeypatch.setattr(scrape.Scrape, "_browser", lambda self: launched.append(1))
    monkeypatch.setattr(scrape, "load_registry", lambda path: [dict(entry, enabled=True)])
    monkeypatch.setattr(scrape, "cache_read", lambda e: None)
    sc = scrape.Scrape()
    out = FetchOutput()
    sc.run([config.PROJECT_BY_NAME["Pendle"]], 30, out)
    assert launched == [], "no browser for a run whose every live entry robots.txt disallows"
    assert any("robots.txt disallows" in e.message for e in out.log), [e.message for e in out.log]


def test_a_monthly_series_q0_is_three_complete_calendar_months():
    """Jake, 2026-09-28: the day window (asof-90, asof] dropped Maple's June buyback, dated 30 June,
    by one day on 28 September. A declared-monthly series' Q0 is now the three complete months
    before asof's month, annualised x12/3; daily series keep the day window. Each Q0 names its
    basis in the Data tab."""
    import build_workbook as bw

    asof = pd.Timestamp("2026-09-28")
    months = {"2025-09-30": 40_000.0, "2025-11-30": 50_000.0, "2026-06-30": 375_000.0,
              "2026-07-31": 136_768.0, "2026-08-31": 147_098.0}
    rows = [{"date": pd.Timestamp(d), "project": "Maple", "metric": "actual_buyback_usd", "value": v,
             "source": "maple_page", "tier": 3, "is_manual": False, "entered_on": ""}
            for d, v in months.items()]
    rows += [{"date": d, "project": "Chainlink", "metric": "actual_buyback_usd", "value": 1.0,
              "source": "x", "tier": 2, "is_manual": False, "entered_on": ""}
             for d in pd.date_range("2026-06-01", "2026-09-27")]
    out = bw.aggregate(pd.DataFrame(rows), pd.DataFrame(), asof, gaps=pd.DataFrame(),
                       review=pd.DataFrame()).set_index(["project", "metric"])
    m = out.loc[("Maple", "actual_buyback_usd")]
    assert m["q0"] == 658_866.0, m["q0"]
    assert m["q0_basis"] == "3 complete months Jun 2026–Aug 2026"
    assert pd.isna(m["q1"]), "Mar-May 2026 hold no row"
    assert m["y1"] == sum(months.values()), "Y1 = the 12 complete months Sep 2025-Aug 2026"
    c = out.loc[("Chainlink", "actual_buyback_usd")]
    assert c["q0"] == 89.0 and c["q0_basis"] == "trailing 90 days to 2026-09-28"
    R = bw.Refs(100, 10, ["2026-09"])
    # ...over the days of the months HELD (2026-09-29): 3 complete months here = 92 days; the
    # x12/3 fallback only where no coverage is recorded.
    assert m["q0_covered_days"] == 92 and m["q1_covered_days"] == 0
    ann = bw._annualise(R, 5, config.PROJECT_BY_NAME["Maple"], "actual_buyback_usd", "X")
    # EVENTS x CADENCE (Jake, 2026-09-29): Maple's monthly buybacks annualise as the mean month
    # x 12 — the same x4 here, where Q0 holds three monthly events.
    assert ann.startswith("IF(AND(ISNUMBER(") and "*12," in ann, ann
    assert m["q0_events"] == 3
    # Maple at a $240M market cap: 658,866 / 3 x 12 / 240M
    assert abs(658_866.0 * 4 / 240e6 - 0.010981) < 1e-6


def test_no_tab_formula_looks_up_a_metric_that_is_not_defined(tmp_path):
    """33 #N/A on the fixture recalc (2026-09-28): A1 and A2 still looked up staked_tokens (merged
    into locked_tokens in 2bc2e5d) and rwa_xyz_usd (retired, covered by rwa_defillama_usd). A
    retired metric must not be able to leave broken lookups again: every "|metric" key a formula
    MATCHes on is checked against config.METRICS."""
    import re

    import openpyxl

    import build_workbook as bw
    import store as store_mod

    st = store_mod.Store(str(tmp_path / "m.db"))
    out = bw.build_workbook(st, str(tmp_path / "w.xlsx"))
    bw._SCOPE = list(bw.PROJECTS)
    wb = openpyxl.load_workbook(out)
    key = re.compile(r'"\|([A-Za-z0-9_]+)"')
    unknown = {}
    for ws in wb.worksheets:
        for row in ws.iter_rows():
            for c in row:
                if isinstance(c.value, str) and c.value.startswith("="):
                    for m in key.findall(c.value):
                        if m not in config.METRICS:
                            unknown.setdefault(m, f"{ws.title}!{c.coordinate}")
    assert not unknown, f"formulas look up metrics that are not defined: {unknown}"


def test_final_block_timestamps_are_cached_and_recent_ones_are_not():
    """C, 2026-09-28: Sky's Stage 2 dating read one block per burner event on every run. Final
    blocks (at least BURN_CONFIRMATIONS deep) are kept across runs; newer ones are read live."""
    import types

    from fetch import chain as chainmod

    calls = []

    class R(chainmod.ChainReader):
        def web3(self, chain):
            def get_block(n):
                calls.append(n)
                return {"timestamp": 1_700_000_000 + n}
            return types.SimpleNamespace(eth=types.SimpleNamespace(get_block=get_block))

    r1 = R()
    r1.log_safe_block = {"ethereum": 1_000}
    assert r1.block_timestamp("ethereum", 900) == 1_700_000_900
    assert r1.block_timestamp("ethereum", 1_010) == 1_700_001_010
    assert r1.block_timestamp("ethereum", 900) == 1_700_000_900 and calls == [900, 1_010], \
        "memoised within a run"
    r2 = R()
    r2.log_safe_block = {"ethereum": 1_000}
    r2.block_timestamp("ethereum", 900)
    r2.block_timestamp("ethereum", 1_010)
    assert calls == [900, 1_010, 1_010], "the final block comes from disk; the recent one is re-read"


def test_the_workbook_builds_from_a_store_holding_every_read_time_view(tmp_path):
    """Run 20260928T142424Z: fetch fine, BUILD CRASHED — aggregate() hit latest["is_manual"] on a
    view row. The declared-issuance view built NEAR's series from scratch and copied stored columns
    from a derived series that store did not have. The fixture never had that shape (NEAR supply
    with no derived issuance). This store holds every view type, in the shapes that failed."""
    import build_workbook as bw
    import store as store_mod

    st = store_mod.Store(str(tmp_path / "m.db"))
    days = pd.date_range(pd.Timestamp.now("UTC").tz_localize(None).normalize() - pd.Timedelta(days=120),
                         periods=119)

    def rows(project, metric, value, source, dates=days):
        return pd.DataFrame({"date": dates, "project": project, "metric": metric,
                             "value": value, "source": source, "tier": 2})

    st.upsert(pd.concat([
        rows("Near", "total_supply", 1.288e9, "near_rpc"),               # declared view, NO derived
        rows("Near", "locked_tokens", 5.57e8, "near_rpc"),
        rows("Pendle", "holders_revenue_usd", 10_000.0, "defillama"),     # restatement view
        rows("Pendle", "total_supply", 2.8e8, "coingecko"),               # declared view (Pendle)
        rows("Hyperliquid", "gross_burn_tokens", 5_000.0, "hypercore:x:delta"),   # burn = buyback view
        rows("Hyperliquid", "core_burn_tokens", 1_000.0, "hypercore_info:tokenDetails.totalSupply:delta"),
        rows("Hyperliquid", "price_usd", 40.0, "coingecko"),
        rows("Ethereum", "gross_issuance_tokens", 101.0, "derived:d_supply+burn"),  # first-party block
        rows("GEODNET", "pool_release_tokens", 1_000.0, config.POOL_RELEASE_DERIVED_SOURCE),
        rows("GEODNET", "circulating_supply", 462_370_402.0, "coingecko"),       # flat circulating
        pd.DataFrame({"date": pd.to_datetime(["2026-06-30", "2026-07-31", "2026-08-31"]),
                      "project": "Maple", "metric": "actual_buyback_usd",
                      "value": [375_000.0, 136_768.0, 147_098.0], "source": "maple_page", "tier": 3}),
    ], ignore_index=True))
    csv = tmp_path / "overrides.csv"
    csv.write_text("date,project,metric,value,source_note,entered_on\n"
                   f"{days[-1].date()},GEODNET,locked_tokens,3000000,test,{days[-1].date()}\n")
    st.load_overrides_csv(csv)

    # every view's rows carry every stored column
    long = st.load_long()
    groups = {k: g for k, g in long.groupby(["project", "metric"])}
    bw._burn_total_views(groups)            # same order as aggregate()
    bw._relabel_views(groups)
    bw._restatement_views(groups)
    bw._VIEW_BLOCKS.clear()
    bw._issuance_views(groups, days[-1] + pd.Timedelta(days=1))
    for key in [("Near", "gross_issuance_tokens"), ("Pendle", "actual_buyback_usd"),
                ("Hyperliquid", "total_burn_tokens"),
                ("Hyperliquid", "actual_buyback_tokens"), ("Hyperliquid", "actual_buyback_usd")]:
        missing = set(long.columns) - set(groups[key].columns)
        assert not missing, f"{key} view lacks stored columns {missing}"

    try:
        out = bw.build_workbook(st, str(tmp_path / "w.xlsx"))
    finally:
        bw._SCOPE = list(bw.PROJECTS)
    assert pathlib_exists(out)


