def test_near_issuance_is_derived_from_the_block_header_supply_and_the_guard_reads_only_that():
    """A3, 2026-09-28: CoinGecko's NEAR total rose ~0.8M over a window with ~8M of expected
    issuance, so the >10x guard blocked the declared route. The header's total_supply (yocto) is
    read daily; issuance = its delta + burn; the guard's cross-check reads only those rows."""
    import build_workbook as bw
    from fetch import _derive_issuance
    from fetch.base import point
    from fetch.near import NearNode

    near = config.PROJECT_BY_NAME["Near"]
    api = near["node_api"]
    read = next(r for r in api["extra_reads"] if r["kind"] == "near_block_supply")
    nn = NearNode()
    nn._call = lambda api, body=None: ({"result": {"header": {"height": 1, "total_supply":
                                         "1307600000000000000000000000000000"}}}, "rpc")
    out = FetchOutput()
    nn._block_supply(near, api, read, out, pd.Timestamp("2026-09-28"))
    v = out.frame()
    assert v.metric.tolist() == ["total_supply_protocol"] and abs(v.value.iloc[0] - 1_307_600_000) < 1e-3

    out2 = FetchOutput()
    out2.add(point("Near", "total_supply_protocol", 1_307_600_000.0, "near_rpc:block.header.total_supply",
                   2, pd.Timestamp("2026-09-28")), "near_rpc", "Near")
    out2.add(point("Near", "gross_burn_tokens", 5_000.0, "x", 2, pd.Timestamp("2026-09-28")), "x", "Near")
    _derive_issuance(out2, [near], {("Near", "total_supply_protocol"): 1_307_520_000.0},
                     {("Near", "total_supply_protocol"): "2026-09-27"})
    f = out2.frame()
    iss = f[f.metric == "gross_issuance_tokens"]
    assert len(iss) == 1 and abs(iss.value.iloc[0] - 85_000.0) < 1e-3, iss
    assert iss.source.iloc[0].startswith("derived:d_total_supply_protocol+burn")
    assert config.issuance_primary("Near")["observed_source_prefix"] == "derived:d_total_supply_protocol"


def test_world_mobile_emissions_are_the_whitepaper_curve_on_the_calendar_not_evm_minting():
    """A8, Jake 2026-09-28: the four-chain EVM sum rose +41.45M in the week of the 2026-09-20
    Ethereum exploit, against a curve of ~0.7M/week. Observed EVM minting is bridging, not
    emissions. The whitepaper curve S(t) = S0 (t+1)^0.1141 is primary, as a MODEL, evaluated on
    the calendar from t0 = 2022-04-16 (the curve's own implied start), so no stored supply moves
    it — and every consumer reads it, including when the stored series holds the exploit week."""
    import build_workbook as bw

    spec = config.issuance_primary("World Mobile")
    assert spec["kind"] == "declared_curve" and spec["metric"] == "emissions_tokens"
    assert spec["t0"] == "2022-04-16" and "unconfirmed" in spec["source_label"]
    assert spec["source_label"].startswith("model:")
    assert config.PROJECT_BY_NAME["World Mobile"]["observed_minting"]["role"] == "cross_check"

    asof = pd.Timestamp("2026-09-28")
    days = pd.date_range("2026-06-01", "2026-09-27")
    stored = [{"date": d, "project": "World Mobile", "metric": "emissions_tokens",
               "value": 41_451_547.0 if d == pd.Timestamp("2026-09-21") else 100_000.0,
               "source": "derived:d_total_supply_gross|PARTIAL:delta", "tier": 2,
               "is_manual": False, "entered_on": ""} for d in days]
    groups = {("World Mobile", "emissions_tokens"): pd.DataFrame(stored)}
    bw._VIEW_BLOCKS.clear()
    bw._issuance_views(groups, asof)
    view = groups[("World Mobile", "emissions_tokens")]
    assert (view["source"] == spec["source_label"]).all()
    assert view["date"].max() == asof - pd.Timedelta(days=1)

    c = config.issuance_curve("World Mobile")
    k, s0 = float(c["k"]), config.issuance_curve_s0(c)
    q0 = view[view["date"] > asof - pd.Timedelta(days=90)]["value"].sum()
    t = lambda d: (pd.Timestamp(d) - pd.Timestamp("2022-04-16")).days / 365.25  # noqa: E731
    # rows dated 07-01 .. 09-27, each S(next day) - S(day): exactly S(09-28) - S(07-01)
    exact = s0 * ((t(asof) + 1) ** k - (t(asof - pd.Timedelta(days=89)) + 1) ** k)
    assert abs(q0 - exact) / exact < 1e-9
    week = q0 / 89 * 7
    assert 650_000 < week < 750_000, f"{week:,.0f}/week — Jake's ~0.7M/week"
    assert 41_000_000 not in set(view["value"].round()), "the exploit week is not issuance"


def test_ethereum_burn_and_issuance_come_from_etherscan_ethsupply2(monkeypatch):
    """A9, Jake 2026-09-28: one free-tier call (stats/ethsupply2) gives cumulative BurntFees and
    the supply components. burn = d(BurntFees); issuance = d(EthSupply + Eth2Staking), reached as
    d(total_supply_protocol) + burn. The key never reaches a log; a refusal quotes Etherscan."""
    from fetch import _derive_issuance
    from fetch.base import FetchOutput, today
    from fetch.etherscan_supply import EtherscanSupply

    key = "es-secret-789"
    monkeypatch.setenv("ETHERSCAN_API_KEY", key)
    wei = 10 ** 18
    body = {"status": "1", "message": "OK", "result": {
        "EthSupply": str(120_000_000 * wei), "Eth2Staking": str(6_000_000 * wei),
        "BurntFees": str(4_600_000 * wei), "WithdrawnTotal": str(30_000_000 * wei)}}

    class _Http:
        def __init__(self, b):
            self.b, self.calls = b, []

        def get(self, url, params=None, headers=None):
            self.calls.append((url, dict(params or {})))
            return self.b

    eth = config.PROJECT_BY_NAME["Ethereum"]
    prior_day = str((today() - pd.Timedelta(days=1)).date())
    prior = {("Ethereum", "burn_cumulative_tokens"): 4_599_000.0,
             ("Ethereum", "total_supply_protocol"): 121_398_000.0}
    dates = {k: prior_day for k in prior}
    a = EtherscanSupply(prior_dates=dates, prior_delta=prior)
    a.http = _Http(body)
    out = FetchOutput()
    a.run([eth], None, out)
    url, params = a.http.calls[0]
    assert url == "https://api.etherscan.io/v2/api" and params["action"] == "ethsupply2"
    assert params["chainid"] == 1 and params["module"] == "stats"
    df = out.frame().set_index("metric")
    assert df.loc["burn_cumulative_tokens", "value"] == 4_600_000.0
    assert df.loc["total_supply_protocol", "value"] == 121_400_000.0, "EthSupply + Eth2Staking - BurntFees"
    assert df.loc["gross_burn_tokens", "value"] == 1_000.0
    assert str(df.loc["gross_burn_tokens", "source"]).startswith("etherscan:ethsupply2.BurntFees")
    assert key not in " ".join(e.message for e in out.log)

    # issuance = d(total_supply_protocol) + burn = 2,000 + 1,000 = d(EthSupply + Eth2Staking)
    _derive_issuance(out, [eth], prior, dates)
    iss = out.frame().query("metric == 'gross_issuance_tokens'")
    assert list(iss["value"]) == [3_000.0], iss
    assert str(iss["source"].iloc[0]).startswith("derived:d_total_supply_protocol+burn")
    assert str(iss["source"].iloc[0]).startswith(config.issuance_primary("Ethereum")["source_prefix"])

    # the stitch from the DefiLlama derivation to d(BurntFees) is DECLARED, so it is not blanked
    import build_workbook as bw
    points = ("derived:defillama_burned_fee_revenue/price", "etherscan:ethsupply2.BurntFees")
    spans = {points[0]: (pd.Timestamp("2026-07-01"), pd.Timestamp("2026-09-28")),
             points[1]: (pd.Timestamp("2026-09-29"), pd.Timestamp("2026-09-30"))}
    assert bw.handover_refusal("Ethereum", "gross_burn_tokens", points, spans) is None
    overlap = {points[0]: spans[points[0]], points[1]: (pd.Timestamp("2026-09-28"), pd.Timestamp("2026-09-30"))}
    assert "OVERLAP" in bw.handover_refusal("Ethereum", "gross_burn_tokens", points, overlap)
    # beaconcha.in was DROPPED entirely (2026-10-01)
    assert "beaconchain" not in eth and eth["beaconchain_dropped"]["decided"] == "Jake, 2026-10-01"

    # a refusal (plan, rate limit, bad key) stores nothing and quotes Etherscan, scrubbed
    a2 = EtherscanSupply()
    a2.http = _Http({"status": "0", "message": "NOTOK", "result": f"Invalid API Key {key}"})
    out2 = FetchOutput()
    a2.run([eth], None, out2)
    assert out2.frame().empty
    reasons = " ".join(g["reason"] for g in out2.gaps)
    assert "NOTOK" in reasons and key not in reasons and "***" in reasons


def test_geodnet_release_is_inflow_minus_the_change_in_daily_balances_in_wei(tmp_path):
    """B1, 2026-09-28: release(D) = external inflow(D) - d(combined balance over D) - sends to
    burn/zero, all integers. A hop between the two wallets cancels; a burn send is not release;
    a balance that rose by more than every inflow refuses the whole series."""
    from fetch.balance_flow import BalanceFlow
    from fetch.base import FetchOutput, today
    from fetch.explorer import TRANSFER_TOPIC, pad_address
    from fetch.logcache import LogCache

    spec = config.PROJECT_BY_NAME["GEODNET"]["balance_flows"][0]
    w1, w2 = (h.lower() for h in spec["holders"])
    dead = spec["exclude_counterparties"][0].lower()
    ext = "0x" + "ab" * 20
    e18 = 10 ** 18
    t0 = today() - pd.Timedelta(days=3)
    # one block per hour: block n has timestamp t0 + n*3600 (block 0 = t0 - ... is fine)
    base_ts = int((t0 - pd.Timedelta(days=1)).timestamp())
    blk = lambda d: int((pd.Timestamp(d).timestamp() - base_ts) // 3600)  # noqa: E731
    head = blk(today()) + 5

    def bal_at(b, w, bump=0):
        # w1: 1,000 at start of t0; +500 inflow on t0, -300 paid out on t0; on t0+1 sends
        # 100 to w2 (hop) and 50 to dead, pays out 200. w2 holds 0 then the 100 hop.
        # balanceOf at B(D) - 1 is the balance at the START of D
        d0, d1 = blk(t0), blk(t0 + pd.Timedelta(days=1))
        if w == w1:
            return (1_000 if b < d0 else 1_200 if b < d1 else 850 + bump) * e18
        return (0 if b < d1 else 100) * e18

    class Fn:
        def __init__(self, v):
            self.v = v

        def call(self, block_identifier=None):
            return self.v(block_identifier) if callable(self.v) else self.v

    class Reader:
        bump = 0

        def web3(self, chain):
            class E:
                block_number = head

                @staticmethod
                def get_block(n):
                    return {"timestamp": base_ts + n * 3600}
            return type("W", (), {"eth": E})()

        def erc20(self, chain, token):
            r = self

            class F:
                @staticmethod
                def decimals():
                    return Fn(18)

                @staticmethod
                def balanceOf(h):
                    return Fn(lambda b: bal_at(b, h.lower(), r.bump))
            return type("C", (), {"functions": F})()

        def checksum(self, a):
            return a

    def log(b, frm, to, amt, i):
        return {"blockNumber": b, "logIndex": i, "transactionHash": f"0x{b:x}{i}",
                "timeStamp": base_ts + b * 3600, "data": hex(amt * e18),
                "topics": [TRANSFER_TOPIC, pad_address(frm), pad_address(to)]}

    d0 = blk(t0)
    events = [log(d0 + 2, ext, w1, 500, 0),                  # external inflow on t0
              log(d0 + 30, w1, w2, 100, 1),                  # hop on t0+1
              log(d0 + 31, w1, dead, 50, 2)]                 # burn send on t0+1

    class Ex:
        def get_logs(self, chain_id, token, topics, start, to):
            want = [t.lower() if t else None for t in topics]
            got = [e for e in events if start <= e["blockNumber"] <= to
                   and (want[1] is None or e["topics"][1] == want[1])
                   and (want[2] is None or e["topics"][2] == want[2])]
            return got, {"explorer": "fake", "requests": 1, "refused": []}

    p = dict(config.PROJECT_BY_NAME["GEODNET"])
    p["balance_flows"] = [dict(spec, days=3)]
    reader = Reader()
    out = FetchOutput()
    BalanceFlow(reader=reader, explorer=Ex(), cache=LogCache(tmp_path), unbounded=True).run([p], None, out)
    got = out.frame().query("metric == 'pool_release_tokens'").set_index("date")["value"]
    # t0:   in 500, balance 1,000 -> 1,200: out 300
    # t0+1: in 0 (the hop is internal), 1,200 -> 950 combined: out 250, of which 50 burned -> 200
    assert got[t0] == 300.0 and got[t0 + pd.Timedelta(days=1)] == 200.0, got
    assert list(out.frame()["source"].unique()) == ["balance_flow:mining_wallets_release"]
    assert config.issuance_primary("GEODNET")["source_prefix"] == "balance_flow:mining_wallets_release"

    # a balance that rose with no inflow to explain it: refused, nothing stored
    reader.bump = 400
    out2 = FetchOutput()
    BalanceFlow(reader=reader, explorer=Ex(), cache=LogCache(tmp_path / "b"), unbounded=True).run([p], None, out2)
    assert out2.frame().empty and "inflow event is missing" in out2.gaps[0]["reason"]


