def test_sky_purchases_are_pair_transfers_inside_flapper_exec_transactions(tmp_path):
    """Jake's run 2026-09-29: Sky A3 read 0 — the scan counted transfers FROM THE FLAPPER, but
    FlapperUniV2SwapOnly's swap pays the receiver FROM THE PAIR. Counted now: pair -> Pause Proxy
    transfers in a transaction where the flapper emitted Exec(lot, bought); an unrelated pair
    transfer is not; and the counted total must equal sum(Exec.bought) to the wei."""
    from fetch.explorer import TRANSFER_TOPIC, pad_address
    from fetch.logcache import LogCache
    from fetch.logscan import LogScan

    spec = next(s for s in config.PROJECT_BY_NAME["Sky"]["log_scans"] if s["key"] == "flapper_purchases")
    pair, proxy = spec["count_from"][0].lower(), spec["holders"][0].lower()
    rq = spec["require_tx_event"]
    e18 = 10 ** 18
    from eth_utils import keccak
    BURN = "0x" + keccak(text="Burn(address,uint256,uint256,address)").hex()

    def tr(tx, frm, amt, blk):
        return {"transactionHash": tx, "logIndex": 1, "blockNumber": blk, "timeStamp": 1_790_000_000 + blk,
                "data": hex(amt * e18), "topics": [TRANSFER_TOPIC, pad_address(frm), pad_address(proxy)]}

    def ex(tx, lot, bought, blk):
        return {"transactionHash": tx, "logIndex": 0, "blockNumber": blk, "timeStamp": 1_790_000_000 + blk,
                "data": "0x" + format(lot * e18, "064x") + format(bought * e18, "064x"),
                "topics": [rq["topic0"]]}

    runs = []

    def run(execs):
        runs.append(1)
        ins = [tr("0xaa", pair, 1_000_000, 10), tr("0xbb", pair, 500, 11)]   # 0xbb: no Exec

        class Ex:
            def configured(self, cid):
                return True

            def get_logs(self, cid, address, topics, start, to):
                if address.lower() == rq["address"].lower():
                    return execs, {"explorer": "fake", "requests": 1, "refused": []}
                if address.lower() == pair:           # the pair's own Swap / Burn, `to` = proxy
                    burn = [{"transactionHash": "0xbb", "logIndex": 0, "blockNumber": 11,
                             "timeStamp": 1_790_000_011, "data": "0x",
                             "topics": [topics[0], pad_address("0x" + "11" * 20), topics[2]]}]
                    return (burn if topics[0] == BURN else []), {"explorer": "fake", "requests": 1, "refused": []}
                if topics[2] and topics[2].lower() == pad_address(proxy):
                    return ins, {"explorer": "fake", "requests": 1, "refused": []}
                return [], {"explorer": "fake", "requests": 1, "refused": []}

        class Fn:
            def __init__(self, v):
                self.v = v

            def call(self, block_identifier=None):
                return self.v

        class R:
            def web3(self, chain):
                return type("W", (), {"eth": type("E", (), {"block_number": 1_000})})()

            def erc20(self, chain, token):
                return type("C", (), {"functions": type("F", (), {
                    "balanceOf": staticmethod(lambda h: Fn(1_000_500 * e18)),
                    "decimals": staticmethod(lambda: Fn(18))})})()

            def checksum(self, a):
                return a

        out = FetchOutput()
        p = dict(config.PROJECT_BY_NAME["Sky"], log_scans=[spec])
        LogScan(explorer=Ex(), reader=R(), cache=LogCache(tmp_path / f"run{len(runs)}"),
                unbounded=True).run([p], None, out)
        return out

    out = run([ex("0xaa", 60_000, 1_000_000, 10)])
    got = out.frame().query("metric == 'actual_buyback_tokens'")
    assert got["value"].sum() == 1_000_000.0, got
    msg = " ".join(e.message for e in out.log)
    assert "Exec(uint256,uint256)" in msg and "to the wei" in msg
    # the transfer OUTSIDE Exec is named from the pair's own logs, with its windows
    assert "OUTSIDE THE EVENT, BY THE PAIR'S OWN LOGS — LP burn to the holder (pair.burn): 500.00 (1 tx" in msg, msg
    # Jake, 2026-09-29: each kind carries its buyback verdict, and the largest transactions are named
    assert "=> NOT BUYBACK — liquidity removal" in msg and "; largest: 0x" in msg and " burn 500.00" in msg
    assert BURN == "0xdccd412f0b1252819cb1fd330b93224ca42612892bb3f4f789976e6d81936496"
    assert "0xc5A9CaeBA70D6974cBDFb28120C3611Dd9910355" in rq["classify_outside"]["known_senders"]
    bad = run([ex("0xaa", 60_000, 999_999, 10)])
    assert bad.frame().query("metric == 'actual_buyback_tokens'").empty
    assert "does not reconcile" in bad.gaps[-1]["reason"]


def test_a_first_row_dated_the_asof_day_covers_one_day_not_zero():
    """Jake's run 2026-09-29: Hyperliquid's first rewards day (13,964.04 HYPE, dated the run day)
    measured 0 covered days, so the validator yield fell back to x365/90 and read 0.013%. A window
    holding a figure has covered at least one day; over one day it annualises to ~5.1M/yr."""
    import build_workbook as bw

    asof = pd.Timestamp("2026-09-29")
    s = pd.Series([13_964.04], index=[asof])
    assert bw._window_coverage(s, asof - pd.Timedelta(days=90), asof) == (1, 90)
    assert bw._window_coverage(pd.Series(dtype=float), asof - pd.Timedelta(days=90), asof) == (0, 90)
    long = pd.Series([1.0] * 10, index=pd.date_range("2026-09-19", "2026-09-28"))
    assert bw._window_coverage(long, asof - pd.Timedelta(days=90), asof)[0] == 10, "unchanged otherwise"
    assert abs(13_964.04 * 365 / 441_700_000 - 0.01154) < 1e-4


def test_geodnet_a3_buyback_and_a4_burn_read_the_same_stitched_burn():
    """Jake's run 2026-09-29: A3 retirement 2.72% (live days only) vs A4 burn yield 6.65% (Dune
    monthly history + live). The buyback view is the burn row for row, so it inherits the burn's
    declared Dune -> live handover (it was blanked as a measuring-point change), and a Dune monthly
    row whose first-of-month has no price is valued at the month's mean price, not dropped."""
    import build_workbook as bw
    bw._SCOPE = list(bw.PROJECTS)
    asof = pd.Timestamp("2026-09-29")
    rows = []

    def add(d, m, v, src):
        rows.append(dict(date=pd.Timestamp(d), project="GEODNET", metric=m, value=v, source=src,
                         tier=2, is_manual=False, entered_on=""))
    for mth, v in (("2026-07-01", 1.6e6), ("2026-08-01", 1.55e6)):
        add(mth, "gross_burn_tokens", v, "dune:8683175")
    live = "chain:sum(polygon:burn_polygon+solana:burn_solana_token_account):delta"
    for d in pd.date_range("2026-09-22", "2026-09-28"):
        add(d, "gross_burn_tokens", 52_000.0, live)
        add(d, "actual_buyback_tokens", 52_000.0, live + ":as-buyback")
    for d in pd.date_range("2026-07-01", "2026-09-28"):          # NO price on 2026-08-01
        if d != pd.Timestamp("2026-08-01"):
            add(d, "price_usd", 0.18 if d.month == 8 else 0.15, "coingecko")
    assert config.declared_handover("GEODNET", "actual_buyback_tokens") == \
        config.declared_handover("GEODNET", "gross_burn_tokens")
    by = {r["key"]: r for r in bw.aggregate(pd.DataFrame(rows), pd.DataFrame(), asof).to_dict("records")}
    b, t, u = by["GEODNET|gross_burn_tokens"], by["GEODNET|actual_buyback_tokens"], by["GEODNET|actual_buyback_usd"]
    # Q0 = THREE COMPLETE MONTHS (Jun-Aug) while the Polygon+Solana live leg covers under 90 days
    # (Jake's run 2026-09-29: the trailing window dropped July's row, dated 07-01, on its boundary)
    assert t["status"] == "ok" and t["q0"] == b["q0"] == 1.6e6 + 1.55e6, (t["status"], t["q0"])
    # the block is Jun-Aug; only July and August are held, so it covers their 62 days
    assert b["q0_covered_days"] == 62 and "3 complete months Jun 2026–Aug 2026" in b["q0_basis"]
    # August's row, with no price on the 1st, is valued at August's mean price (0.18); the dollars
    # cover the same months as the tokens
    assert abs(u["q0"] - (1.6e6 * 0.15 + 1.55e6 * 0.18)) < 1e-6, u["q0"]
    assert u["q0_covered_days"] == 62


def test_pendle_token_yield_is_pendle_distributed_over_real_plus_virtual():
    """Jake, 2026-09-29: the USD protocol yield (1.15%) divides buy-time spend by today's staked
    value and understates on a rising price. The token yield = PENDLE bought (annualised) / (real +
    virtual) sPENDLE — Pendle's docs: up to 100% of repurchased PENDLE goes to active sPENDLE, and
    reward snapshots include virtual balances. ~4.6M/yr on ~208M -> ~2.2%."""
    import build_workbook as bw

    ty = config.PROTOCOL_YIELD["Pendle"]["token_yield"]
    assert ty["tokens"] == "pendle_distributed_tokens" and ty["epoch_days"] == 14
    assert config.PENDLE_STAKING_PAGE_2026_09_29["total_pendle_staked_headline"] == 93_877_266
    parts = config.PENDLE_STAKING_PAGE_2026_09_29["decomposes_as"]
    assert abs(sum(parts.values()) - 93_877_266) / 93_877_266 < 0.001

    class R:
        def D(self, r, m, w):
            return f"D[{m}:{w}]"

    label, build = bw._token_yield(R())[:2]
    f = str(build(5, config.PROJECT_BY_NAME["Pendle"]))
    assert "D[pendle_distributed_tokens:q0]" in f and "D[pendle_distributed_tokens:q0_events]" in f and "365.25/14" in f and "D[locked_tokens_shares:now]" in f
    assert "D[locked_tokens_virtual:now]" in f and "price_usd" not in f, f
    # TOKENS PRIMARY (2026-09-30): every PROTOCOL_YIELD project gets the token yield — where no
    # token series is declared, holders revenue in tokens at the Q0 AVERAGE price
    sky = str(build(5, config.PROJECT_BY_NAME["Sky"]))
    assert "D[holders_revenue_usd:q0]/D[price_usd:q0]" in sky and "D[locked_tokens:now]" in sky, sky
    aero = str(build(5, config.PROJECT_BY_NAME["Aerodrome"]))
    assert "D[holders_revenue_usd:q0]" in aero and "D[ve_locked_supply_tokens:now]" in aero, aero
    assert label.startswith("PROTOCOL STAKING YIELD (tokens)")
    assert build(5, config.PROJECT_BY_NAME["Fluid"]).startswith("n/a — FLUID staking is not deployed")
    assert abs(4_600_000 / (30_340_000 + 177_780_000) - 0.0221) < 0.001


def test_geodnet_burn_windows_are_complete_months_until_the_summed_leg_covers_them():
    """Jake's run 2026-09-29: GEODNET burn Q0 4,029,999.99 against ~9M, release/burn 2.727x. The
    trailing (07-01, 09-29] window dropped July's Dune row (dated 07-01) and filled September with
    the Polygon-only leg. Until the Polygon + Solana sum covers a window, that window is complete
    months (Dune counts both chains); a month Dune covers keeps only Dune's row, so September's
    Dune row (from October) replaces the Polygon-only days rather than adding to them."""
    import build_workbook as bw
    DUNE, POLY = "dune:8683175", "chain:polygon:burn_polygon:delta"
    SUM = config.GEODNET_BURN_SUM_POINT + ":delta"

    def frame(rows):
        return pd.DataFrame([dict(date=pd.Timestamp(d), project="GEODNET", metric="gross_burn_tokens",
                                  value=v, source=src, tier=2, is_manual=False, entered_on="")
                             for d, v, src in rows])
    base = [("2026-06-01", 3.0e6, DUNE), ("2026-07-01", 3.1e6, DUNE), ("2026-08-01", 3.0e6, DUNE)]
    base += [(d, 35_000.0, POLY) for d in pd.date_range("2026-09-14", "2026-09-27")]
    base += [("2026-09-29", 100_000.0, SUM)]
    assert config.handover_monthly_leg("GEODNET", "gross_burn_tokens") == (DUNE, config.GEODNET_BURN_SUM_POINT)
    assert config.handover_monthly_leg("GEODNET", "actual_buyback_usd") == (DUNE, config.GEODNET_BURN_SUM_POINT)
    assert config.handover_monthly_leg("Uniswap", "gross_burn_tokens") is None

    b = bw.aggregate(frame(base), pd.DataFrame(), pd.Timestamp("2026-09-29")).set_index("key").loc["GEODNET|gross_burn_tokens"]
    assert b["status"] == "ok" and b["q0"] == 9.1e6 and b["q0_covered_days"] == 92, (b["status"], b["q0"])
    assert b["q0_basis"].startswith("3 complete months Jun 2026–Aug 2026") and "covers 1 day(s)" in b["q0_basis"]
    assert b["now"] == 3.0e6 and b["m1"] == 3.1e6 and b["y1"] == 9.1e6

    # October: Dune's September row lands; the Polygon-only September days give way to it
    oct_ = base + [("2026-09-01", 3.2e6, DUNE)] + [(d, 100_000.0, SUM) for d in pd.date_range("2026-09-30", "2026-10-02")]
    b = bw.aggregate(frame(oct_), pd.DataFrame(), pd.Timestamp("2026-10-02")).set_index("key").loc["GEODNET|gross_burn_tokens"]
    assert b["status"] == "ok" and b["q0"] == 3.1e6 + 3.0e6 + 3.2e6, b["q0"]

    # January: the summed leg covers 90+ days, so Q0 is trailing days again (Y1 stays months)
    jan = oct_ + [(d, 100_000.0, SUM) for d in pd.date_range("2026-10-03", "2027-01-05")]
    b = bw.aggregate(frame(jan), pd.DataFrame(), pd.Timestamp("2027-01-05")).set_index("key").loc["GEODNET|gross_burn_tokens"]
    assert b["q0_basis"].startswith("trailing 90 days") and b["q0"] == 90 * 100_000.0, (b["q0_basis"], b["q0"])


def test_ratios_of_flows_divide_rates_over_each_sides_own_covered_days_or_block():
    """Jake's run 2026-09-29: Ethereum A4 BURN ÷ ISSUANCE 15.68x = 3,773.86 ETH of burn over 90
    days / 240.74 ETH of issuance from one reading. Every flow ratio divides per-covered-day rates,
    and is BLOCKED — naming each side's coverage — where either side covers under a week; a
    difference of two window totals is also blocked where the coverages differ materially."""
    import build_workbook as bw

    class R:
        def D(self, r, m, w):
            return f"D[{m}:{w}]"

        def C(self, r, name):
            return f"C[{name}]"
    eth = config.PROJECT_BY_NAME["Ethereum"]
    heads = {h[0]: h for h in bw._a4_headline(R(), lambda r, p, w="q0": f"D[{config.a4_burn_metric(p['name'])}:{w}]", {})}
    f = heads["BURN ÷ ISSUANCE (x) — crossover, on the basis to the left"][1](5, eth)
    assert f.startswith("=IF(OR(") and "BLOCKED — unequal coverage" in f, f
    bm, im = config.a4_burn_metric("Ethereum"), config.issuance_basis("Ethereum")
    for m in (bm, im):
        assert f"D[{m}:q0_covered_days]<{bw.RATE_MIN_DAYS}" in f and f"D[{m}:q0]" in f
    assert f"D[{bm}:q0])/IF(ISNUMBER(D[{bm}:q0_covered_days])" in f, "a rate, not a window sum"
    net = heads["NET SUPPLY CHANGE Q0 (tokens) — self-reported where published, else issuance − burn, on the basis to the left"][1](5, eth)
    assert "ABS(" in net and "BLOCKED" in net, "a difference of sums blocks on unequal spans"
    pct = heads["NET SUPPLY CHANGE, annualised % of circulating (signed; + is net inflation)"][1](5, eth)
    assert "BLOCKED" in pct and f"/D[{im}:q0_covered_days]" in pct and f"/D[{bm}:q0_covered_days]" in pct, \
        "each side annualised over its own covered days, not the difference x365/90"

    # the trajectory of a FLOW compares rates; of a STOCK, values as before
    traj = dict((h[0], h[1]) for h in bw._trajectory(R(), "fees_usd", "Fees"))
    assert "BLOCKED" in traj["Fees Δ3m"](5, eth) and "D[fees_usd:q1_covered_days]" in traj["Fees Δ3m"](5, eth)
    stock = dict((h[0], h[1]) for h in bw._trajectory(R(), "tvl_usd", "TVL"))
    assert "BLOCKED" not in stock["TVL Δ3m"](5, eth)

    # coverage per window, in the Data tab: burn 90 backfilled days, issuance one reading
    rows = [dict(date=d, project="Ethereum", metric="gross_burn_tokens", value=41.0,
                 source="etherscan:ethsupply2.BurntFees:delta", tier=1, is_manual=False, entered_on="")
            for d in pd.date_range("2026-07-01", "2026-09-29")]
    rows.append(dict(date=pd.Timestamp("2026-09-29"), project="Ethereum", metric="gross_issuance_tokens",
                     value=240.74, source="derived:d_supply_gross", tier=2, is_manual=False, entered_on=""))
    out = bw.aggregate(pd.DataFrame(rows), pd.DataFrame(), pd.Timestamp("2026-09-29")).set_index("key")
    b, i = out.loc["Ethereum|gross_burn_tokens"], out.loc["Ethereum|gross_issuance_tokens"]
    assert b["q0_covered_days"] == 90 and b["now_covered_days"] == 30 and b["q1_covered_days"] == 1
    assert i["q0_covered_days"] == 1 < bw.RATE_MIN_DAYS


def test_a_backfill_the_source_did_not_answer_is_not_remembered_as_source_limited(monkeypatch, tmp_path):
    """Jake's run 2026-09-29: Sky's price_usd held 29 days (2026-08-31..09-28) though CoinGecko has
    SKY's whole history, so actual_buyback_usd valued 29 of 729 rows. record() remembered every
    backfilled pair as "nothing older", including a run where the source stored nothing — which
    stopped the year being re-asked for 30 days. Only pairs answered in the run are remembered;
    history_audit wants 365 days of price and can drop a stale memo (look first, --yes to write)."""
    from fetch import backfill as bf
    import history_audit as ha
    monkeypatch.setenv("TOKEN_METRICS_LOGCACHE", str(tmp_path))
    first = {("Sky", "price_usd"): "2026-08-31", ("Sky", "market_cap_usd"): "2026-08-31"}
    bf.record({("Sky", "price_usd"), ("Sky", "market_cap_usd")}, first, answered={("Sky", "market_cap_usd")})
    memo = bf._read()
    assert "Sky|price_usd" not in memo and "Sky|market_cap_usd" in memo
    pairs, _ = bf.plan([config.PROJECT_BY_NAME["Sky"]], first)
    assert ("Sky", "price_usd") in pairs, "not answered -> re-asked next run"

    bf.record({("Sky", "price_usd")}, first)          # an old-style memo, as Jake's cache holds
    assert ha.main(["--forget", "price_usd"]) == 0 and "Sky|price_usd" in bf._read()
    assert ha.main(["--forget", "price_usd", "--yes"]) == 0 and "Sky|price_usd" not in bf._read()
    assert ha.PRICE_DAYS == 365 and config.PROJECT_BY_NAME["Sky"]["net_protocol_surplus_reference"] \
        ["financials_page_2026_09_29"]["a3_buyback_cross_check"]["measured_expected"]["ratio_to_implied"] == 1.13


def test_pendle_epochs_are_read_per_epoch_with_units_checked_against_the_staking_page():
    """Jake, 2026-09-29: sPendleHistoricalData is the per-epoch distribution series (PENDLE per
    epoch) and lastEpochApr is Pendle's own APR, stored as a cross-check. The docs give no units:
    the median epoch / 1e18 must land in the staking page's range or NOTHING is stored. The
    instant-unstake fee goes to Pendle's treasury, not to stakers."""
    import os
    from fetch.base import FetchOutput
    from fetch.pendle_epochs import PendleEpochs
    os.environ["TOKEN_METRICS_IGNORE_ROBOTS"] = "1"
    try:
        p = config.PROJECT_BY_NAME["Pendle"]
        ts = [1_780_000_000 + 14 * 86_400 * i for i in range(4)]
        good = {"lastEpochApr": 0.0231, "sPendleHistoricalData": {
            "timestamps": ts, "buybackAmounts": [str(a * 10**18) for a in (170_000, 350_000, 240_000, 82_545)]}}
        out = FetchOutput()
        PendleEpochs(get=lambda url: good).run([p], None, out)
        f = out.frame()
        ep = f[f.metric == "pendle_distributed_tokens"]
        assert len(ep) == 4 and ep["value"].max() == 350_000.0
        assert f[f.metric == "staking_apr_published"]["value"].iloc[0] == 0.0231
        assert any("UNITS CONFIRMED" in e.message for e in out.log)
        # Jake's run 2026-09-29 14:38: not wei. The payload's scale is found among the DECLARED
        # candidates (plain tokens, 1e-7) and named in the log; a figure fitting none (here USD,
        # ~$1.2M an epoch) is refused, never fitted to the band by a free power-of-ten search.
        for amounts, k in (([170_000, 350_000, 240_000, 82_545], "/10^0"),
                           ([0.017, 0.035, 0.024, 0.0082545], "/10^-7")):
            plain = dict(good, sPendleHistoricalData={"timestamps": ts, "buybackAmounts": amounts})
            o = FetchOutput()
            PendleEpochs(get=lambda url: plain).run([p], None, o)
            e = o.frame().query("metric == 'pendle_distributed_tokens'")
            msg = " ".join(x.message for x in o.log)
            assert len(e) == 4 and abs(e["value"].max() - 350_000) < 1e-6, k
            assert "DECLARED /10^18 DID NOT FIT" in msg and f"the payload's scale is {k}" in msg
            assert "last complete epoch 82,545 PENDLE" in msg
        bad = dict(good, sPendleHistoricalData={"timestamps": ts, "buybackAmounts": [1_200_000, 900_000, 1_500_000, 400_000]})
        out2 = FetchOutput()
        PendleEpochs(get=lambda url: bad).run([p], None, out2)
        assert out2.frame().query("metric == 'pendle_distributed_tokens'").empty
        assert "UNITS NOT CONFIRMED" in " ".join(e.message for e in out2.log)
    finally:
        os.environ.pop("TOKEN_METRICS_IGNORE_ROBOTS", None)
    assert "TREASURY" in config.PENDLE_STAKING_PAGE_2026_09_29["instant_unstake_fee_to"]
    assert config.METRICS["staking_apr_published"]["sanity_max"] == 1.0, "a percent is rejected, not stored x100"


def test_archive_backfill_reads_state_at_each_days_first_block_and_never_overwrites(tmp_path, monkeypatch):
    """Jake, 2026-09-29: state-based series were SOURCE-LIMITED only because their reads started in
    September. archive_backfill reads the same contracts at the first block of each UTC day (same
    source string + `archive`), writes only empty keys, refuses a day whose stored neighbour was
    read from another measuring point, differences the burn stock into flows, and lists what
    cannot be backfilled with the reason."""
    import store as store_mod
    from fetch import archive as ar
    from fetch.base import today, _measuring_point
    monkeypatch.setenv("TOKEN_METRICS_LOGCACHE", str(tmp_path))
    t0 = int((today() - pd.Timedelta(days=400)).tz_localize("UTC").timestamp())

    class Eth:
        block_number = 400 * 24 + 10

        def get_block(self, n):
            return {"timestamp": t0 + n * 3600}              # one block an hour

        def get_balance(self, a, block_identifier=None):
            return 0

    class Reader(StubReader):
        def __init__(self):
            super().__init__(symbol="UNI")
            self.at_block, self.calls = {}, []

        def web3(self, chain):
            return type("W", (), {"eth": Eth()})()

        def scaled(self, chain, address, call, *args, **kw):
            b = self.at_block[chain]
            self.calls.append(b)
            return 111_000_000.0 + b if args else 1e9        # burn balance grows with the block

    p = dict(config.PROJECT_BY_NAME["Uniswap"])
    p["contracts"] = {k: v for k, v in p["contracts"].items() if k in ("token", "burn_dead")}
    monkeypatch.setitem(config.PROJECT_BY_NAME, "Uniswap", p)
    st = store_mod.Store(tmp_path / "m.db")
    y = today() - pd.Timedelta(days=1)
    live = pd.DataFrame([{"date": y, "project": "Uniswap", "metric": "burn_address_balance",
                          "value": 111_950_000.0, "source": "chain:ethereum:burn_dead", "tier": 2}])
    st.upsert(live)
    bf = ar.ArchiveBackfill(st, [p], budget_s=60, reader=Reader(), days=5)
    ok, no = bf.targets({"ethereum"})
    assert ok["Uniswap"] == {"burn_address_balance", "total_supply_gross"} and not no
    res = bf.run({"ethereum"})
    rows = st.conn.execute("SELECT date, value, source FROM metrics WHERE project='Uniswap' AND "
                           "metric='burn_address_balance' ORDER BY date").fetchall()
    assert len(rows) == 5, rows
    assert dict((d, v) for d, v, _ in rows)[str(y.date())] == 111_950_000.0, "the live row is never overwritten"
    arch = [r for r in rows if r[0] != str(y.date())]
    assert all(s == "chain:ethereum:burn_dead:archive" and _measuring_point(s) == "chain:ethereum:burn_dead"
               for _, _, s in arch)
    # each archive read is AT the first block of its day (block n has timestamp t0 + n hours)
    for d, v, _ in arch:
        b = int(v - 111_000_000)
        day0 = int(pd.Timestamp(d).tz_localize("UTC").timestamp())
        assert t0 + b * 3600 >= day0 > t0 + (b - 1) * 3600
    assert res["flows"].get(("Uniswap", "gross_burn_tokens")), res
    # another measuring point beside a missing day refuses it, with the reason
    st2 = store_mod.Store(tmp_path / "m2.db")
    st2.upsert(live.assign(source="chain:ethereum:fire_pit"))
    res2 = ar.ArchiveBackfill(st2, [p], budget_s=60, reader=Reader(), days=5).run({"ethereum"})
    assert "fire_pit" in res2["refused"][("Uniswap", "burn_address_balance")]
    # what cannot be backfilled says why
    _, no = ar.ArchiveBackfill(st, [config.PROJECT_BY_NAME["Sky"], config.PROJECT_BY_NAME["World Mobile"]],
                               reader=Reader()).targets({"ethereum", "arbitrum", "bsc", "base"})
    why = {(n, m): w for n, m, w in no}
    assert "event-log read" in why[("Sky", "burn_address_balance")]
    assert "spl_mint" in why[("World Mobile", "total_supply_gross")]


def test_a_month_the_full_daily_leg_holds_whole_beats_the_monthly_row():
    """Once archive_backfill has written the Polygon + Solana sum for every day of a month, those
    daily rows are the same burn at daily resolution: the Dune monthly row gives way to them (and
    still wins a month the daily leg only part-covers)."""
    import build_workbook as bw
    SUM = config.GEODNET_BURN_SUM_POINT + ":archive:delta"
    rows = [("2026-07-01", 3.1e6, "dune:8683175"), ("2026-08-01", 3.0e6, "dune:8683175")]
    rows += [(d, 100_000.0, SUM) for d in pd.date_range("2026-08-01", "2026-08-31")]
    rows += [(d, 100_000.0, SUM) for d in pd.date_range("2026-07-20", "2026-07-31")]
    g = pd.DataFrame([dict(date=pd.Timestamp(d), project="GEODNET", metric="gross_burn_tokens", value=v,
                           source=s, tier=2, is_manual=False, entered_on="") for d, v, s in rows])
    groups = {("GEODNET", "gross_burn_tokens"): g}
    bw._monthly_leg_views(groups)
    out = groups[("GEODNET", "gross_burn_tokens")]
    by = out.groupby(out["date"].dt.to_period("M"))["value"].sum()
    assert by[pd.Period("2026-08")] == 31 * 100_000.0, "August: the whole daily leg, not Dune"
    assert by[pd.Period("2026-07")] == 3.1e6, "July: Dune, the daily leg holds only 12 days"


def test_solana_account_history_gives_the_balance_at_each_day_start(tmp_path):
    """2d (Jake, 2026-09-29): GEODNET's Solana burn account history from its own transactions —
    getSignaturesForAddress back to the window start, each transaction's post-balance for this
    account (by its index in the account keys). A day's value is the balance after the last
    transaction before that day starts; a fall refuses the series (a sink never falls)."""
    from fetch.archive import SolanaAccountHistory
    acct = "5SBfxBdqsCM1SJZGQkf9Y74EFmUfzs8LGDjBZUjZGnED"
    d0 = int(pd.Timestamp("2026-09-01").tz_localize("UTC").timestamp())
    txs = {"s3": (d0 + 2 * 86_400 + 60, 150, 200), "s2": (d0 + 86_400 + 60, 100, 150),
           "s1": (d0 + 60, 0, 100)}

    class RPC:
        def call(self, method, params):
            if method == "getSignaturesForAddress":
                if params[1].get("before"):
                    return []
                return [{"signature": s, "blockTime": v[0]} for s, v in txs.items()]
            t, pre, post = txs[params[0]]

            def bal(a):
                return [{"accountIndex": 1, "uiTokenAmount": {"amount": str(a * 10**9)}}]
            return {"blockTime": t, "transaction": {"message": {"accountKeys": [{"pubkey": "x"}, {"pubkey": acct}]}},
                    "meta": {"preTokenBalances": bal(pre), "postTokenBalances": bal(post)}}
    h = SolanaAccountHistory(rpc=RPC(), account=acct, decimals=9, root=tmp_path, pace_s=0)
    done, note = h.fill(d0 - 86_400, deadline=__import__("time").monotonic() + 30)
    assert done and "3 transaction(s) read" in note
    days = [pd.Timestamp(f"2026-09-0{i}") for i in (1, 2, 3, 4)]
    got = h.daily(days)
    assert [got[d] for d in days] == [0.0, 100.0, 150.0, 200.0]
    h.state["sigs"]["s4"] = [d0 + 3 * 86_400, 200, 190]
    with __import__("pytest").raises(ValueError, match="FELL"):
        h.daily(days)


def test_near_archive_reads_header_supply_and_stake_at_the_first_block_of_the_day(tmp_path):
    """2c: NEAR's archival RPC — the first block at or after the day's start (heights may be
    skipped), header.total_supply, and validators at that block, sourced like the live reads."""
    from fetch.archive import NearArchive
    from fetch.base import _measuring_point
    t_day = int(pd.Timestamp("2026-06-01").tz_localize("UTC").timestamp()) * 10**9
    GEN = 9_820_210

    class Http:
        def post(self, url, json_body):
            m, prm = json_body["method"], json_body["params"]
            if m == "block":
                h = 200_000_000 if prm.get("finality") else prm["block_id"]
                if h == 150_000_001:
                    return {"error": {"cause": {"name": "UNKNOWN_BLOCK"}}}
                ts = t_day + (h - 150_000_000) * 10**9 if h != GEN else 0
                return {"result": {"header": {"height": h, "timestamp": ts,
                                              "total_supply": str(1_250_000_000 * 10**24)}}}
            return {"result": {"current_validators": [{"stake": str(600_000_000 * 10**24)}]}}
    na = NearArchive(http=Http(), endpoints=["https://archival.example"], root=tmp_path, sleep=lambda s: None)
    rows = na.rows(config.PROJECT_BY_NAME["Near"], pd.Timestamp("2026-06-01"))
    got = {r["metric"]: r for r in rows}
    assert got["total_supply_protocol"]["value"] == 1_250_000_000
    assert "locked_tokens" not in got, "validators is refused for past blocks: forward-only"
    assert "locked_tokens" in config.HISTORY_FORWARD_ONLY["Near"]["metrics"]
    assert _measuring_point(got["total_supply_protocol"]["source"]) == "near_rpc:block.header.total_supply"
    assert na.known["2026-06-01"] == 150_000_000


def test_ethereum_issuance_route_a_is_removed_and_its_rejection_recorded():
    """Jake, 2026-09-30: route (a) — d(CoinGecko market cap / price) + burn — is swamped by noise
    (daily -626,651.7..+1,331,145.2, 174 negative days; each window's endpoints carry hundreds of
    thousands of ETH against ~245K/quarter). It is removed, the rejection is recorded, and
    Ethereum's issuance is Etherscan-only and FORWARD-ONLY from 2026-09-29."""
    import fetch
    from fetch import backfill
    eth = config.PROJECT_BY_NAME["Ethereum"]
    assert "issuance_history" not in eth
    for gone in ("_derive_issuance_history", "issuance_history_rows", "MAX_UPDATE_GAP_DAYS"):
        assert not hasattr(fetch, gone), gone
    rej = eth["issuance_history_rejected"]
    assert rej["source"] == "derived:d_coingecko_supply+burn" and rej["rejected_on"] == "2026-09-30"
    assert "174 negative days" in rej["evidence"] and "-626,651.7..+1,331,145.2" in rej["evidence"]
    assert "gross_burn_tokens" in eth["series_handover"], "the burn's history leg is kept"
    # ultrasound.money's daily supply is FROZEN at 2024-06-22 and beaconcha.in (the ETH.Store history
    # leg) was DROPPED 2026-10-01: no handover — Etherscan alone, FORWARD-ONLY from 2026-09-29
    assert config.declared_handover("Ethereum", "gross_issuance_tokens") is None
    assert "DROPPED 2026-10-01" in config.HISTORY_FORWARD_ONLY["Ethereum"]["why"]
    fo = config.HISTORY_FORWARD_ONLY["Ethereum"]
    assert "gross_issuance_tokens" in fo["metrics"] and "2026-09-29" in fo["why"] and "frozen" in fo["why"]
    assert eth["ultrasound_history"]["frozen_since"] == "2024-06-22"
    # nothing is DERIVED for the history at fetch time, and the ETH.Store read-time leg went with
    # beaconcha.in (2026-10-01): forward-only
    assert backfill.derived_inputs(eth, "gross_issuance_tokens") == set()
    assert "history_legs" not in eth
    sql = (Path(__file__).resolve().parent.parent / "orphan_cleanup.sql").read_text(encoding="utf-8")
    assert "-- BA. ETHEREUM: issuance ROUTE (a) rows" in sql and "-- DELETE FROM metrics" in sql
    # ADDENDUM 11: whatever the retired routes wrote, SELECT first; only Etherscan's leg from 09-29 stays
    assert "-- BD. ETHEREUM gross_issuance_tokens: ONE ROUTE ONLY" in sql
    # AMENDED (Jake's probes2): 2026-09-29 was a stale-supply row (= the prior day's burn) — it goes too
    assert ("NOT (source LIKE 'derived:d_total_supply_protocol+burn%' AND date >= '2026-09-30')" in sql)


def test_sql_ba_removes_only_route_a_rows(tmp_path, capsys, monkeypatch):
    """The DELETE is review-first and touches route (a)'s source only: the Etherscan leg and the
    burn stay."""
    import sqlite3
    import run_sql
    db = tmp_path / "m.db"
    c = sqlite3.connect(db)
    c.execute("CREATE TABLE metrics (date TEXT, project TEXT, metric TEXT, value REAL, source TEXT, "
              "tier INTEGER, fetched_at TEXT, PRIMARY KEY (date, project, metric))")
    rows = [("2026-06-01", "Ethereum", "gross_issuance_tokens", -626_651.7, "derived:d_coingecko_supply+burn"),
            ("2026-06-02", "Ethereum", "gross_issuance_tokens", 1_331_145.2, "derived:d_coingecko_supply+burn[span=3d]"),
            ("2026-09-29", "Ethereum", "gross_issuance_tokens", 2_650.0, "derived:d_total_supply_protocol+burn"),
            ("2026-06-01", "Ethereum", "gross_burn_tokens", 40.0, "derived:defillama_burned_fee_revenue/price")]
    c.executemany("INSERT INTO metrics VALUES (?,?,?,?,?,2,'x')", rows)
    c.commit()
    c.close()
    assert run_sql.main(["BA", "--db", str(db)]) == 0
    out = capsys.readouterr().out
    assert "derived:d_total_supply_protocol+burn" in out
    monkeypatch.setattr("builtins.input", lambda *_: "DELETE BA")
    assert run_sql.main(["--delete", "BA", "--db", str(db)]) == 0
    assert "Rows this would remove from metrics (2)" in capsys.readouterr().out
    left = sorted(sqlite3.connect(db).execute("SELECT metric, source FROM metrics").fetchall())
    assert left == [("gross_burn_tokens", "derived:defillama_burned_fee_revenue/price"),
                    ("gross_issuance_tokens", "derived:d_total_supply_protocol+burn")]


def test_a_route_closure_does_not_close_a_metric_another_route_is_filling():
    """Jake, 2026-09-30: Ethereum's 2026-09-22 closure is about ultrasound.money's issuance
    endpoint. With Etherscan's readings arriving, the metric is MATURING (forward-only, with the
    reason), not ACCEPTED LIMIT. With nothing held, the closure still stands."""
    import completeness_report as cr
    asof = pd.Timestamp("2026-09-30")
    eth = config.PROJECT_BY_NAME["Ethereum"]
    assert config.unavailable_for("Ethereum", "gross_issuance_tokens")
    note = ("BLOCKED — waiting for Etherscan ethsupply2 readings (d(total_supply_protocol) + "
            "d(BurntFees)) to cover the window")
    live = {"status": "blocked", "note": note, "latest_date": pd.Timestamp("2026-09-29")}
    v, d = cr.classify(eth, "gross_issuance_tokens", live, "2026-09-29", asof)
    # (A1, later the same day: ultrasound.money's daily supply gives the history, so the
    # forward-only record went; the blocked row matures as the legs fill the window)
    assert v == "MATURING" and d.startswith("blocked until its readings cover the window"), (v, d)
    none = {"status": "missing", "note": "", "latest_date": None}
    v, d = cr.classify(eth, "gross_issuance_tokens", none, None, asof)
    assert v == "ACCEPTED LIMIT" and d.startswith("closed 2026-09-22"), (v, d)
    assert "native sources checked: ultrasoundmoney/frontend" in d, d
    # AN ACCEPTED LIMIT WITHOUT NATIVE-SOURCE EVIDENCE IS A BUG (second pass, 2026-09-30)
    closed = config.unavailable_for("Ethereum", "gross_issuance_tokens")
    saved = closed.pop("native_checked")
    try:
        v, d = cr.classify(eth, "gross_issuance_tokens", none, None, asof)
        assert v == "BUG" and "without evidence that project-native sources were checked" in d, (v, d)
    finally:
        closed["native_checked"] = saved


def test_a_supply_that_moves_daily_but_did_not_is_refused_and_the_next_move_spans_the_gap():
    """1a (Jake, 2026-09-30): Ethereum's two stored issuance rows equalled the previous day's burn
    exactly — CoinGecko's supply was unchanged across the days. A zero change on a supply declared
    to move daily is refused (stale reading) and gapped; the next reading that has moved derives
    the whole interval, adding back the burn of the days it spans."""
    from fetch import _derive_issuance
    from fetch.base import FetchOutput, today, point
    eth = config.PROJECT_BY_NAME["Ethereum"]
    assert config.moves_daily("Ethereum", "total_supply_protocol")
    t = today()
    d = lambda n: t - pd.Timedelta(days=n)  # noqa: E731
    v0 = 122_090_190.712258
    # flat: prior equals today's reading
    out = FetchOutput()
    out.add(point("Ethereum", "total_supply_protocol", v0, "etherscan:ethsupply2.supply", 1, t), "x", "Ethereum", "", 1)
    out.add(point("Ethereum", "gross_burn_tokens", 240.739909, "etherscan:ethsupply2.BurntFees:delta", 1, t), "x", "Ethereum", "", 1)
    _derive_issuance(out, [eth], {("Ethereum", "total_supply_protocol"): v0},
                     {("Ethereum", "total_supply_protocol"): str(d(1).date())})
    assert out.frame().query("metric == 'gross_issuance_tokens'").empty
    assert [r["reason"] for r in out.review if r["metric"] == "gross_issuance_tokens"] == ["stale_supply"]
    # moved after two flat days: the delta spans them, so their burns are added back
    stored = pd.DataFrame([
        dict(date=d(3), project="Ethereum", metric="total_supply_protocol", value=v0 - 2_660.0),
        dict(date=d(2), project="Ethereum", metric="total_supply_protocol", value=v0),
        dict(date=d(1), project="Ethereum", metric="total_supply_protocol", value=v0),
        dict(date=d(1), project="Ethereum", metric="gross_burn_tokens", value=40.0)])
    out2 = FetchOutput()
    out2.add(point("Ethereum", "total_supply_protocol", v0 + 5_320.0, "etherscan:ethsupply2.supply", 1, t), "x", "Ethereum", "", 1)
    out2.add(point("Ethereum", "gross_burn_tokens", 40.0, "etherscan:ethsupply2.BurntFees:delta", 1, t), "x", "Ethereum", "", 1)
    _derive_issuance(out2, [eth], {("Ethereum", "total_supply_protocol"): v0},
                     {("Ethereum", "total_supply_protocol"): str(d(1).date())}, stored)
    got = out2.frame().query("metric == 'gross_issuance_tokens'")["value"]
    assert len(got) == 1 and abs(got.iloc[0] - (5_320.0 + 40.0 + 40.0)) < 1e-6, got



def test_ethereum_yield_without_beaconchain_is_consensus_plus_priority_fees_over_beacon_chain_eth():
    """1c (Jake, 2026-09-29): consensus = issuance / ETH on the beacon chain; execution = (DefiLlama
    fees - burned revenue) / price / the same; MEV not included. ETH on the beacon chain = deposit
    contract + Eth2Staking - WithdrawnTotal (ethsupply2). The protocol ceiling 166.32*sqrt(B) and
    the beaconcha.in apr sit beside it. Coin Metrics' TxTfrValAdjUSD is not on the free tier."""
    import build_workbook as bw
    from fetch.base import FetchOutput
    from fetch.etherscan_supply import EtherscanSupply

    class H:
        def get(self, url, params=None):
            return {"status": "1", "result": {"EthSupply": str(120_000_000 * 10**18),
                                              "Eth2Staking": str(1_160_000 * 10**18),
                                              "BurntFees": str(4_600_000 * 10**18),
                                              "WithdrawnTotal": str(40_000_000 * 10**18)}}
    es = EtherscanSupply(deposit_balance=lambda a: 74_000_000 * 10**18)
    es.http = H()
    import os
    os.environ["ETHERSCAN_API_KEY"] = "k"
    try:
        out = FetchOutput()
        es.run([config.PROJECT_BY_NAME["Ethereum"]], None, out)
    finally:
        os.environ.pop("ETHERSCAN_API_KEY", None)
    got = out.frame().set_index("metric")["value"]
    # RETIRED 2026-10-05: deposit contract + Eth2Staking - WithdrawnTotal read 88.4M "staked"; ethsupply2
    # no longer writes beacon_chain_eth (fetch/staked_eth.py does, from validatorqueue's history)
    assert "beacon_chain_eth" not in got.index
    # Jake's decision 2026-09-29: the consensus part is d(Eth2Staking), stored as its own series
    assert got["consensus_rewards_cumulative"] == 1_160_000
    es.prior_delta = {("Ethereum", "consensus_rewards_cumulative"): 1_157_300.0}
    es.prior_dates = {("Ethereum", "consensus_rewards_cumulative"): "2026-01-01"}
    os.environ["ETHERSCAN_API_KEY"] = "k"
    try:
        out2 = FetchOutput()
        es.run([config.PROJECT_BY_NAME["Ethereum"]], None, out2)
    finally:
        os.environ.pop("ETHERSCAN_API_KEY", None)
    f2 = out2.frame().set_index("metric")
    assert abs(f2.loc["consensus_rewards_tokens", "value"] - 2_700.0) < 1e-6
    assert ":delta" in f2.loc["consensus_rewards_tokens", "source"]

    class R:
        def D(self, r, m, w):
            return f"D[{m}:{w}]"
    eth = config.PROJECT_BY_NAME["Ethereum"]
    spec = config.VALIDATOR_YIELD["Ethereum"]
    cons, exe, legs = bw._eth_yield_parts(R(), 5, eth, spec)
    assert "D[consensus_rewards_tokens:q0]" in cons and "/D[beacon_chain_eth:now]" in cons
    assert "gross_issuance_tokens" not in cons, "the consensus part is d(Eth2Staking), not issuance"
    # MEV INCLUDED where held (Jake, 2026-10-02); the fee-based estimate (excluding MEV) otherwise
    assert "MEV INCLUDED" in spec["note"] and "excluding MEV" in spec["note"]
    assert "(D[fees_usd:q0]-D[revenue_usd:q0])" in exe and "D[price_usd:q0]" in exe
    assert exe.startswith("IF(ISNUMBER(D[execution_rewards_eth:q0]),") and \
        ("execution rewards (MEV included)", "execution_rewards_eth", "q0") in legs
    cols = {c[0]: c for c in bw._eth_yield_columns(R())}
    ceil = cols["Issuance ÷ protocol maximum 166.32·√staked (consensus-specs; <1 = missed duties)"][1](5, eth)
    # ultrasound.money's staked-ETH series is frozen at 2024-06-22 (Jake's probe, 2026-09-30): the
    # ceiling's stake is back to ETH on the beacon chain now (formula_stake_metric removed)
    assert "166.32*SQRT(D[beacon_chain_eth:now])" in ceil
    assert "beacon_validators_eth" not in ceil
    assert cols["Consensus part (d Eth2Staking ÷ ETH on the beacon chain)"][1](5, config.PROJECT_BY_NAME["Near"]) == ""
    assert any("MEV INCLUDED where held" in k for k in cols) and not any("beaconcha" in k for k in cols)
    # 64 x sqrt(B gwei) per epoch x 82,181.25 epochs/yr / 1e9 = 166.32 x sqrt(B ETH)
    assert abs(64 * (1e9) ** 0.5 * 365.25 * 86_400 / (32 * 12) / 1e9 - 166.32) < 0.01
    assert config.PROJECT_BY_NAME["Ethereum"]["coinmetrics_community"]["available"] is False


def test_a_daily_moving_supply_that_stayed_flat_is_flagged_with_its_run_length():
    """1d (Jake, 2026-09-30): any supply or balance declared to move daily that reads the same on
    consecutive days is flagged for review (flat_supply) with how long it has been flat — ETH's
    CoinGecko supply, and GEODNET's CoinGecko circulating supply."""
