def test_aerodromes_weekly_epoch_reads_backfill_one_per_past_epoch():
    """2 (Jake, 2026-09-30): the epoch argument is the week's start — deterministic for any past
    date. The archive reads a weekly series on the day AFTER each epoch start, with the argument
    and filing week computed from that day, not from the clock."""
    from fetch import archive as ar
    from fetch.chain import Chain
    aero = config.PROJECT_BY_NAME["Aerodrome"]
    ok, no = ar.ArchiveBackfill(None, [aero]).targets({"base"})
    assert {"gross_issuance_tokens", "emissions_tokens"} <= ok["Aerodrome"], no
    epoch = pd.Timestamp("2026-09-17")                    # a Thursday: unix-week boundary
    assert int(epoch.tz_localize("UTC").timestamp()) % ar.WEEK_S == 0
    day = epoch + pd.Timedelta(days=1)
    assert ar.read_day(aero, "emissions_tokens", day) and not ar.read_day(aero, "emissions_tokens", epoch)
    assert ar.read_day(aero, "locked_tokens", epoch), "daily series: every day"
    assert ar.stored_date(aero, "gross_issuance_tokens", day) == epoch                    # weekly()
    assert ar.stored_date(aero, "emissions_tokens", day) == epoch - pd.Timedelta(days=7)  # last complete week
    c = Chain(backfill={"day": day, "metrics": {}})
    assert c._now_ts() == int(day.tz_localize("UTC").timestamp())


def test_the_archive_resolver_tries_every_endpoint_at_a_year_old_block_never_block_zero(tmp_path, monkeypatch):
    """Jake's run 2026-09-29: the backfill tested only the first endpoint that CONNECTED and gave up
    (publicnode 403 / "historical state not available"; Base refused block 0 as pruned) while
    archive_probe had found eth.drpc.org, Alchemy Polygon and mainnet.base.org serving old state.
    One resolver: env URL first, then every endpoint, each tested ~365 days back (never block 0);
    the host that answers is used for every historical read and remembered for the next run."""
    from fetch import archive as ar
    from fetch import chain as ch
    monkeypatch.setenv("TOKEN_METRICS_LOGCACHE", str(tmp_path))
    monkeypatch.setattr(ar, "_RESOLVED", {})
    monkeypatch.setattr(ch, "rpc_endpoints",
                        lambda c: ["https://pruned.example/rpc", "https://archive.example/v2/SECRETKEY"])
    asked = []

    class Eth:
        def __init__(self, archive):
            self.archive, self.block_number = archive, 20_000_000

        def get_block(self, n):
            return {"timestamp": 1_700_000_000 + 2 * n}           # 2s blocks

        def get_balance(self, a, block_identifier=None):
            asked.append(block_identifier)
            if not self.archive:
                raise ValueError("pruned history unavailable")
            return 0

    monkeypatch.setattr(ch.ChainReader, "make_web3",
                        staticmethod(lambda chain, url, t=30: type("W", (), {"eth": Eth("archive" in url)})()))
    tried = []
    w3, host = ar.resolve_archive("base", attempts=tried)
    assert host == "archive.example" and w3 is not None
    assert [h for h, _ in tried] == ["pruned.example", "archive.example"]
    assert "REFUSED" in tried[0][1] and "SERVED" in tried[1][1]
    assert all(b and b > 1 for b in asked), "never block 0"
    assert abs(asked[0] - (20_000_000 - 365 * 86_400 // 2)) < 10, "a block ~365 days back"
    assert "SECRETKEY" not in (tmp_path / "archive-endpoints.json").read_text()
    # next run: the remembered host is tried first
    monkeypatch.setattr(ar, "_RESOLVED", {})
    tried2 = []
    ar.resolve_archive("base", attempts=tried2)
    assert [h for h, _ in tried2] == ["archive.example"]


def test_near_archival_calls_are_paced_back_off_on_429_and_resume(tmp_path):
    """Jake's run 2026-09-29: fastnear and near.org both answered 429 after ~20 calls. Each 429 is
    waited out on the same endpoint (Retry-After, else 5 -> 15 -> ...s) and slows the pace x1.5;
    a clean streak speeds it back up; the pace and day boundaries persist for the next pass; a
    wait that would overrun the budget stops cleanly (NearBudgetSpent)."""
    import time as _t
    from fetch.archive import NearArchive, NearBudgetSpent
    naps, calls = [], []
    replies = [(429, None, {"Retry-After": "7"}), (429, None, {}), (200, {"result": {"ok": 1}}, {})]

    def post(url, body):
        calls.append(url)
        return replies.pop(0) if replies else (200, {"result": {"ok": 1}}, {})
    na = NearArchive(endpoints=["https://a.example"], root=tmp_path, post=post, sleep=naps.append)
    assert na.pace == NearArchive.PACE_START
    assert na.rpc("block", {"block_id": 1}) == {"ok": 1}
    assert calls == ["https://a.example"] * 3, "the same endpoint is waited out, not abandoned"
    assert 7 in naps and 15 in naps, naps                  # Retry-After honoured, then the ladder
    assert na.stats["429s"] == 2 and abs(na.pace - 1.0 * 1.5 * 1.5) < 1e-9
    for _ in range(25):
        na.rpc("block", {"block_id": 1})
    assert na.pace < 2.25, "a clean streak speeds it back up"
    na.save()
    again = NearArchive(endpoints=["https://a.example"], root=tmp_path, post=post, sleep=naps.append)
    assert abs(again.pace - na.pace) < 1e-3, "the pace that worked is where the next pass starts"
    tight = NearArchive(endpoints=["https://a.example"], root=tmp_path, sleep=naps.append,
                        post=lambda u, b: (429, None, {}), deadline=_t.monotonic() + 3)
    import pytest as _pytest
    with _pytest.raises(NearBudgetSpent):
        tight.rpc("block", {"block_id": 1})


def test_an_exception_from_a_keyed_url_never_reaches_a_log_print_store_or_sheet_unredacted(tmp_path, monkeypatch, caplog):
    """Jake's archive_probe (2026-09-29) printed "403 Client Error: Forbidden for url:
    https://arb-mainnet.g.alchemy.com/v2/<key>". A real HTTPError from a keyed URL is pushed through
    every sink — FetchOutput.fail / gap / LogEntry, the logging module, a CLI's stdout, the store's
    run_log and gap_report, the archive resolver's verdicts — and the key must appear in none."""
    import io
    import logging
    import requests
    import store as store_mod
    from fetch import archive as ar
    from fetch import chain as ch
    from fetch.base import FetchOutput, LogEntry, _RedactingStream, install_redaction, redact

    key = "Zk9Qw3Rt7Yp2Lm5Nb8Vc1Xs4"                              # key-shaped, and in .env
    url = f"https://arb-mainnet.g.alchemy.com/v2/{key}"
    monkeypatch.setenv("ARBITRUM_RPC_URL", url)
    resp = requests.models.Response()
    resp.status_code, resp.url, resp.reason = 403, url, "Forbidden"
    try:
        resp.raise_for_status()
    except requests.HTTPError as e:
        err = e
    assert key in str(err), "the premise: the raw exception carries the key"

    seen = []
    out = FetchOutput()
    out.fail("chain", "Aethir", err)
    out.gap("Aethir", "total_supply", reason=f"read failed: {err}", suggestion=f"check {url}")
    out.log.append(LogEntry("chain", "Aethir", 0, "failed", f"endpoint {url}: {err}"))
    seen += [e.message for e in out.log] + [g["reason"] + g["suggestion"] for g in out.gaps]

    install_redaction(streams=False)
    with caplog.at_level(logging.WARNING):
        logging.getLogger("token_metrics.test").warning("probe failed: %s", err)
    seen += [r.getMessage() for r in caplog.records]

    buf = io.StringIO()
    print(f"    arbitrum: FAILED — {err}", file=_RedactingStream(buf))
    seen.append(buf.getvalue())

    st = store_mod.Store(tmp_path / "m.db")
    st.record_fetch("r1", "chain", "Aethir", 0, "failed", f"raw {err}")
    st.record_gaps("r1", [{"project": "Aethir", "metric": "total_supply", "reason": str(err),
                           "suggestion": url, "tiers_attempted": "2"}])
    seen += [m for (m,) in st.conn.execute("SELECT message FROM run_log")]
    seen += [a + b for a, b in st.conn.execute("SELECT reason, suggestion FROM gap_report")]

    monkeypatch.setattr(ar, "_RESOLVED", {})
    monkeypatch.setenv("TOKEN_METRICS_LOGCACHE", str(tmp_path))
    monkeypatch.setattr(ch, "rpc_endpoints", lambda c: [url])

    def boom(chain, u, t=30):
        raise err
    monkeypatch.setattr(ch.ChainReader, "make_web3", staticmethod(boom))
    tried = []
    ar.resolve_archive("arbitrum", attempts=tried)
    seen += [h + v for h, v in tried]

    leaked = [s for s in seen if key in s]
    assert not leaked, leaked
    assert any("arb-mainnet.g.alchemy.com" in s for s in seen), "the host still says which provider"
    # a key-shaped path on an unknown host, and a key query parameter, go too; docs links stay
    assert redact("https://rpc.example.org/v1/Xk82hd7FJ29sLq01mNbV33") == "https://rpc.example.org"
    assert "apikey=***" in redact("https://api.etherscan.io/v2/api?module=stats&apikey=ABCDEF1234567890")
    doc = "https://github.com/pendle-finance/documentation/blob/9b9509e/docs/ApiOverview.mdx"
    assert redact(doc) == doc


def test_archive_records_pre_deployment_starts_paces_429s_and_explains_every_unwritten_day(tmp_path, monkeypatch):
    """Backfill pass 2 (2026-09-29): (1) sPENDLE failed every day before it existed ("Could not
    decode ... b''") and was retried each pass — a day whose contract has NO CODE at the pinned
    block is recorded as the series' start and older days are not retried; (2) a series with a
    declared start (Uniswap's burn address, from the UNIfication burn) is complete from it; (3) a
    429 is waited out and slows the chain's pace, saved for the next pass; (4) total_supply is not
    backfilled, by design, and says so."""
    import store as store_mod
    from fetch import archive as ar
    from fetch.base import AdaptivePacer, today
    monkeypatch.setenv("TOKEN_METRICS_LOGCACHE", str(tmp_path))
    t0 = int((today() - pd.Timedelta(days=400)).tz_localize("UTC").timestamp())
    deployed_at = 400 * 24 - 3 * 24 + 5          # deployed 3 days ago, 5h into the day
    rate = {"n": 0}

    class Eth:
        block_number = 400 * 24 + 10

        def get_block(self, n):
            return {"timestamp": t0 + n * 3600}

        def get_code(self, a, block_identifier=None):
            return b"\x60" if (block_identifier is None or block_identifier >= deployed_at) else b""

    class Reader(StubReader):
        def __init__(self):
            super().__init__(symbol="sPENDLE")
            self.at_block, self.pacers = {}, {}

        def web3(self, chain):
            return type("W", (), {"eth": Eth()})()

        def checksum(self, a):
            return a

        def deployment_block(self, chain, a):
            return deployed_at

        def scaled(self, chain, address, call, *args, **kw):
            def read():
                rate["n"] += 1
                if rate["n"] == 2:
                    raise RuntimeError("429 Client Error: Too Many Requests for url: https://mainnet.example")
                b = self.at_block[chain]
                if b < deployed_at:
                    raise ValueError("Could not decode contract function call to totalSupply with return data: b''")
                return 30_000_000.0 + b
            return self._paced(chain, read)

        def _paced(self, chain, fn):
            p = self.pacers.get(chain)
            return p.run(fn) if p else fn()

    naps = []
    monkeypatch.setattr(AdaptivePacer, "__init__", (lambda orig: (lambda self, **kw: orig(self, **dict(kw, sleep=naps.append))))(AdaptivePacer.__init__))
    p = dict(config.PROJECT_BY_NAME["Pendle"])
    p["contracts"] = {k: v for k, v in p["contracts"].items() if k in ("spendle",)}
    monkeypatch.setitem(config.PROJECT_BY_NAME, "Pendle", p)
    st = store_mod.Store(tmp_path / "m.db")
    bf = ar.ArchiveBackfill(st, [p], budget_s=60, reader=Reader(), days=6)
    res = bf.run({"ethereum"})
    n = st.conn.execute("SELECT COUNT(*) FROM metrics WHERE project='Pendle' AND metric='locked_tokens_shares'").fetchone()[0]
    assert n == 2, n                                 # the two whole days since deployment
    starts = ar.series_starts()
    begin = str((today() - pd.Timedelta(days=2)).date())
    assert starts[("Pendle", "locked_tokens_shares")]["from"] == begin
    assert "has no code" in starts[("Pendle", "locked_tokens_shares")]["why"]
    assert any(line.startswith("COMPLETE FROM " + begin) for line in res["report"]), res["report"]
    assert 5 in naps and ar.saved_pace("ethereum") >= 0.25, "the 429 waited out and slowed the pace"
    # a second pass does not retry the pre-deployment days
    rate["n"] = 10
    res2 = ar.ArchiveBackfill(st, [p], budget_s=60, reader=Reader(), days=6).run({"ethereum"})
    assert not res2["written"] and not any(l.startswith("NOT WRITTEN") for l in res2["report"])
    # Uniswap's declared start was REMOVED 2026-09-29: the floor is dated instead, and the year
    # before the 100M burn is backfilled (the burn itself is a dated one-off, kept out of rates)
    assert ("Uniswap", "burn_address_balance") not in ar.series_starts()
    _, no = ar.ArchiveBackfill(None, [config.PROJECT_BY_NAME["Chainlink"]]).targets({"ethereum"})
    assert any(m == "total_supply" and w.startswith("BY DESIGN") for _, m, w in no)


def test_history_audit_reads_a_series_that_starts_late_as_complete(tmp_path, monkeypatch):
    """Jake, 2026-09-29: Uniswap burn_address_balance stayed 276 -> 276 and Pendle's spendle series
    hold 257 days because they START there (UNIfication's 100M burn; sPENDLE's deployment). The
    audit reads them COMPLETE with the reason — not BACKFILLING, not SOURCE-LIMITED."""
    import sqlite3
    import store as store_mod
    import history_audit as ha
    from fetch import archive as ar
    from fetch.base import today
    monkeypatch.setenv("TOKEN_METRICS_LOGCACHE", str(tmp_path))
    db = str(tmp_path / "m.db")
    store_mod.Store(db)
    start = str((today() - pd.Timedelta(days=40)).date())     # short of Q0, so the verdict matters
    ar.record_series_start("Pendle", "locked_tokens", start, "spendle 0x… has no code at block 1 (deployed at block 2)")
    conn = sqlite3.connect(db)
    for name, m, first in (("Uniswap", "burn_address_balance", "2025-12-28"), ("Pendle", "locked_tokens", start),
                           ("Pendle", "cooldown_days", str((pd.Timestamp(start) + pd.Timedelta(days=3)).date()))):
        conn.execute("INSERT INTO metrics VALUES (?,?,?,?,?,?,?)", (first, name, m, 1.0, "chain", 2, "x"))
        conn.execute("INSERT INTO metrics VALUES (?,?,?,?,?,?,?)",
                     (str((today() - pd.Timedelta(days=1)).date()), name, m, 1.0, "chain", 2, "x"))
    conn.commit()
    got = {(r[0], r[1]): (r[7], r[8]) for r in ha.rows(db, short_only=False)}
    if ("Uniswap", "burn_address_balance") in got:
        v, why = got[("Uniswap", "burn_address_balance")]
        assert v in ("FULL", "COMPLETE") and (v == "FULL" or "UNIfication" in why)
    v, why = got[("Pendle", "locked_tokens")]
    assert v == "COMPLETE" and why.startswith(f"series starts {start}") and "has no code" in why
    assert got[("Pendle", "cooldown_days")][0] == "BACKFILLING", "stored first AFTER the start: not complete"
    assert not any(k == ("Pendle", "locked_tokens") for k in ((r[0], r[1]) for r in ha.rows(db, short_only=True)))


def test_uniswap_one_off_burn_is_dated_shown_apart_and_kept_out_of_every_rate(tmp_path):
    """Jake, 2026-09-29 14:38: (a) gross_burn_tokens summed 116,000 UNI over the stock's move —
    archive days differenced INSIDE a stored multi-day delta; (b) the 100M retroactive burn must
    never enter a rate; (c) the 100M floor applies only from the burn, so the year before it is
    backfilled as real history."""
    import build_workbook as bw
    import store as store_mod
    from fetch import archive as ar

    # (c) the floor is dated
    assert config.sanity_bounds("Uniswap", "burn_address_balance", "2025-12-27")[0] == \
        config.METRICS["burn_address_balance"]["sanity_min"]
    assert config.sanity_bounds("Uniswap", "burn_address_balance", "2025-12-28")[0] == 100_000_000
    assert config.sanity_bounds("Uniswap", "burn_address_balance")[0] == 100_000_000, "undated: strict"
    assert ("Uniswap", "burn_address_balance") not in config.ARCHIVE_SERIES_START

    # (b) a year of dead-address readings with the 100M burn landing on 2025-12-27 UTC
    days = pd.date_range("2025-10-01", "2026-09-27")
    bal, v = [], 1_000_000.0
    for d in days:
        if d > days[0]:
            v += 45_000.0 if d >= pd.Timestamp("2025-12-28") else 10.0
            if d == pd.Timestamp("2025-12-28"):
                v += 100_000_000.0
        bal.append(v)
    base = {"project": "Uniswap", "tier": 2, "fetched_at": "x", "is_manual": 0, "entered_on": None, "source_note": None}
    rows = [dict(base, date=d, metric="burn_address_balance", value=x, source="chain:ethereum:burn_dead")
            for d, x in zip(days, bal)]
    rows += [dict(base, date=d, metric="gross_burn_tokens", value=x1 - x0, source="chain:ethereum:burn_dead:delta")
             for d, x0, x1 in zip(days[1:], bal, bal[1:])]
    asof = pd.Timestamp("2026-09-28")
    data = bw.aggregate(pd.DataFrame(rows), pd.DataFrame(), asof).set_index("metric")
    uni = data[data.project == "Uniswap"]
    burn = uni.loc["gross_burn_tokens"]
    assert burn["status"] not in bw.WITHHELD_STATUSES, burn["note"]
    assert abs(burn["q0"] - 89 * 45_000.0) < 1e-6                 # (06-30, 09-28], last reading 09-27
    ongoing = (bal[-1] - bal[0]) - 100_000_000                     # the stray days, then the programme
    assert abs(burn["y1"] - ongoing) < 1e-3, "the 100M is in no window"
    assert abs(uni.loc["one_off_burn_tokens", "y1"] - 100_000_000) < 1e-6, "shown on its own row"
    assert uni.loc["one_off_burn_tokens", "latest_date"] == "2025-12-28"
    assert abs(uni.loc["actual_buyback_tokens", "y1"] - ongoing) < 1e-3, "the buyback copy excludes it too"
    assert burn["status"] != "unreconciled_flow", "the reconciliation adds the one-off back"

    # (a) the archive never differences a day inside a stored multi-day delta
    st = store_mod.Store(str(tmp_path / "m.db"))
    w = lambda d, m, x, s: st.conn.execute("INSERT INTO metrics (date, project, metric, value, source, tier, fetched_at) "
                                           "VALUES (?,?,?,?,?,?,?)", (d, "Uniswap", m, x, s, 2, "x"))
    w("2026-09-01", "burn_address_balance", 200_000_000.0, "chain:ethereum:burn_dead")
    w("2026-09-04", "burn_address_balance", 200_116_000.0, "chain:ethereum:burn_dead")
    w("2026-09-04", "gross_burn_tokens", 116_000.0, "chain:ethereum:burn_dead:delta[span=3d]")
    for d, x in (("2026-09-02", 200_100_000.0), ("2026-09-03", 200_116_000.0)):     # archive fills
        w(d, "burn_address_balance", x, "chain:ethereum:burn_dead:archive")
    st.conn.commit()
    straddled = []
    assert ar.derive_flows(st, "Uniswap", "burn_address_balance", straddled) == 0
    assert len(straddled) == 2 and "2026-09-04" in straddled[0]
    total = st.conn.execute("SELECT SUM(value) FROM metrics WHERE project='Uniswap' AND metric='gross_burn_tokens'").fetchone()[0]
    assert total == 116_000.0, "the flows still sum to the stock's move"


def test_derived_series_use_the_full_span_of_their_stored_inputs():
    """Jake, 2026-09-29 14:38: NEAR's validator yield was blocked on ONE covered day of observed
    issuance (~706 NEAR against ~89,500/day expected) while the archival header supply held 365;
    Near burn held 35 days, Plume issuance 7, Chainlink pool release 7; Sky's actual_buyback_usd
    valued 29 of 729 rows though price_usd now spans the year. Every write-time derivation read
    one run's frame. fetch.history_derive re-derives each over the stored inputs."""
    from fetch.history_derive import derive_from_history

    base = {"tier": 2, "fetched_at": "x", "is_manual": 0, "entered_on": None, "source_note": None}
    days = pd.date_range("2025-09-29", "2026-09-28")
    rows = []
    add = lambda n, m, d, v, s: rows.append(dict(base, project=n, metric=m, date=d, value=v, source=s))
    sup = 1_300_000_000.0
    for i, d in enumerate(days):
        if i:
            sup += 89_500.0 - 700.0                  # minted less the day before's burn
        add("Near", "total_supply_protocol", d, sup, "near_rpc:block.header.total_supply" + (":archive" if i < 330 else ""))
        add("Near", "fees_usd", d, 1_000.0, "defillama:fees")
        add("Near", "revenue_usd", d, 700.0, "defillama:revenue")
        add("Near", "price_usd", d, 1.0, "coingecko:market_chart")
        add("Sky", "price_usd", d, 0.062, "coingecko:market_chart")
        add("Sky", "actual_buyback_tokens", d, 934_665.27, "chain:ethereum:flapper_purchases")
    for d in days[-5:]:
        add("Near", "gross_burn_tokens", d, 700.0, "derived:defillama_burned_fee_revenue/price")
    add("Near", "gross_issuance_tokens", days[-1], 706.0, "derived:d_total_supply_protocol+burn")   # the one-day row
    for d in days[-29:]:
        add("Sky", "actual_buyback_usd", d, 934_665.27 * 0.05, "derived:tokens*price")          # stale valuations
    for i, d in enumerate(days[-8:]):
        # Plume's issuance is d(totalSupply()) of the Ethereum ERC-20 since 2026-10-01 (not CoinGecko's)
        add("Plume", "total_supply_protocol", d, 10_000_000_000.0 + 1_000.0 * i, "chain:ethereum:token_ethereum")
        add("Chainlink", "circulating_supply", d, 678_000_000.0 + 50_000.0 * i, "coingecko:coins")
        add("Chainlink", "total_supply", d, 1_000_000_000.0, "coingecko:coins")
    stored = pd.DataFrame(rows)

    out = FetchOutput()
    ps = [config.PROJECT_BY_NAME[n] for n in ("Near", "Sky", "Plume", "Chainlink")]
    done = derive_from_history(out, ps, stored)
    f = out.frame()
    burn = f[(f.project == "Near") & (f.metric == "gross_burn_tokens")]
    assert len(burn) == len(days) - 5 and (burn["value"] == 700.0).all(), "the year of revenue / price"
    iss = f[(f.project == "Near") & (f.metric == "gross_issuance_tokens")]
    assert len(iss) == len(days) - 1, "every interval of the header supply"
    assert abs(iss["value"].median() - 89_500.0) < 1e-6, "d(supply) + the burn inside the interval"
    assert iss.set_index("date").loc[days[-1], "value"] == 89_500.0, "the one-day 706 row is replaced"
    usd = f[(f.project == "Sky") & (f.metric == "actual_buyback_usd")].set_index("date")
    assert len(usd) == len(days) and abs(usd.loc[days[-1], "value"] - 934_665.27 * 0.062) < 1e-6
    q0 = usd[usd.index > days[-1] - pd.Timedelta(days=90)]["value"].sum()
    assert abs(q0 - 90 * 934_665.27 * 0.062) < 1e-3                                        # ~$5.2M
    assert f[(f.project == "Plume") & (f.metric == "gross_issuance_tokens")]["value"].tolist() == [1_000.0] * 7
    rel = f[(f.project == "Chainlink") & (f.metric == "pool_release_tokens")]
    assert rel["value"].tolist() == [50_000.0] * 7
    assert done[("Near", "gross_issuance_tokens")] == len(days) - 1

    # idempotent: with its own rows stored, a second pass writes nothing
    again = pd.concat([stored, f.assign(**{k: v for k, v in base.items() if k not in f.columns})], ignore_index=True)
    out2 = FetchOutput()
    assert derive_from_history(out2, ps, again) == {}

    # a burn day missing refuses that interval, never adds a partial burn
    gap = stored[~((stored.project == "Near") & (stored.metric == "revenue_usd") & (stored.date == days[100]))]
    out3 = FetchOutput()
    derive_from_history(out3, [config.PROJECT_BY_NAME["Near"]], gap)
    i3 = out3.frame().query("metric == 'gross_issuance_tokens'")
    assert days[101] not in set(i3["date"]) and len(i3) == len(days) - 2


def test_a_declared_discrete_series_is_annualised_by_events_times_cadence():
    """Jake, 2026-09-29: Sky's burn/issuance moved 0.059 -> 0.137 under the equal-coverage rule —
    one monthly burn divided by its 16 covered days. Sky's monthly burn and Maple's monthly
    buybacks are annualised as (total / events) x 12, and their per-day rate in a ratio is that
    over days_per_year. One ~2.86M SKY burn a month against ~393M SKY/yr: ~0.087."""
    import build_workbook as bw
    R = bw.Refs(10, 10, ["2026-08"])
    sky, maple, pendle = (config.PROJECT_BY_NAME[n] for n in ("Sky", "Maple", "Pendle"))
    ev_col = bw.DC["q0_events"]
    rate = bw._flow_rate(R, 5, "sky_stage2_burn_tokens", p=sky)
    assert f"Data!${ev_col}$" in rate and "*12/" in rate
    assert f"Data!${ev_col}$" not in bw._flow_rate(R, 5, "sky_stage2_burn_tokens"), "no project, no cadence"
    ann = bw._annualise(R, 5, maple, "actual_buyback_usd", "X")
    assert f"Data!${ev_col}$" in ann and "*12," in ann
    assert f"Data!${ev_col}$" not in bw._annualise(R, 5, pendle, "actual_buyback_usd", "X"), \
        "Pendle's biweekly cadence is its epochs; its buyback rows are daily"
    assert config.events_per_year("Sky", "sky_stage2_burn_tokens") == 12
    assert config.events_per_year("Sky", "gross_issuance_tokens") is None
    # the arithmetic Jake gave: one 2.86M burn in Q0, issuance 393M/yr
    burn_rate, iss_rate = (2_860_000 / 1) * 12 / 365, 393_000_000 / 365
    assert abs(burn_rate / iss_rate - 0.0873) < 0.001

    # a monthly series' Q0 events are the months in its block with a non-zero total
    rows = [{"date": pd.Timestamp(d), "project": "Maple", "metric": "actual_buyback_tokens", "value": v,
             "source": "maple_page:transparency", "tier": 3, "fetched_at": "x", "is_manual": 0,
             "entered_on": None, "source_note": None}
            for d, v in (("2026-06-01", 5.0), ("2026-07-01", 0.0), ("2026-08-01", 7.0))]
    data = bw.aggregate(pd.DataFrame(rows), pd.DataFrame(), pd.Timestamp("2026-09-28"))
    row = data[(data.project == "Maple") & (data.metric == "actual_buyback_tokens")].iloc[0]
    assert row["q0_events"] == 2


def test_completeness_report_gives_every_headline_cell_one_status():
    """Jake, 2026-09-29 (definition of done): each headline cell of the 16 is COMPLETE (with its
    independent reference named), MATURING (with the date it is full), WAITING ON A DATE, or
    NEEDS JAKE (the exact input); World Mobile is PARKED; anything else is a BUG, listed."""
    import build_workbook as bw
    import completeness_report as cr
    asof = pd.Timestamp("2026-09-28")
    base = {"tier": 2, "fetched_at": "x", "is_manual": 0, "entered_on": None, "source_note": None}
    rows = [dict(base, project="Sky", metric="price_usd", date=d, value=0.062, source="coingecko:market_chart")
            for d in pd.date_range("2026-06-01", "2026-09-27")]
    rows += [dict(base, project="Sky", metric="actual_buyback_tokens", date=d, value=900_000.0,
                  source="explorer:flapper_purchases") for d in pd.date_range("2026-06-01", "2026-09-27")]
    long = pd.DataFrame(rows)
    data = bw.aggregate(long, pd.DataFrame(), asof)
    table = cr.report(data, long, asof, scope=(list(config.PROJECTS), []))
    got = {(n, m): (v, d) for n, m, v, d in table}
    assert got[("World Mobile", "*")][0] == "PARKED"
    v, d = got[("Sky", "price_usd")]
    assert v == "MATURING" and "full on 2027-05-31" in d, d                 # prices need 365
    v, d = got[("Sky", "actual_buyback_tokens")]
    assert v == "COMPLETE" and "balanceOf to the wei" in d, d
    assert all(v in ("COMPLETE", "MATURING", "WAITING ON A DATE", "NEEDS JAKE", "BUG", "N/A", "PARKED",
                     "ACCEPTED LIMIT") for _, _, v, _ in table)
    assert any(v == "BUG" and "status missing" in d for n, m, v, d in table if n == "Sky"), \
        "an empty headline cell with no manual route is a bug, listed"


def test_completeness_report_maps_every_recorded_decision_off_the_bug_list():
    """Jake, 2026-09-29: scope is portfolio.txt (the rest one PARKED line); a recorded decision is
    COMPLETE, N/A or ACCEPTED LIMIT, never BUG; NEEDS JAKE is only his three inputs; a Review Queue
    flag is informational; Fluid's halted buyback renders 0 and is COMPLETE; Ethereum's yield
    waits on a week of Eth2Staking readings."""
    import build_workbook as bw
    import completeness_report as cr
    asof = pd.Timestamp("2026-09-29")
    names = ["Ethereum", "Near", "Chainlink", "Hyperliquid", "Uniswap", "Aerodrome", "Sky", "Pendle",
             "Fluid", "Ether.fi", "Morpho", "Maple", "GEODNET", "World Mobile", "Aethir", "Plume"]
    scope = ([config.PROJECT_BY_NAME[n] for n in names], [p["name"] for p in config.PROJECTS if p["name"] not in names])
    base = {"tier": 1, "fetched_at": "x", "is_manual": 0, "entered_on": None, "source_note": None}
    long = pd.DataFrame([dict(base, project="Ethereum", metric="consensus_rewards_cumulative",
                              date=pd.Timestamp("2026-09-30") - pd.Timedelta(days=1), value=1.0,
                              source="etherscan:ethsupply2.Eth2Staking")])
    data = bw.aggregate(long, pd.DataFrame(), asof)
    table = cr.report(data, long, asof, scope=scope)
    got = {(n, m): (v, d) for n, m, v, d in table}
    parked = [(n, d) for n, m, v, d in table if v == "PARKED" and n != "World Mobile"]
    assert len(parked) == 1 and parked[0][0] == f"{len(scope[1])} not in portfolio.txt"
    assert not any(n in scope[1] for n, _, _, _ in table), "a parked project has no rows"
    for k in (("GEODNET", "gross_issuance_tokens"), ("Maple", "emissions_tokens"),
              ("Near", "emissions_tokens"), ("Pendle", "emissions_tokens"), ("Chainlink", "pool_release_tokens"),
              ("Hyperliquid", "pool_release_tokens")):
        assert got[k][0] == "N/A", (k, got[k])
    # Aethir's release is WIRED (Jake, 2026-10-01): it waits on two days of the checker total, and its
    # gross issuance is the declared zero
    assert got[("Aethir", "pool_release_tokens")][0] == "WAITING ON A DATE"
    assert got[("Aethir", "gross_issuance_tokens")][0] == "COMPLETE" and "pre-minted" in got[("Aethir", "gross_issuance_tokens")][1]
    assert "SUPERSEDED" in got[("Chainlink", "pool_release_tokens")][1]
    # SECOND PASS (2026-09-30): both ACCEPTED LIMITs reopened — Maple's SSF chart is the route
    # (NEEDS JAKE: run the probe), Plume's fees come from growthepie (no longer closed)
    # Jake's probe 5 (2026-09-30): the SSF chart is in the page's island props, so the release is
    # WIRED (no decision left; this empty store simply holds none of it yet)
    # Jake (2026-10-01): no release programme runs (MIP-019; Drips ended after Q4 2025) — N/A, not HELD
    assert got[("Maple", "pool_release_tokens")][0] == "N/A" and "MIP-019" in got[("Maple", "pool_release_tokens")][1]
    # the SSF's net change stays SIGNED and stored on its own, for the record
    assert config.PROJECT_BY_NAME["Maple"]["transparency_page"]["metrics"]["ssf_net_outflow_tokens"]["field"] == "ssf_release"
    assert config.PROJECT_BY_NAME["Maple"]["pool_release_tokens_blocked"]["status"].startswith("CLOSED — N/A")
    assert got[("Plume", "fees_usd")][0] != "ACCEPTED LIMIT", got[("Plume", "fees_usd")]
    assert all("native sources checked:" in d for k, (v, d) in got.items() if v == "ACCEPTED LIMIT"), \
        "no ACCEPTED LIMIT survives without native-source evidence"
    for m in ("actual_buyback_tokens", "actual_buyback_usd"):
        v, d = got[("Fluid", m)]
        assert v == "COMPLETE" and "PROGRAMME HALTED 2026-05-11" in d, (m, v, d)
    # beaconcha.in dropped (2026-10-01): staking_yield_pct no longer applies to Ethereum — its yield
    # is A1's calculation from d(Eth2Staking) + priority fees
    assert ("Ethereum", "staking_yield_pct") not in got
    # (a manual quarterly row that is actually MISSING stays NEEDS JAKE; this store is empty)
    jake = {k for k, (v, _) in got.items() if v == "NEEDS JAKE" and not config.is_manual_quarterly(*k)}
    # settlement volume (2026-09-30): Ethereum's Artemis export is in; the other three wait on Jake's
    # (Jake, 2026-09-30: Artemis covers none of them — Hyperliquid CLOSED, NEAR waits on the rebuild)
    import completeness_report as _cr
    assert jake <= {("GEODNET", "locked_tokens"), ("Sky", "net_protocol_surplus_usd"),
                    *(("Near", m) for m in ("settlement_volume_usd", "network_reserve_ratio")),
                    *_cr.PENDING_SEED}           # one-off seeds Jake runs (Plume rebuild, Hyperliquid candles)
    for m in ("settlement_volume_usd", "network_reserve_ratio"):
        assert got[("Hyperliquid", m)][0] == "ACCEPTED LIMIT", got[("Hyperliquid", m)]
        # 2026-10-05: built; with none of it in the store it is the seed Jake runs (NEEDS JAKE) ...
        assert got[("Near", m)][0] == "NEEDS JAKE" and "near_bigquery" in got[("Near", m)][1], got[("Near", m)]
        # ... and once rows are held, MATURING with the full-year date — never NEEDS JAKE again
        v, d = cr.classify(config.PROJECT_BY_NAME["Near"], m, {"status": "gap", "note": "backfill"},
                           "2026-04-01", pd.Timestamp("2026-10-05"),
                           {("Near", "p2p_transfer_volume_usd"): "2026-04-01"})
        assert v == "MATURING" and "188 of 365 days" in d and "2027-03-31" in d, (v, d)
        assert "p2p_transfer_volume_usd" in d, "keyed on the STORED input, not the read-time view"
    # GEODNET locked_tokens: read on chain from the staking wallet since 2026-10-05 — no decision left
    assert ("GEODNET", "locked_tokens") not in cr.DECISIONS
    # a Review Queue flag is informational, never NEEDS JAKE
    v, d = cr.classify(config.PROJECT_BY_NAME["Uniswap"], "fees_usd", {"status": "review", "note": "x"},
                       "2025-01-01", asof)
    assert v == "COMPLETE" and "informational" in d
    # and the workbook itself renders Fluid's halted buyback as 0 over windows after the halt
    f = data.set_index(["project", "metric"]).loc[("Fluid", "actual_buyback_tokens")]
    assert f["q0"] == 0.0 and f["now"] == 0.0 and pd.isna(f["y1"])


def test_pendle_published_apr_of_zero_falls_back_to_the_last_complete_epoch():
    """Jake, 2026-09-29: lastEpochApr read 0. The raw value is logged with whether the latest epoch
    is still in progress; the last complete epoch's APR is stored instead, or nothing (the
    cross-check reads unavailable), never 0."""
    import os
    from fetch.base import FetchOutput
    from fetch.pendle_epochs import PendleEpochs
    os.environ["TOKEN_METRICS_IGNORE_ROBOTS"] = "1"
    try:
        p = config.PROJECT_BY_NAME["Pendle"]
        now = pd.Timestamp.now("UTC").tz_localize(None)
        ts = [int((now - pd.Timedelta(days=14 * (3 - i) + 2)).timestamp()) for i in range(4)]
        amounts = [str(a * 10**18) for a in (170_000, 350_000, 240_000, 82_545)]
        payload = {"lastEpochApr": 0, "sPendleHistoricalData": {
            "timestamps": ts, "buybackAmounts": amounts, "aprs": [0.021, 0.025, 0.0231, 0.0]}}
        out = FetchOutput()
        PendleEpochs(get=lambda url: payload).run([p], None, out)
        apr = out.frame().query("metric == 'staking_apr_published'")
        assert len(apr) == 1 and apr["value"].iloc[0] == 0.0231
        msg = " ".join(e.message for e in out.log)
        assert "lastEpochApr reads 0 (raw)" in msg and "IN PROGRESS" in msg and "last COMPLETE epoch" in msg
        none = dict(payload, sPendleHistoricalData=dict(payload["sPendleHistoricalData"], aprs=[0, 0, 0, 0]))
        out2 = FetchOutput()
        PendleEpochs(get=lambda url: none).run([p], None, out2)
        assert out2.frame().query("metric == 'staking_apr_published'").empty
        assert "UNAVAILABLE this run, not 0" in " ".join(e.message for e in out2.log)
        # Jake, 2026-09-29: "I couldn't find the staking_apr_published line". EVERY outcome writes
        # one Run Log row starting with the metric's name (pendle_api / Pendle, status ok), and
        # the same text at INFO — the field absent, the fetch failing, or a figure stored.
        import logging
        caplog = []
        h = logging.Handler()
        h.emit = lambda r: caplog.append((r.levelno, r.getMessage()))
        lg = logging.getLogger("token_metrics.fetch.pendle_epochs")
        lg.addHandler(h)
        lg.setLevel(logging.INFO)
        try:
            outs = []
            for get in (lambda url: payload, lambda url: {k: v for k, v in payload.items() if k != "lastEpochApr"}):
                o = FetchOutput()
                PendleEpochs(get=get).run([p], None, o)
                outs.append(o)
            def boom(url):
                raise RuntimeError("HTTP 503")
            o = FetchOutput()
            PendleEpochs(get=boom).run([p], None, o)
            outs.append(o)
        finally:
            lg.removeHandler(h)
        for o in outs:
            lines = [e for e in o.log if e.message.startswith("staking_apr_published: ")]
            assert len(lines) == 1 and lines[0].status == "ok" and lines[0].source == "pendle_api", \
                [e.message for e in o.log]
        assert "ABSENT from the payload" in [e.message for e in outs[1].log if e.message.startswith("staking_apr")][0]
        assert "did not answer: HTTP 503" in [e.message for e in outs[2].log if e.message.startswith("staking_apr")][0]
        assert sum(1 for lv, m in caplog if lv == logging.INFO and "staking_apr_published: " in m) == 3
    finally:
        os.environ.pop("TOKEN_METRICS_IGNORE_ROBOTS", None)


def test_section_at_deletes_claim_duplicates_then_renames_the_rest(tmp_path, monkeypatch, capsys):
    """Jake's run 2026-09-29: AT's rename failed "UNIQUE constraint failed" — the scan now writes
    claims straight to emissions_claimed_tokens, so some dates were already there. AT deletes the
    emissions_tokens claim rows whose (date, project) already exist under the new metric, then
    renames the remainder, in one transaction; the SELECTs show both counts first."""
    import sqlite3
    import run_sql
    import store as store_mod
    db = tmp_path / "m.db"
    store_mod.Store(str(db))
    c = sqlite3.connect(db)
    ins = lambda d, m, v, s: c.execute("INSERT INTO metrics (date, project, metric, value, source, tier, fetched_at) "
                                       "VALUES (?,?,?,?,?,?,?)", (d, "Chainlink", m, v, s, 2, "2026-09-28T00:00:00"))
    old = "explorer:staking_rewards_out"
    for d, v in (("2026-09-20", 10.0), ("2026-09-21", 11.0), ("2026-09-22", 12.0)):
        ins(d, "emissions_tokens", v, old)
    for d, v in (("2026-09-21", 11.0), ("2026-09-22", 12.0)):
        ins(d, "emissions_claimed_tokens", v, old)
    ins("2026-09-23", "emissions_tokens", 99.0, "reward_vault:rate")          # the rate row stays
    c.commit()
    c.close()
    assert run_sql.main(["AT", "--db", str(db)]) == 0
    out = capsys.readouterr().out
    assert "to_delete_duplicates" in out and "to_rename" in out
    monkeypatch.setattr("builtins.input", lambda *a: "DELETE AT")
    assert run_sql.main(["--delete", "AT", "--db", str(db)]) == 0
    out = capsys.readouterr().out
    assert "Rows this would remove from metrics (2)" in out and "Rows this UPDATE would change in metrics (1)" in out
    c = sqlite3.connect(db)
    got = sorted(c.execute("SELECT date, metric, value FROM metrics ORDER BY metric, date").fetchall())
    assert got == [("2026-09-20", "emissions_claimed_tokens", 10.0), ("2026-09-21", "emissions_claimed_tokens", 11.0),
                   ("2026-09-22", "emissions_claimed_tokens", 12.0), ("2026-09-23", "emissions_tokens", 99.0)]


def test_pendle_epochs_are_sorted_by_date_and_the_epoch_in_progress_is_not_stored():
    """Jake, 2026-09-29: the APR line said "the latest epoch started 2026-01-29" (sPENDLE's launch)
    — the array came newest-first and its LAST element was read as the latest. Epochs are sorted
    by date whatever the API order; the epoch still in progress (start + 14 days after now) is not
    stored, because counted as a whole epoch it pulls the per-epoch mean and the yield down."""
    import os
    from fetch.base import FetchOutput
    from fetch.pendle_epochs import PendleEpochs
    os.environ["TOKEN_METRICS_IGNORE_ROBOTS"] = "1"
    try:
        p = config.PROJECT_BY_NAME["Pendle"]
        now = pd.Timestamp.now("UTC").tz_localize(None).normalize()
        starts = [now - pd.Timedelta(days=5 + 14 * i) for i in range(6)]            # newest first
        amounts = [82_545, 240_000, 350_000, 170_000, 260_000, 300_000]
        payload = {"lastEpochApr": 0, "sPendleHistoricalData": {
            "timestamps": [int(t.timestamp()) for t in starts],
            "buybackAmounts": [str(a * 10**18) for a in amounts], "aprs": [0] * 6}}
        out = FetchOutput()
        PendleEpochs(get=lambda url: payload).run([p], None, out)
        ep = out.frame().query("metric == 'pendle_distributed_tokens'").sort_values("date")
        assert len(ep) == 5 and 82_545.0 not in set(ep["value"]), "the in-progress epoch is held back"
        assert ep["date"].max() == starts[1] and ep["date"].min() == starts[5]
        msg = " ".join(e.message for e in out.log)
        assert "API order newest-first" in msg and "payload holds 6 epoch(s)" in msg
        assert f"IN PROGRESS, not stored until it ends: {starts[0].date()} at 82,545 PENDLE" in msg
        apr = next(e.message for e in out.log if e.message.startswith("staking_apr_published: "))
        assert f"the latest epoch started {starts[0].date()} and is IN PROGRESS" in apr
    finally:
        os.environ.pop("TOKEN_METRICS_IGNORE_ROBOTS", None)


def test_a_narrow_partial_nearblocks_read_never_caps_the_seeds_wider_window(monkeypatch, caplog):
    """Jake (asked twice): the NEAR buyback seed kept stopping at 2026-08-30. A routine run hit
    its page cap and saved `pending` with after = today - 30; the 365-day seed then RESUMED that
    narrower read instead of reading its own window. A pending read starting later than the one
    requested is discarded and the whole window is read."""
    import json
    import logging
    from fetch import nearblocks, scrape
    from fetch.base import today
    from fetch.logcache import LogCache
    near = config.PROJECT_BY_NAME["Near"]
    flow = near["near_account_flows"][0]
    f = LogCache().root / f"nearblocks-{flow['account']}.json"
    f.parent.mkdir(parents=True, exist_ok=True)
    narrow = str((today() - pd.Timedelta(days=30)).date())
    f.write_text(json.dumps({"version": 1, "after": narrow, "newest_ts": None, "newest_ids": [],
                             "by_day": {}, "pending": {"cursor": "c7", "after": narrow,
                                                       "before": str((today() - pd.Timedelta(days=1)).date()),
                                                       "top_ts": None, "top_ids": [], "by_day": {},
                                                       "rows": 900, "excluded": 0}}))
    asked = []

    class H:
        def get(self, url, params=None, headers=None):
            asked.append((params.get("after_date"), params.get("cursor")))
            old = today() - pd.Timedelta(days=200)
            return {"cursor": None, "txns": [{
                "predecessor_account_id": "some-user.near", "receiver_account_id": flow["account"],
                "transaction_hash": "t1", "block_timestamp": str(int(old.value)),
                "actions": [{"action": "TRANSFER", "deposit": str(3 * 10**24)}]}]}

    monkeypatch.setenv("NEARBLOCKS_API_KEY", "nb-test")
    monkeypatch.setattr(scrape, "robots_verdict", lambda url: (True, "test"))
    out = FetchOutput()
    with caplog.at_level(logging.INFO, logger="token_metrics.fetch.nearblocks"):
        nearblocks.NearBlocks(http=H(), page_cap=10_000)._account_flow("Near", flow, 365, out)
    assert "DISCARDING a partial read" in caplog.text
    assert asked[0] == (str((today() - pd.Timedelta(days=365)).date()), None), "the whole year, from the newest"
    got = out.frame()
    assert len(got) == 1 and got["date"].iloc[0] == (today() - pd.Timedelta(days=200)).normalize()
    assert json.loads(f.read_text())["after"] == str((today() - pd.Timedelta(days=365)).date())


def test_maturing_round_history_backfills(tmp_path, monkeypatch):
    """Jake, 2026-09-29: 31 MATURING, most not needing to wait. (1) circulating_supply history =
    market cap / price before the live read, flat stretches flagged; (2) Uniswap issuance from
    d(total_supply_gross) = 0 on every archived day; Aethir's declared schedule over the whole
    year; Chainlink's vault rate at each past day's first block; (3) Hyperliquid's buyback history
    from DefiLlama holders revenue, handed over to the live read."""
    import build_workbook as bw
    from fetch.base import today
    from fetch.history_derive import derive_from_history
    from fetch.schedule import Schedule
    base = {"tier": 1, "fetched_at": "x", "is_manual": 0, "entered_on": None, "source_note": None}
    days = pd.date_range(today() - pd.Timedelta(days=365), today() - pd.Timedelta(days=1))
    live_from = today() - pd.Timedelta(days=19)
    rows = []
    add = lambda n, m, d, v, s: rows.append(dict(base, project=n, metric=m, date=d, value=v, source=s))
    for i, d in enumerate(days):
        # GEODNET: CoinGecko's circulating figure stuck for 10 days in the middle of the year
        v = 400e6 + (0 if 100 <= i < 110 else i * 1000.0) + (100 * 1000.0 if i >= 110 else 0)
        add("GEODNET", "circulating_supply_implied", d, v, "coingecko:mcap/price")
        add("Uniswap", "total_supply_gross", d, 1_000_000_000.0, "chain:ethereum:token" + (":archive" if d < live_from else ""))
        if d >= live_from:
            add("GEODNET", "circulating_supply", d, v, "coingecko")
    add("Near", "circulating_supply", days[-1], 1.0, "nearblocks:supply")        # a non-CoinGecko live leg
    add("Near", "circulating_supply_implied", days[0], 1.0, "coingecko:mcap/price")
    stored = pd.DataFrame(rows)
    out = FetchOutput()
    ps = [config.PROJECT_BY_NAME[n] for n in ("GEODNET", "Uniswap", "Near")]
    derive_from_history(out, ps, stored)
    f = out.frame()
    circ = f[(f.project == "GEODNET") & (f.metric == "circulating_supply")].sort_values("date")
    assert len(circ) == 365 - 19 and circ["date"].max() < live_from, "strictly before the live leg"
    flat = circ[circ["source"].str.contains(r"\[flat=")]
    assert len(flat) == 10 and flat["source"].iloc[0] == "coingecko:mcap/price[flat=10d]"
    assert f[(f.project == "Near") & (f.metric == "circulating_supply")].empty, "another live source: not stitched"
    iss = f[(f.project == "Uniswap") & (f.metric == "gross_issuance_tokens")]
    assert len(iss) == 364 and (iss["value"] == 0.0).all() and set(iss["source"]) == {"derived:d_supply_gross"}
    # the stitched series builds without a measuring-point block
    hist = pd.concat([stored, f.assign(**{k: v for k, v in base.items() if k not in f.columns})], ignore_index=True)
    data = bw.aggregate(hist, pd.DataFrame(), today()).set_index(["project", "metric"])
    assert data.loc[("GEODNET", "circulating_supply"), "status"] == "ok", data.loc[("GEODNET", "circulating_supply"), "note"]
    assert data.loc[("GEODNET", "circulating_supply"), "first_date"] == str(days[0].date())

    # Aethir's declared schedule: the whole year on a routine 30-day run
    o = FetchOutput()
    Schedule().run([config.PROJECT_BY_NAME["Aethir"]], 30, o)
    em = o.frame().query("metric == 'emissions_tokens'")
    assert em["date"].min() <= today() - pd.Timedelta(days=364)

    # Hyperliquid: DefiLlama holders revenue / price before the live read, handed over
    hl = []
    live = today() - pd.Timedelta(days=17)
    for d in days:
        hl.append(dict(base, project="Hyperliquid", metric="holders_revenue_usd", date=d, value=2_000_000.0, source="defillama:dailyHoldersRevenue"))
        hl.append(dict(base, project="Hyperliquid", metric="price_usd", date=d, value=40.0, source="coingecko"))
        if d >= live:
            for m in ("gross_burn_tokens", "core_burn_tokens"):
                hl.append(dict(base, project="Hyperliquid", metric=m, date=d, value=25_000.0, source="hypercore_info:x:delta"))
    data = bw.aggregate(pd.DataFrame(hl), pd.DataFrame(), today()).set_index(["project", "metric"])
    b = data.loc[("Hyperliquid", "actual_buyback_tokens")]
    assert b["status"] not in bw.WITHHELD_STATUSES, b["note"]
    assert b["first_date"] == str(days[0].date()) and abs(b["y1"] - 364 * 50_000.0) < 1e-3
    u = data.loc[("Hyperliquid", "actual_buyback_usd")]
    assert abs(u["q0"] - (72 * 2_000_000.0 + 17 * 50_000.0 * 40.0)) < 1e-3          # (asof-90, asof], data to asof-1


def test_reward_vault_history_reads_each_past_day_at_its_first_block():
    """Chainlink emissions_tokens: getRewardBuckets() at each past day's first block (the archive
    pattern), newest first, never over a stored day, stopping where the vault is not readable."""
    from fetch import reward_vault as rv
    from fetch.base import today
    p = config.PROJECT_BY_NAME["Chainlink"]
    rate = 1_000 * 10**18 // rv.SECONDS_PER_YEAR * 10**0          # ~1,000 LINK/yr per bucket

    def word(v):
        return f"{v:064x}"

    class Eth:
        def call(self, tx, block):
            if block < 90:
                raise ValueError("execution reverted")               # before deployment
            if tx["data"] == rv.SEL_TYPE_AND_VERSION:
                s = "RewardVault 1.0.0".encode().hex()
                return bytes.fromhex(word(32) + word(17) + s.ljust(64, "0"))
            far = 2_000_000_000
            return bytes.fromhex("".join(word(x) for x in (rate, far, 0) * 3))

        def get_block(self, n):
            return {"timestamp": 1_700_000_000 + n}

    class W3:
        eth = Eth()

        def to_checksum_address(self, a):
            return a

    class DB:
        def at(self, day, head):
            return 100 - (today() - day).days

    have = {str((today() - pd.Timedelta(days=2)).date())}
    rows, why = rv.history_rows(p, W3(), DB(), 30, have, 100)
    got = pd.DataFrame(rows)
    em = got[got.metric == "emissions_tokens"]
    assert len(em) == 9 and str((today() - pd.Timedelta(days=2)).date()) not in set(em["date"].astype(str).str[:10])
    assert em["source"].iloc[0].endswith(":archive") and "not readable" in why and "execution reverted" in why
    assert abs(em["value"].iloc[0] - got[got.metric == "reward_emission_rate_annual"]["value"].iloc[0] / 365.25) < 1e-9


def test_completeness_counts_mechanism_starts_complete_and_names_every_forward_only_reason():
    """Jake, 2026-09-29: a series that begins with its mechanism is COMPLETE from that date, with
    the youth of its rates said apart; MATURING is only for forward-only series, each with its
    reason — anything else that is short says a backfill should fill it."""
    import completeness_report as cr
    asof = pd.Timestamp("2026-09-29")
    sky = config.PROJECT_BY_NAME["Sky"]
    ok = {"status": "ok", "q0_basis": "trailing 90 days"}
    # Sky's gross issuance is a DECLARED ZERO since 2026-10-05 (rewards released, not minted); the
    # stream's mechanism start now lives on emissions_tokens.
    v, d = cr.classify(sky, "gross_issuance_tokens", ok, "2026-08-13", asof)
    assert v == "COMPLETE" and d.startswith("0 — DECLARED") and "not minted" in d
    v, d = cr.classify(sky, "emissions_tokens", ok, "2026-08-13", asof)
    assert v == "COMPLETE" and d.startswith("COMPLETE FROM MECHANISM START 2026-08-13") and "young" in d
    v, d = cr.classify(sky, "sky_stage2_burn_tokens", ok, "2026-09-14", asof)
    assert v == "COMPLETE" and "2026-09-13" in d
    v, d = cr.classify(config.PROJECT_BY_NAME["Near"], "locked_tokens", {"status": "ok"}, "2026-09-11", asof)
    assert v == "MATURING" and "FORWARD-ONLY: NEAR's archival RPC refuses" in d
    v, d = cr.classify(config.PROJECT_BY_NAME["Fluid"], "emissions_tokens", {"status": "ok"}, "2026-09-22", asof)
    assert v == "MATURING" and "FORWARD-ONLY" in d
    v, d = cr.classify(config.PROJECT_BY_NAME["Morpho"], "fees_usd", ok, "2026-09-11", asof)
    assert v == "MATURING" and "NOT FORWARD-ONLY" in d


def test_section_az_removes_only_the_pendle_epoch_still_in_progress(tmp_path, monkeypatch, capsys):
    """Jake, 2026-09-29: remove the in-progress epoch row already stored, review-first, so the
    token-terms yield stops being understated now. Only an epoch whose 14 days have not run goes;
    complete epochs and other metrics stay."""
    import sqlite3
    import run_sql
    import store as store_mod
    from datetime import date, timedelta
    db = tmp_path / "m.db"
    store_mod.Store(str(db))
    c = sqlite3.connect(db)
    today_ = date.today()
    for back, v in ((5, 82_545.0), (19, 240_000.0), (33, 350_000.0)):
        c.execute("INSERT INTO metrics (date, project, metric, value, source, tier, fetched_at) VALUES (?,?,?,?,?,?,?)",
                  (str(today_ - timedelta(days=back)), "Pendle", "pendle_distributed_tokens", v,
                   "pendle_api:sPendleHistoricalData.buybackAmounts", 3, "x"))
    c.execute("INSERT INTO metrics (date, project, metric, value, source, tier, fetched_at) VALUES (?,?,?,?,?,?,?)",
              (str(today_ - timedelta(days=5)), "Pendle", "price_usd", 4.0, "coingecko", 1, "x"))
    c.commit()
    c.close()
    assert run_sql.main(["AZ", "--db", str(db)]) == 0
    assert "IN PROGRESS" in capsys.readouterr().out
    monkeypatch.setattr("builtins.input", lambda *a: "DELETE AZ")
    assert run_sql.main(["--delete", "AZ", "--db", str(db)]) == 0
    assert "Rows this would remove from metrics (1)" in capsys.readouterr().out
    c = sqlite3.connect(db)
    left = sorted(c.execute("SELECT metric, value FROM metrics").fetchall())
    assert left == [("pendle_distributed_tokens", 240_000.0), ("pendle_distributed_tokens", 350_000.0),
                    ("price_usd", 4.0)]


def test_near_and_ethereum_issuance_history_from_backfilled_inputs():
    """Jake, 2026-09-29 (third request for NEAR): issuance = d(supply) + burn over the year.
    NEAR's burn is revenue / price gated by the 70%-of-fees tripwire, so fees_usd is now a
    declared input of the burn and the issuance (the backfill re-reads it), and the inputs'
    coverage is logged whatever is written. ETHEREUM: the burn history stood down once any
    Etherscan burn existed, though it is the declared history leg — it now fills the days before
    the measured leg. (Its issuance history, route (a), was rejected on 2026-09-30.)"""
    from fetch import backfill
    from fetch.base import today
    from fetch.history_derive import derive_from_history
    near, eth = config.PROJECT_BY_NAME["Near"], config.PROJECT_BY_NAME["Ethereum"]
    assert {"revenue_usd", "fees_usd", "price_usd"} <= backfill.derived_inputs(near, "gross_issuance_tokens")
    assert "fees_usd" in backfill.derived_inputs(near, "gross_burn_tokens")
    assert {"revenue_usd", "price_usd"} <= backfill.derived_inputs(eth, "gross_burn_tokens")

    base = {"tier": 2, "fetched_at": "x", "is_manual": 0, "entered_on": None, "source_note": None}
    days = pd.date_range(today() - pd.Timedelta(days=365), today() - pd.Timedelta(days=1))
    etherscan_from = today() - pd.Timedelta(days=1)
    rows = []
    add = lambda m, d, v, src: rows.append(dict(base, project="Ethereum", metric=m, date=d, value=v, source=src))
    for d in days:
        add("revenue_usd", d, 2_000 * 4_000.0, "defillama:dailyRevenue")
        add("price_usd", d, 4_000.0, "coingecko")
        if d >= etherscan_from:
            add("gross_burn_tokens", d, 2_000.0, "etherscan:ethsupply2.BurntFees:delta")
    stored = pd.DataFrame(rows)
    out = FetchOutput()
    derive_from_history(out, [eth], stored)
    burn = out.frame().query("metric == 'gross_burn_tokens'")
    assert len(burn) == 364 and burn["date"].max() < etherscan_from and (burn["value"] == 2_000.0).all()
    assert out.frame().query("metric == 'gross_issuance_tokens'").empty

    # NEAR: the inputs' coverage is said even when intervals are refused
    nrows = []
    for i, d in enumerate(days):
        nrows.append(dict(base, project="Near", metric="total_supply_protocol", date=d, value=1.3e9 + i * 88_800.0,
                          source="near_rpc:block.header.total_supply:archive"))
    o2 = FetchOutput()
    derive_from_history(o2, [near], pd.DataFrame(nrows))
    line = next(e.message for e in o2.log if "history INPUTS" in e.message)
    assert "total_supply_protocol 365 reading(s)" in line and "gross_burn_tokens 0 day(s)" in line
    assert "fees_usd 0 day(s)" in line and "364 interval(s) refused" in line


def test_near_declared_issuance_covers_the_archival_header_year():
    """Jake, 2026-09-30: NEAR's primary issuance is declared 2.5%/yr x total_supply, shown for 19
    days because CoinGecko's total_supply starts 2026-09-11. The archival header total_supply
    covers the year, so each earlier day reads that level — at the superseded 5% before the
    2025-10-30 halving — under ONE measuring point. The derived series stays the cross-check."""
    import build_workbook as bw
    from fetch.base import _measuring_point
    spec = config.issuance_primary("Near")
    assert spec["history_supply_metric"] == "total_supply_protocol"
    asof = pd.Timestamp("2026-09-30")
    base = {"tier": 1, "fetched_at": "x", "is_manual": False, "entered_on": "", "source_note": ""}
    hdr = [dict(base, date=d, project="Near", metric="total_supply_protocol", value=1.20e9 + i * 100_000.0,
                source="near_rpc:block.header.total_supply:archive")
           for i, d in enumerate(pd.date_range(asof - pd.Timedelta(days=365), asof - pd.Timedelta(days=1)))]
    cg = [dict(base, date=d, project="Near", metric="total_supply", value=1.25e9, source="coingecko")
          for d in pd.date_range("2026-09-11", asof - pd.Timedelta(days=1))]
    obs = [dict(base, date=d, project="Near", metric="gross_issuance_tokens", value=85_000.0,
                source="derived:d_total_supply_protocol+burn", tier=2)
           for d in pd.date_range(asof - pd.Timedelta(days=60), asof - pd.Timedelta(days=1))]
    groups = {("Near", "total_supply_protocol"): pd.DataFrame(hdr), ("Near", "total_supply"): pd.DataFrame(cg),
              ("Near", "gross_issuance_tokens"): pd.DataFrame(obs)}
    bw._VIEW_BLOCKS.clear()
    bw._issuance_views(groups, asof)
    view = groups[("Near", "gross_issuance_tokens")].set_index("date")
    assert len(view) == 365 and view.index.min() == asof - pd.Timedelta(days=365)
    assert ("Near", "gross_issuance_tokens") not in bw._VIEW_BLOCKS
    ann = bw.GLOBALS["days_per_year"]
    d0 = pd.Timestamp("2025-10-29")
    assert abs(view.loc[d0, "value"] - 0.05 * hdr[(d0 - hdr[0]["date"]).days]["value"] / ann) < 1e-6
    assert view.loc[d0, "source"] == "declared:2.50%/yr x total_supply[5.00%/yr x total_supply_protocol]"
    d1 = pd.Timestamp("2026-09-10")
    assert abs(view.loc[d1, "value"] - 0.025 * hdr[(d1 - hdr[0]["date"]).days]["value"] / ann) < 1e-6
    assert view.loc[d1, "source"] == "declared:2.50%/yr x total_supply[2.50%/yr x total_supply_protocol]"
    d2 = pd.Timestamp("2026-09-11")
    assert abs(view.loc[d2, "value"] - 0.025 * 1.25e9 / ann) < 1e-6
    assert view.loc[d2, "source"] == "declared:2.50%/yr x total_supply", "the live label is unchanged"
    assert {_measuring_point(s) for s in view["source"]} == {"declared:2.50%/yr x total_supply"}
    import completeness_report as cr
    ref = cr.reference(config.PROJECT_BY_NAME["Near"], "gross_issuance_tokens", {})
    assert "cross-check derived:d_total_supply_protocol (>10x apart blocks)" in ref


def test_every_exit_of_the_issuance_history_step_says_why(caplog):
    """Jake, 2026-09-30: NEAR's 'issuance history INPUTS' line never appeared, on the console or
    the Run Log. Every early return now writes a NOT RUN line naming its cause, and the INPUTS
    line reaches the console too."""
    import logging
    from fetch.history_derive import derive_from_history
    near = config.PROJECT_BY_NAME["Near"]
    base = {"tier": 2, "fetched_at": "x", "is_manual": 0, "entered_on": None, "source_note": None}
    days = pd.date_range("2026-09-01", "2026-09-10")
    sup = [dict(base, project="Near", metric="total_supply_protocol", date=d, value=1.3e9 + i * 88_800.0,
                source="near_rpc:block.header.total_supply:archive") for i, d in enumerate(days)]
    msgs = lambda o: [e.message for e in o.log if e.source == "derive_history" and e.project == "Near"]  # noqa: E731

    with caplog.at_level(logging.INFO, logger="token_metrics.fetch.history_derive"):
        o = FetchOutput()
        derive_from_history(o, [near], pd.DataFrame(sup))
    assert any("history INPUTS" in m for m in msgs(o))
    assert any("history INPUTS" in r.getMessage() for r in caplog.records), "on the console too"

    o = FetchOutput()
    derive_from_history(o, [near], pd.DataFrame(sup[:1]))
    assert any("NOT RUN — total_supply_protocol holds 1 reading(s)" in m for m in msgs(o)), msgs(o)

    manual = dict(base, project="Near", metric="gross_issuance_tokens", date=days[3], value=1.0, source="manual")
    o = FetchOutput()
    derive_from_history(o, [near], pd.DataFrame(sup + [manual]))
    assert any("NOT RUN — 1 stored row(s) are not derived" in m and "manual x1" in m for m in msgs(o)), msgs(o)

    caplog.clear()
    with caplog.at_level(logging.INFO, logger="token_metrics.fetch.history_derive"):
        derive_from_history(FetchOutput(), [config.PROJECT_BY_NAME["Ethereum"]], pd.DataFrame(sup))
    assert any("Near gross_issuance_tokens history NOT RUN — Near is not in this run's projects"
               in r.getMessage() for r in caplog.records)


