def test_plume_staking_apr_is_the_contracts_own_rate_and_a_rate_over_the_cap_stores_nothing():
    """G + Jake's probes3 (2026-09-30): the LIVE diamond is 0x30c791E4 (totalAmountStaked
    134,043,359.31, -0.04% vs the app's 134.1M). locked_tokens = totalAmountStaked(); gross APR =
    rewardRates[PLUME_NATIVE] x 31,536,000 / 1e18, labelled GROSS; commission stake-weighted over
    ACTIVE validators (getValidatorStats — getValidatorInfo's tuple order changed in d408f63); net
    APR = gross x sum_active(staked x (1-commission)) / all stake. The 21-day cooldown is read and
    compared. Unconfirmed, exactly one candidate must reconcile with the app; a rate above the cap
    stores nothing."""
    import copy
    from fetch.plume_staking import PlumeStaking
    spec = config.PROJECT_BY_NAME["Plume"]["plume_staking"]
    assert spec["address"] == "0x30c791E4654EdAc575FA1700eD8633CB2FEDE871"
    assert spec["live_contract"]["confirmed"] is True and spec["cooldown_seconds"] == 1_814_400
    # NET IS THE HEADLINE (Jake, 2026-10-05); gross stands beside it
    assert config.VALIDATOR_YIELD["Plume"]["metric"] == "staking_yield_net_pct"
    assert config.VALIDATOR_YIELD["Plume"]["gross_metric"] == "staking_yield_pct"

    def factory(rate, aggregate, validators, active=None, cooldown=1_814_400):
        active = active or {}

        class F:
            def __init__(self):
                self.functions = self

            def getRewardRate(self, tok):
                assert tok == spec["reward_token"]
                return type("C", (), {"call": lambda s: rate})()

            def totalAmountStaked(self):
                return type("C", (), {"call": lambda s: aggregate})()

            def getValidatorsList(self):
                return type("C", (), {"call": lambda s: validators})()

            def getValidatorStats(self, vid):
                v = next(x for x in validators if x[0] == vid)
                return type("C", (), {"call": lambda s: (active.get(vid, True), v[2], v[1], 10)})()

            def getCooldownInterval(self):
                return type("C", (), {"call": lambda s: cooldown})()
        return lambda sp: F()
    plume = config.PROJECT_BY_NAME["Plume"]
    live = spec["live_contract"]
    assert live["app_total_tokens"] == 134_100_000 and live["app_tolerance"] == 0.005
    cands = list(live["candidates"])
    assert cands[0] == spec["address"]

    def multi(by_addr):
        """contract_factory reading per candidate: {address: (rate, aggregate, validators[, active])}."""
        def make(sp):
            return factory(*by_addr[sp["address"]])(sp)
        return make
    test_diamond = (1_584_404_391, 94_868_945_541_646_499_332,         # 0xCF8B: 94.87 PLUME
                    [(1, 56_410_000_000_000_000_000, 5 * 10**15), (2, 38_458_945_541_646_499_332, 5 * 10**15)])
    agg = 134_043_359_310_000_000_000_000_000                          # Jake's read, -0.04% vs 134.1M
    vals = [(1, 100_000_000 * 10**18, 5 * 10**16), (2, 30_000_000 * 10**18, 2 * 10**16),
            (3, 4_043_359_310_000_000_000_000_000, 10**17)]
    live_diamond = (1_900_000_000, agg, vals, {3: False})              # validator 3 inactive
    far = (1_000_000_000, 10**24, [(1, 10**24, 0)])                    # 1M PLUME: no match

    # CONFIRMED: only the live diamond is read, and its own figures are stored
    out = FetchOutput()
    PlumeStaking(contract_factory=multi({cands[0]: live_diamond})).run([plume], None, out)
    f = out.frame().set_index("metric")
    assert f.loc["locked_tokens", "value"] == agg / 1e18
    assert f.loc["locked_tokens", "source"] == "plume_staking:0x30c791E4.totalAmountStaked"
    apr = 1_900_000_000 * 31_536_000 / 1e18
    assert abs(f.loc["staking_yield_pct", "value"] - apr) < 1e-12 and "[GROSS]" in f.loc["staking_yield_pct", "source"]
    comm = (100 * 0.05 + 30 * 0.02) / 130                              # active validators only
    assert abs(f.loc["staking_commission_pct", "value"] - comm) < 1e-9
    net_factor = (100 * 0.95 + 30 * 0.98) / (agg / 1e24)               # inactive stake earns nothing
    assert abs(f.loc["staking_yield_net_pct", "value"] - apr * net_factor) < 1e-9
    msgs = " ".join(e.message for e in out.log)
    assert "-0.04% against the app's 134,100,000" in msgs and "1,814,400 s = 21 days" in msgs
    assert "DIFFERENT" not in msgs
    # a changed cooldown is flagged, not silently accepted
    out = FetchOutput()
    PlumeStaking(contract_factory=lambda sp: factory(*live_diamond, cooldown=604_800)(sp)).run([plume], None, out)
    assert any("DIFFERENT" in e.message for e in out.log)

    # UNCONFIRMED (the gate that identified it): exactly one candidate within ±0.5% of the app
    unconf = copy.deepcopy(plume)
    unconf["plume_staking"]["live_contract"]["confirmed"] = False
    out = FetchOutput()
    PlumeStaking(contract_factory=multi({cands[0]: far, cands[1]: test_diamond, cands[2]: far})).run([unconf], None, out)
    assert out.frame().empty
    msg = next(e.message for e in out.log if e.status == "skipped")
    assert "0 candidate(s) within ±0.5% of staking.plume.org's 134,100,000" in msg and "94.87 PLUME" in msg
    out = FetchOutput()
    PlumeStaking(contract_factory=multi({cands[0]: live_diamond, cands[1]: test_diamond, cands[2]: far})).run(
        [unconf], None, out)
    assert out.frame().set_index("metric").loc["locked_tokens", "value"] == agg / 1e18
    assert any("identified 0x30c791E4" in e.message for e in out.log)
    out = FetchOutput()
    PlumeStaking(contract_factory=multi({cands[0]: live_diamond, cands[1]: live_diamond, cands[2]: far})).run(
        [unconf], None, out)
    assert out.frame().empty
    # a rate above the cap disqualifies a candidate
    out2 = FetchOutput()
    bad = (4000 * 10**9,) + live_diamond[1:]
    PlumeStaking(contract_factory=multi({cands[0]: bad, cands[1]: test_diamond, cands[2]: far})).run([unconf], None, out2)
    assert out2.frame().empty and any("above the contract's own cap" in e.message for e in out2.log)


def test_plume_staking_history_seed_reads_past_blocks_and_stops_where_the_rpc_does():
    """Jake's run 2026-09-30 17:21: Plume locked_tokens / staking_yield_pct held 1 day each, NOT
    forward-only. `--seed plume_staking` reads the live diamond at the first block of each past day,
    newest first, skipping days held; the rows are the live read's measuring point marked archive.
    The first day the RPC refuses state STOPS it (forward-only from there on this RPC); a block
    with no code is the diamond's deployment — the series' start."""
    from fetch.base import _measuring_point, today
    from fetch.plume_staking import PlumeStaking
    plume = config.PROJECT_BY_NAME["Plume"]
    vals = [(1, 100_000_000 * 10**18, 5 * 10**16)]

    def factory(refuse_below=None):
        def mk(sp):
            class F:
                def __init__(self):
                    self.functions = self

                def _c(self, v):
                    def call(block_identifier=None):
                        if refuse_below is not None and block_identifier is not None and block_identifier < refuse_below:
                            raise ValueError("missing trie node")
                        return v
                    return type("C", (), {"call": staticmethod(call)})()

                def getRewardRate(self, tok):
                    return self._c(1_900_000_000)

                def totalAmountStaked(self):
                    return self._c(134_000_000 * 10**18)

                def getValidatorsList(self):
                    return self._c(vals)

                def getValidatorStats(self, vid):
                    return self._c((True, 5 * 10**16, 100_000_000 * 10**18, 3))

                def getCooldownInterval(self):
                    return self._c(1_814_400)
            return F()
        return mk
    block_at = lambda day: 1000 - (today() - day).days                   # noqa: E731
    have = {(today() - pd.Timedelta(days=2)).normalize()}
    out = FetchOutput()
    res = PlumeStaking(contract_factory=factory()).seed([plume], 5, out, have=have,
                                                        chain=(block_at, lambda b: True))
    f = out.frame()
    assert res == {"stored_days": 4, "stopped": None, "mechanism_start": None}
    assert len(f[f.metric == "locked_tokens"]) == 4 and (today() - pd.Timedelta(days=2)) not in set(f.date)
    lt = f[f.metric == "locked_tokens"].iloc[0]
    assert lt["source"] == "plume_staking:0x30c791E4.totalAmountStaked:archive"
    assert _measuring_point(lt["source"]) == "plume_staking:0x30c791E4.totalAmountStaked"
    assert set(f.metric) == {"locked_tokens", "staking_yield_pct", "staking_commission_pct", "staking_yield_net_pct"}
    # the RPC refuses state before block 997 (3 days back): STOPPED at day 4, days 1-3 stored
    out = FetchOutput()
    res = PlumeStaking(contract_factory=factory(refuse_below=997)).seed([plume], 5, out,
                                                                        chain=(block_at, lambda b: True))
    assert res["stored_days"] == 3 and res["stopped"].startswith(str((today() - pd.Timedelta(days=4)).date()))
    assert any("history STOPPED" in e.message and "FORWARD-ONLY" in e.message for e in out.log)
    # no code before block 998: deployed then — the series starts the day after the last codeless day
    out = FetchOutput()
    res = PlumeStaking(contract_factory=factory()).seed([plume], 5, out, chain=(block_at, lambda b: b >= 998))
    assert res["stored_days"] == 2 and res["mechanism_start"] == str((today() - pd.Timedelta(days=2)).date())
    # CHECKPOINTED (Jake, 2026-10-01): `flush` (the store write in token_metrics.seed_plume_staking)
    # runs at every progress line and at the end, so an interrupted seed keeps the days it read
    import fetch.plume_staking as ps
    from fetch.base import Progress
    seen = []
    out = FetchOutput()
    orig = ps.Progress
    ps.Progress = lambda *a, **k: Progress(*a, **{**k, "every_units": 2})
    try:
        res = PlumeStaking(contract_factory=factory()).seed(
            [plume], 5, out, chain=(block_at, lambda b: True),
            flush=lambda: seen.append(len(out.frame()) if out.frames else 0))
    finally:
        ps.Progress = orig
    assert res["stored_days"] == 5 and len(seen) >= 3 and seen[0] > 0, seen


def test_trading_throughput_is_defillama_dex_plus_perps_by_chain_and_never_settlement_volume():
    """Jake, 2026-09-30: one measure for all four chains — DefiLlama's DEX and perps volume by chain,
    stored separately, summed at read time into trading_throughput_usd, with its own 365-day sum
    and NRR in their own A1 columns. The response's chain must be the declared label (two slugs
    are unverified live); a refused derivatives call (pro-only in today's docs) stores nothing; a
    chain DefiLlama carries no perps for sums DEX alone and says so."""
    import build_workbook as bw
    from fetch.llama import DefiLlama
    tt = config.TRADING_THROUGHPUT
    assert tt["chains"]["Hyperliquid"]["slug"] == "hyperliquid-l1" and tt["chains"]["Plume"]["slug"] == "plume-mainnet"
    assert tt["chains"]["Near"]["covered"] == ("dex_volume_usd",)
    assert "THROUGHPUT only" in tt["meaningful"]["Hyperliquid"] and "perps" in config.METHODOLOGY_FLAGS["hyperliquid_nrr"]
    days = pd.date_range("2025-09-01", "2026-09-29")
    chart = [[int(d.timestamp()), 1e9] for d in days]

    class Http:
        def __init__(self, label, refuse_derivs=False):
            self.label, self.refuse, self.calls = label, refuse_derivs, []

        def get(self, url, params=None):
            self.calls.append(url)
            if self.refuse and "derivatives" in url:
                raise RuntimeError("HTTP 402")
            return {"chain": self.label, "totalDataChart": chart}
    hl = config.PROJECT_BY_NAME["Hyperliquid"]
    ll = DefiLlama()
    ll.http = Http("Hyperliquid L1")
    out = FetchOutput()
    ll.trading_volume(hl, out)
    f = out.frame()
    # DefiLlama's derivatives route is PAID (HTTP 402, 2026-10-01): it is never called; Hyperliquid's
    # perps come from its own info API (fetch/hl_candles.py)
    assert set(f.metric) == {"dex_volume_usd"} and len(f) == len(days)
    assert not any("derivatives" in u for u in ll.http.calls)
    assert set(f.source) == {"defillama:dexs:hyperliquid-l1"}
    assert all("NOT settlement volume" in e.message for e in out.log)
    assert "derivatives" not in str(config.TRADING_THROUGHPUT["endpoints"])
    assert config.TRADING_THROUGHPUT["chains"]["Ethereum"]["covered"] == ("dex_volume_usd",)
    assert "402" in str(config.SOURCE_REGISTER["api.llama.fi"]["paid_only"])
    assert "~7.7%" in config.METHODOLOGY_FLAGS["throughput_vs_settlement"]
    # a slug that resolved to another chain stores nothing
    ll.http, out = Http("HyperEVM"), FetchOutput()
    ll.trading_volume(hl, out)
    assert out.frame().empty and any("not 'Hyperliquid L1'" in e.message for e in out.log)
    # NEAR: DEX only is called
    ll.http, out = Http("Near"), FetchOutput()
    ll.trading_volume(config.PROJECT_BY_NAME["Near"], out)
    assert ll.http.calls == ["https://api.llama.fi/overview/dexs/near"]
    # READ TIME: the sum, its 365d total and NRR — separate metrics from settlement volume
    perps = f.assign(metric="perps_volume_usd", source="hl_candles:candleSnapshot[1d, v x close]")
    groups = {("Hyperliquid", "dex_volume_usd"): f.assign(tier=1), ("Hyperliquid", "perps_volume_usd"): perps.assign(tier=1)}
    groups[("Hyperliquid", "market_cap_usd")] = pd.DataFrame({"date": days, "project": "Hyperliquid",
                                                             "metric": "market_cap_usd", "value": 1.46e11,
                                                             "source": "coingecko", "tier": 1})
    bw._VIEW_BLOCKS.clear()
    bw._settlement_views(groups)
    tp = groups[("Hyperliquid", "trading_throughput_usd")]
    assert float(tp["value"].iloc[0]) == 2e9 and tp["source"].iloc[0] == "derived:dex_volume_usd+perps_volume_usd"
    nrr = groups[("Hyperliquid", "network_reserve_ratio_throughput")]
    assert abs(float(nrr["value"].iloc[-1]) - 1.46e11 / (365 * 2e9)) < 1e-12
    assert nrr["source"].iloc[-1] == "derived:market_cap/trading_throughput_365d"
    assert ("Hyperliquid", "network_reserve_ratio") not in groups, "never mixed with settlement NRR"
    groups = {("Near", "dex_volume_usd"): f.assign(project="Near", tier=1)}
    bw._settlement_views(groups)
    assert groups[("Near", "trading_throughput_usd")]["source"].iloc[0] == \
        "derived:dex_volume_usd[no DefiLlama perps_volume_usd adapter on this chain]"


def test_tier_summary_counts_the_rows_each_tier_stored(tmp_path, monkeypatch):
    """Jake's run 2026-09-30 17:21: artemis_csv logged "0 rows" while storing Ethereum's series —
    the summary keyed its counts by the log's source name ("artemis"), not the tier's. Rows,
    failures and skips are now counted per tier from what it produced and passed validation."""
