def test_maple_own_monthly_revenue_is_primary_and_months_between_buybacks_are_zeros():
    """3b: Maple's own monthly revenueUsd (island datasets) is revenue_usd, monthly, dated to
    month-end; DefiLlama's goes under revenue_usd_defillama. Jake, 2026-09-30: the implied buyback is
    WITHDRAWN — the table is newest-first and contiguous by date, so a month between visible rows
    had no buyback (a measured 0), and the SSF release is computed for EVERY month since the first
    visible buyback, zeros included. Not strictly newest-first -> no zero is inferred."""
    import html as _html
    from fetch import maple_transparency as mt
    from fetch.llama import DefiLlama

    def enc(v):
        if isinstance(v, dict):
            return [0, {k: enc(x) for k, x in v.items()}]
        if isinstance(v, list):
            return [1, [enc(x) for x in v]]
        return [0, v]
    ms = lambda d: int(pd.Timestamp(d).timestamp() * 1000)  # noqa: E731
    months = pd.date_range("2025-09-01", "2026-08-01", freq="MS")
    rows = [{"ts": ms(m), "revenueUsd": 1_000_000.0 + i} for i, m in enumerate(months)]
    top = {"datasets": enc({"LAST_1Y": rows[-6:], "ALL": rows})}
    markup = f'<astro-island uid="r" props="{_html.escape(json.dumps(top))}"></astro-island>'
    rev, key = mt.revenue_series(markup)
    assert key == "ALL" and len(rev) == 12 and rev[-1][0] == pd.Timestamp("2026-08-31")
    assert not hasattr(mt, "implied_buybacks"), "the implied buyback is withdrawn"
    text = ("Aug 2026 $147,098.00 676,293.73 $0.2175 Jul 2026 $136,768.00 852,668.33 $0.1604 "
            "Jun 2026 $375,000.00 1,500,000.00 $0.2500 Nov 2025 $50,000.00 250,000.00 $0.2000 "
            "Sep 2025 $40,000.00 250,000.00 $0.1600 Showing 1-5 of 13")
    bb = mt.parse(text)["buybacks"]
    zeros, why = mt.buyback_zero_months(bb, list(bb["month"]), pd.Timestamp("2026-09-30"))
    assert [f"{m:%Y-%m}" for m in zeros] == ["2025-10", "2025-12", "2026-01", "2026-02", "2026-03",
                                             "2026-04", "2026-05"] and "newest-first" in why
    z2, why2 = mt.buyback_zero_months(bb, list(reversed(bb["month"])), pd.Timestamp("2026-09-30"))
    assert z2 == [] and "not strictly newest-first" in why2
    # the SSF release for EVERY month Sep 2025..Aug 2026: holdings fall 1,000/day
    days = pd.date_range("2025-08-13", "2026-09-29")
    pts = [(d, 90e6 - i * 1000.0) for i, d in enumerate(days)]
    rel, skipped = mt.ssf_release(pts, bb, pd.Timestamp("2026-09-30"), zeros)
    got = {f"{d:%Y-%m}": v for d, v in rel}
    assert list(got) == [f"{m:%Y-%m}" for m in months], "every month since the first visible buyback"
    assert got["2025-10"] == 31_000.0 and got["2026-02"] == 28_000.0, "a zero month is the fall alone"
    assert got["2025-11"] == 30_000.0 + 250_000.0
    maple = config.PROJECT_BY_NAME["Maple"]
    tp = maple["transparency_page"]["metrics"]
    assert tp["revenue_usd"]["field"] == "revenue_monthly" and "actual_buyback_usd_implied" not in tp
    assert "actual_buyback_usd_implied" not in config.METRICS and "mip021_tiers" not in maple["transparency_page"]
    assert config.series_granularity("Maple", "revenue_usd") == "monthly"
    assert maple["defillama_metric_as"] == {"revenue_usd": "revenue_usd_defillama"}
    ll = DefiLlama.__new__(DefiLlama)
    ll._memo, ll.known_absent = {}, set()
    ll._absent = lambda *a, **k: False
    ll._summary_chart = lambda slug, dt: [(pd.Timestamp("2026-09-01"), 10.0)]
    out = FetchOutput()
    ll.fees(maple, None, out)
    assert set(out.frame()["metric"]) == {"fees_usd", "revenue_usd_defillama", "holders_revenue_usd"}
    # the release is no longer HELD but CLOSED N/A (Jake, 2026-10-01): no release programme runs;
    # the block record still stops _derive_pool_release
    assert maple["pool_release_tokens_blocked"]["status"].startswith("CLOSED — N/A")
    sql = (Path(__file__).resolve().parent.parent / "orphan_cleanup.sql").read_text(encoding="utf-8")
    assert "-- BH. MAPLE revenue_usd" in sql and "-- UPDATE metrics SET metric = 'revenue_usd_defillama'" in sql
    assert "-- BI. MAPLE: THE IMPLIED BUYBACK IS WITHDRAWN" in sql and "metric = 'actual_buyback_usd_implied'" in sql


def test_hyperliquid_a4_total_burn_uses_the_assistance_fund_leg_before_both_legs_exist():
    """Jake agreed (2026-09-30): before the first day both legs (Assistance Fund + Core) exist, the
    total burn is the AF leg's history (its buyback / same-day price), labelled as that leg only,
    under a declared handover; the live total follows."""
    import build_workbook as bw
    from fetch.base import _measuring_point
    days = pd.date_range("2026-09-01", "2026-09-29")
    live_from = days[-4]
    mk = lambda m, vals, src, ds=days: pd.DataFrame({"date": ds, "project": "Hyperliquid", "metric": m,  # noqa: E731
                                                     "value": vals, "source": src, "tier": 1})
    groups = {("Hyperliquid", "holders_revenue_usd"): mk("holders_revenue_usd", 1_000_000.0, "defillama"),
              ("Hyperliquid", "price_usd"): mk("price_usd", 40.0, "coingecko"),
              ("Hyperliquid", "gross_burn_tokens"): mk("gross_burn_tokens", 30_000.0,
                                                       "hypercore_info:spotClearinghouseState:delta:PARTIAL",
                                                       days[days >= live_from]),
              ("Hyperliquid", "core_burn_tokens"): mk("core_burn_tokens", 100.0,
                                                      "hypercore_info:tokenDetails.totalSupply:delta",
                                                      days[days >= live_from])}
    bw._usd_history_views(groups)
    bw._burn_total_views(groups)
    t = groups[("Hyperliquid", "total_burn_tokens")].set_index("date")
    assert t.index.min() == days[0] and not t.index.duplicated().any()
    assert t.loc[days[0], "value"] == 25_000.0 and "leg only" in t.loc[days[0], "source"]
    assert t.loc[live_from, "value"] == 30_100.0
    pts = {_measuring_point(s_) for s_ in t["source"]}
    assert pts == set(config.declared_handover("Hyperliquid", "total_burn_tokens")["ordered_points"])
    assert "total_burn_tokens" not in config.HISTORY_FORWARD_ONLY["Hyperliquid"]["metrics"]


def test_aerodrome_team_permanent_locks_are_excluded_from_circulating_only():
    """Jake's decision (2026-09-30): the team's 95M in permanent veNFTs is excluded from circulating
    and kept in total supply, FDV and the veAERO locked total — a named line on the exclusion list;
    Flight School and the PGF are listed, not excluded."""
    from fetch import circulating as C
    spec = config.circulating_onchain("Aerodrome")
    assert spec["status"] == "partial" and spec["declared_exclusions"][0]["tokens"] == 95_000_000
    d = pd.Timestamp("2026-09-29")
    h = pd.DataFrame([{"date": d, "project": "Aerodrome", "metric": "total_supply", "value": 1.8e9}])
    assert list(C.series(h, "Aerodrome")) == [1.8e9 - 95e6]
    lines = "\n".join(C.report_lines())
    assert "EXCLUDED: Development Team Funding" in lines and "still in total supply, FDV and the locked total" in lines
    assert "PENDING (same principle, not excluded): Flight School 50M" in lines


def test_aethir_page_fields_come_from_the_nextjs_server_payload():
    """Jake's probes2 4: the supply page's RSC payload carries {"nodes":433704,"locations":94} and
    {"totalComputePower":…,"totalMonthlyCapacity":…}. Parsed from the HTML; a key with two values
    stores nothing; the manual row is the declared fallback (handover manual -> page)."""
    from fetch.aethir_pages import AethirPages, fields
    chunk = json.dumps('1a:["$","div",null,{"children":[{"nodes":433704,"locations":94},'
                       '{"totalComputePower":38509113.66,"totalMonthlyCapacity":638256960}]}]')[1:-1]
    html = f'<html><script>self.__next_f.push([1,"{chunk}"])</script></html>'
    assert fields(html) == {"nodes": [433704.0], "locations": [94.0], "totalComputePower": [38509113.66],
                            "totalMonthlyCapacity": [638256960.0]}

    class Daily:
        def due(self, *a):
            return True

        def done(self, *a):
            pass
    import fetch.scrape as scrape
    orig = scrape.robots_verdict
    scrape.robots_verdict = lambda url: (True, "test")
    try:
        out = FetchOutput()
        AethirPages(get=lambda url: html if "supply" in url else "<html></html>", daily=Daily()).run(
            [config.PROJECT_BY_NAME["Aethir"]], None, out)
        f = out.frame().set_index("metric")
        assert f.loc["supply_units", "value"] == 433704 and f.loc["capacity_monthly_total", "value"] == 638256960
        assert f.loc["supply_units", "source"] == "aethir_page:protocol/supply-metric.nodes"
        chunk2 = json.dumps('1a:[{"nodes":433704,"locations":94,"totalComputePower":1},{"nodes":1}]')[1:-1]
        two = f'<html><script>self.__next_f.push([1,"{chunk2}"])</script></html>'
        out = FetchOutput()
        AethirPages(get=lambda url: two if "supply" in url else "", daily=Daily()).run(
            [config.PROJECT_BY_NAME["Aethir"]], None, out)
        assert "supply_units" not in set(out.frame()["metric"]) and any(
            "2 different values" in e.message for e in out.log)
    finally:
        scrape.robots_verdict = orig
    assert config.declared_handover("Aethir", "supply_units")["ordered_points"] == \
        ("manual", "aethir_page:protocol/supply-metric.nodes")


def test_aethir_dashboard_by_label_supplier_vs_staker_emissions_and_components():
    """Jake's probes4 + labels (2026-10-01). Tiles are CURRENT figures, charts are HISTORY
    (current_and_series): totalStaked = idc + ai + gaming + edge exactly, and a part not read is
    named, never summed as zero. `emitted` (emissionStakeRewardSchedule, DD-MM-YYYY, weekly, past
    today) is staker_rewards_emitted — NOT emissions. Labelled figures resolve to keys BY VALUE;
    ambiguity stores nothing. Supplier emissions = day-on-day rise of the checker + edge cumulatives,
    handing over from the schedule. Utilisation = last week's hours / (containers x 168)."""
    import build_workbook as bw
    import pytest
    from fetch.aethir_pages import AethirPages, array_objects, current_and_series, resolve_scalar

    def page(objs):
        chunk = json.dumps("1a:" + json.dumps(objs))[1:-1]
        return f'<html><script>self.__next_f.push([1,"{chunk}"])</script></html>'
    months = ["2026-05-01", "2026-06-01", "2026-07-01", "2026-08-01", "2026-09-01"]
    base, bonus, air = 2_418_496_407, 1_181_250_000, 249_123_076
    sched = [{"emitted": 616_412_275 + 2_000_000 * i,
              "date": (pd.Timestamp("2026-08-06") + pd.Timedelta(weeks=i)).strftime("%d-%m-%Y")} for i in range(17)]
    onchain = page([{"totalStaked": 1_789_329_561, "idcStaked": 866_896_004, "aiStaked": 416_297_029,
                     "gamingStaked": 369_439_890, "edgeStaked": 136_696_638,
                     "athCirculatingSupply": 24_053_550_151, "baseRewardDistributed": base,
                     "bonusRewardDistributed": bonus, "airdropRewardDistributed": air,
                     "numberDelegatedCheckers": 84_562, "totalRunningHours": 197_245_731,
                     "aprAi": 12.49, "aprGaming": 14.08, "lockedRatio": 7.44,
                     "edgeTotalEarnings": 2_363_422_512, "edgeStipend": 44_917_651,
                     "edgeDailyPool": 1_184_420, "edgeDevices": 64_869}]
                   + [{"x": 1}]) .replace("</script>", "") + \
        f'<script>self.__next_f.push([1,"{json.dumps(chr(34) + "emissionStakeRewardSchedule" + chr(34) + ":" + json.dumps(sched))[1:-1]}"])</script>'
    # stakeHistory (probes5): ISO startTime/endTime, monthly, ai + gaming only
    hist = [{"startTime": f"{m}T00:00:00.000Z", "endTime": f"{(pd.Timestamp(m) + pd.DateOffset(months=1)).date()}T00:00:00.000Z",
             "aiStaked": 380.2e6 + i * 5e6, "gamingStaked": 287.6e6} for i, m in enumerate(months)]
    onchain += f'<script>self.__next_f.push([1,"{json.dumps(chr(34) + "stakeHistory" + chr(34) + ":" + json.dumps(hist))[1:-1]}"])</script>'
    # the daily APR series `ai` / `gaming` (Jake's pin run, 2026-10-06): ai climbs to exactly 0.1249 on
    # 2026-10-01, so only the POINT reproduces the printed "Average APR"; gaming sits at 0.10, so nothing does
    aprd = pd.date_range("2026-07-04", "2026-10-01")
    apr = [{"date": str(d.date()), "ai": round(0.05 + (0.1249 - 0.05) * i / (len(aprd) - 1), 6), "gaming": 0.10}
           for i, d in enumerate(aprd)]
    onchain += f'<script>self.__next_f.push([1,"{json.dumps("1d:" + json.dumps(apr))[1:-1]}"])</script>'
    # protocol/ecosystem, pinned by key (Jake, 2026-10-06)
    eco = page([{"totalStaked": 592_517_997.39, "checkerRewards": 3_849_000_000.0, "cloudHostRewards": 3_280_000_000.0,
                 "edgeRewards": 2_408_340_163.0, "stakingRewards": 449_478_239.82}])
    # demand-metric (probes5): "arr" sits in an object that also holds the two revenue arrays — the
    # flat-object reader cannot see it; weekly labels are DD/MM with no year
    weeks = pd.date_range("2024-06-03", "2026-09-28", freq="7D")             # the last week is in progress
    wk = [{"startDate": w.strftime("%d/%m"), "amount": 868_693.77} for w in weeks]
    mons = pd.date_range("2024-08-01", "2026-10-01", freq="MS")              # October 2026 is in progress
    mo = [{"month": m.strftime("%B, %Y"), "earning": 868_693.77 * m.days_in_month / 7} for m in mons]
    blob = {"arr": 62_489_999.90221721, "weeklyNetworkRevenue": wk, "monthlyNetworkRevenue": mo}
    demand = page([{"totalRevenue": 192_220_803, "purchasesAth": 11_182_170_271,
                    "totalComputeHoursDelivered": 2_433_230_876, "totalComputeHoursDeliveredLastWeek": 22_089_416}]) + \
        f'<script>self.__next_f.push([1,"{json.dumps("1b:" + json.dumps(blob))[1:-1]}"])</script>'
    supply = page([{"nodes": 433704, "locations": 94}, {"totalComputePower": 38509113.66,
                                                         "totalMonthlyCapacity": 638256960},
                   {"idcStaked": 866_896_004, "totalOnlineHours": 3_514_810_067}])
    # the compute-reward block (probes5): keys BESIDE the weeklyData array, weeks DD/MM with no year
    cweeks = pd.date_range("2026-07-26", "2026-09-27", freq="7D")             # the last is in progress
    cblock = {"totalRewards": 3_063_771_452.71, "totalServiceFee": 8_841_927_451.05,
              "totalLockedRewards": 2_040_911_539.99,
              "weeklyData": [{"week": w.strftime("%d/%m"), "reward": 18_364_931.51, "service": 149_152_120.69}
                             for w in cweeks]}
    supply += f'<script>self.__next_f.push([1,"{json.dumps("1c:" + json.dumps(cblock))[1:-1]}"])</script>'


    assert current_and_series(onchain, "aiStaked")[0] == 416_297_029
    assert len(current_and_series(onchain, "aiStaked")[1]) == 5
    arr = array_objects(onchain, "emissionStakeRewardSchedule")
    assert len(arr) == 17 and arr[0] == {"emitted": 616_412_275, "date": "06-08-2026"}

    class Daily:
        def due(self, *a):
            return True

        def done(self, *a):
            pass
    import fetch.scrape as scrape
    orig = scrape.robots_verdict
    scrape.robots_verdict = lambda url: (True, "test")
    import fetch.aethir_pages as apm
    orig_ap_today = apm.today
    apm.today = lambda: pd.Timestamp("2026-10-01")
    aeth = config.PROJECT_BY_NAME["Aethir"]

    def get(url):
        if "onchain" in url:
            return onchain
        if "ecosystem" in url:
            return eco
        if "supply" in url:
            return supply
        if "demand" in url:
            return demand
        raise RuntimeError("404")
    try:
        out = FetchOutput()
        AethirPages(get=get, daily=Daily()).run([aeth], None, out)
    finally:
        scrape.robots_verdict, apm.today = orig, orig_ap_today
    f = out.frame()
    one = lambda m: f[f.metric == m].sort_values("date")                     # noqa: E731
    msgs = " ".join(e.message for e in out.log)
    # tiles current, charts history; totalStaked current-only (the wrapper handover)
    assert list(one("locked_tokens").value) == [1_789_329_561]
    assert len(one("locked_tokens_ai")) == 6 and one("locked_tokens_ai").value.iloc[-1] == 416_297_029
    assert set(one("locked_tokens_ai").source) == {"aethir_page:protocol/onchain-metric.aiStaked"}   # one point
    assert one("locked_tokens_ai").date.iloc[0] == pd.Timestamp("2026-05-01")      # stakeHistory startTime
    assert len(one("locked_tokens_edge")) == 1 and "locked_tokens_edge: `stakeHistory` on protocol/onchain-metric no object carries" in msgs
    assert "totalStaked 1,789,329,561.00 vs the sum of its parts 1,789,329,561.00 (+0.00%)" in msgs
    assert float(one("circulating_supply_first_party").value.iloc[-1]) == 24_053_550_151
    assert float(one("supply_units_checker_licences").value.iloc[0]) == 84_562
    # staker rewards: dates up to today only, never emissions_tokens
    st = one("staker_rewards_emitted")
    # 06-08 .. 01-10 weekly = 9 points on 2026-10-01 (Jake's page read 630,412,275 "at 24-09-2026")
    assert len(st) == 9 and st.value.iloc[-2] == 630_412_275 and "emissions_tokens" not in set(f.metric)
    assert "8 point(s) not stored (after today: 2026-10-08 634,412,275.00 .. 2026-11-26)" in msgs
    # ARR PINNED BY KEY (probes5), the value as read kept as a cross-check
    assert float(one("arr_usd").value.iloc[0]) == 62_489_999.90221721
    assert "pinned by key; cross-check vs 62,490,000 as read 2026-10-01: -0.0%" in msgs
    # APRs: the statistic of the `ai` / `gaming` series that reproduces Jake's 2026-10-01 reading is pinned
    assert one("staking_apr_ai").value.iloc[0] == pytest.approx(0.1249)
    assert one("staking_apr_ai").source.iloc[0] == "aethir_page:protocol/onchain-metric.ai[point]"
    assert "staking_apr_ai = point of `ai` = 0.1249 as of 2026-10-01 — PINNED" in msgs
    assert one("staking_apr_gaming").empty
    assert "staking_apr_gaming: \"Average APR of Gaming Pool\" read 0.1408 on 2026-10-01" in msgs
    assert "point 0.1000 (-29.0%)" in msgs and "NONE within 1%. Left UNPINNED; NOTHING STORED." in msgs
    # ecosystem page, pinned by key; Total Rewards Distributed = the four components
    assert float(one("stath_sophon_pool_tokens").value.iloc[0]) == 592_517_997.39
    assert float(one("eco_checker_rewards_cumulative_tokens").value.iloc[0]) == 3_849_000_000.0
    assert float(one("cloud_host_rewards_cumulative_tokens").value.iloc[0]) == 3_280_000_000.0
    assert float(one("staker_rewards_cumulative_tokens").value.iloc[0]) == 449_478_239.82
    assert float(one("ecosystem_rewards_cumulative_tokens").value.iloc[0]) == pytest.approx(
        3_849_000_000.0 + 3_280_000_000.0 + 2_408_340_163.0 + 449_478_239.82)
    # Total Network Revenue = the monthly list's sum, PARTIAL for June-July 2024
    tot = one("customer_revenue_cumulative_usd")
    assert float(tot.value.iloc[0]) == pytest.approx(sum(o["earning"] for o in mo))
    assert tot.source.iloc[0] == ("aethir_page:protocol/demand-metric.sum(monthlyNetworkRevenue):PARTIAL"
                                  "[June-July 2024 not in the monthly list]")
    # the figures not in any payload are UNAVAILABLE, never value-matched
    for m in ("compute_purchases_cumulative_tokens", "supply_units_edge", "edge_stipend_cumulative_tokens",
              "edge_earnings_cumulative_tokens", "edge_daily_reward_pool_tokens"):
        assert config.unavailable_for("Aethir", m) is not None and one(m).empty, m
    # WEEKLY REVENUE: DD/MM, year inferred from the sequence; the week in progress reported, not stored
    rv = one("customer_revenue_usd")
    assert len(rv) == len(weeks) - 1 and rv.date.iloc[0] == pd.Timestamp("2024-06-03")
    assert rv.date.iloc[-1] == pd.Timestamp("2026-09-21") and rv.value.iloc[0] == 868_693.77
    assert rv.source.iloc[0] == "aethir_page:protocol/demand-metric.weeklyNetworkRevenue.amount"
    assert "1 point(s) not stored (in progress: 2026-09-28 868,693.77)" in msgs
    # MONTHLY REVENUE from Aug 2024; October in progress
    mv = one("customer_revenue_monthly_usd")
    assert len(mv) == 26 and mv.date.iloc[0] == pd.Timestamp("2024-08-01") and mv.date.iloc[-1] == pd.Timestamp("2026-09-01")
    assert config.series_granularity("Aethir", "customer_revenue_monthly_usd") == "monthly"
    assert "monthlyNetworkRevenue summed vs Total Network Revenue (Since June 2024)" in msgs
    assert "the monthly list starts Aug 2024" in msgs
    wvm = next(e.message for e in out.log if e.message.startswith("weeklyNetworkRevenue (pro rata by day) vs"))
    assert "(+0.00%)" in wvm and "2024-08..2026-09" in wvm, wvm
    # client-loaded charts: nothing stored from the server payload; the browser route (Jake, 2026-10-02)
    assert not {"compute_hours_weekly", "avg_lock_duration_days_ai", "avg_lock_duration_days_gaming"} & set(f.metric)
    assert config.unavailable_for("Aethir", "avg_lock_duration_days_ai") is not None    # probes9: UNAVAILABLE
    assert "browser_capture" not in config.PROJECT_BY_NAME["Aethir"], "removed: the durations are UNAVAILABLE"
    # probes8: weekly compute hours come from the demand page's server payload (by key prefix), not the browser
    assert "weeklyComputeHo*" in config.PROJECT_BY_NAME["Aethir"]["dashboard_pages"]["pages"]["protocol/demand-metric"]["arrays"]
    # COMPUTE REWARDS (Jake, 2026-10-02): stored, read by key beside the weeklyData array; service fee
    # (demand) and locked rewards apart; finished weeks only
    assert float(one("compute_rewards_cumulative_tokens").value.iloc[0]) == 3_063_771_452.71
    assert float(one("compute_service_fee_cumulative_tokens").value.iloc[0]) == 8_841_927_451.05
    assert float(one("compute_rewards_locked_tokens").value.iloc[0]) == 2_040_911_539.99
    cr = one("compute_rewards_tokens")
    assert len(cr) == len(cweeks) - 1 and cr.date.iloc[0] == pd.Timestamp("2026-07-26") and cr.value.iloc[0] == 18_364_931.51
    assert len(one("compute_service_fee_tokens")) == len(cweeks) - 1
    assert config.series_granularity("Aethir", "compute_rewards_tokens") == "weekly"
    # derived: supplier stocks, utilisation, the ratio check
    assert float(one("checker_rewards_cumulative_tokens").value.iloc[0]) == base + bonus + air
    assert float(one("edge_rewards_cumulative_tokens").value.iloc[0]) == 2_408_340_163.0     # = earnings + stipend
    assert set(one("edge_rewards_cumulative_tokens").source) == {"aethir_page:protocol/ecosystem.edgeRewards"}
    assert float(one("utilisation_containers_pct").value.iloc[0]) == pytest.approx(22_089_416 / (433_704 * 168))
    assert "assumes every container available 24/7" in one("utilisation_containers_pct").source.iloc[0]
    assert "locked / circulating = totalStaked / athCirculatingSupply = 0.0744" in msgs     # computed
    assert aeth["dashboard_pages"]["pages"]["protocol/ecosystem"]["fields"]["edgeRewards"] == \
        "edge_rewards_cumulative_tokens"                                                   # pinned (Jake, 2026-10-06)
    # ambiguity stores nothing
    two = page([{"a": 62_000_000, "b": 63_000_000}])
    unpinned = {**aeth["dashboard_pages"]["labelled"]["arr"], "key": None}
    assert resolve_scalar(unpinned, {"protocol/demand-metric": two}).startswith("ambiguous")
    assert resolve_scalar(aeth["dashboard_pages"]["labelled"]["arr"], {"protocol/demand-metric": two}).startswith(
        "pinned `arr` is not in the payload of protocol/demand-metric — `arr` is not in the payload")

    # READ TIME: supplier emissions = the day-on-day rise of the ecosystem page's checker + cloud host + edge
    # cumulatives (Jake, 2026-10-06); the schedule gives way. No compute add-on, so no PARTIAL.
    d = pd.date_range("2026-09-25", "2026-10-03")
    sch = pd.DataFrame({"date": d, "project": "Aethir", "metric": "emissions_tokens", "value": 2.87e6,
                        "source": "schedule:config:PARTIAL", "tier": 1})
    days = pd.to_datetime(["2026-10-01", "2026-10-02", "2026-10-04"])
    ck = pd.DataFrame({"date": days, "project": "Aethir", "metric": "eco_checker_rewards_cumulative_tokens",
                       "value": [3.849e9, 3.852e9, 3.858e9], "source": "x", "tier": 3})
    ch = ck.assign(metric="cloud_host_rewards_cumulative_tokens", value=[3.28e9, 3.2826e9, 3.2826e9])
    eg = ck.assign(metric="edge_rewards_cumulative_tokens", value=[2.408e9, 2.409e9, 2.4114e9])
    stocks = {("Aethir", "eco_checker_rewards_cumulative_tokens"): ck,
              ("Aethir", "cloud_host_rewards_cumulative_tokens"): ch, ("Aethir", "edge_rewards_cumulative_tokens"): eg}
    groups = {("Aethir", "emissions_tokens"): sch, **stocks}
    bw._measured_emissions_views(groups)
    em = groups[("Aethir", "emissions_tokens")].sort_values("date")
    meas = em[em.source.str.startswith("aethir_page:supplier_rewards")]
    assert list(meas.value) == pytest.approx([3e6 + 2.6e6 + 1e6, 6e6 + 0 + 2.4e6])
    assert "[span=2d]" in meas.source.iloc[1] and not meas.source.str.contains("PARTIAL").any()
    # released = earned: none of the three carries a locked split
    rel_ = groups[("Aethir", "emissions_released_tokens")].sort_values("date")
    ear_ = groups[("Aethir", "emissions_earned_tokens")].sort_values("date")
    assert list(rel_.value) == list(meas.value) == list(ear_.value)
    assert "[RELEASED: checker + cloud host + edge carry no locked split" in meas.source.iloc[0]
    from fetch.base import _measuring_point
    assert {_measuring_point(x) for x in meas.source} == {"aethir_page:supplier_rewards"}, \
        "the declared handover's measuring point is unchanged"
    assert em[em.source.str.startswith("schedule")].date.max() == pd.Timestamp("2026-10-01")
    # TOTAL RELEASE = supplier + the staker schedule's rise in the same span (both pre-minted releases)
    stk = pd.DataFrame({"date": pd.to_datetime(["2026-09-24", "2026-10-01", "2026-10-03"]), "project": "Aethir",
                        "metric": "staker_rewards_emitted", "value": [630.4e6, 632.4e6, 634.4e6],
                        "source": "aethir_page:x", "tier": 3})
    groups = {("Aethir", "emissions_tokens"): sch, **stocks, ("Aethir", "staker_rewards_emitted"): stk,
              ("Aethir", "gross_issuance_tokens"): pd.DataFrame({
                  "date": pd.to_datetime(["2026-09-30", "2026-10-01"]), "project": "Aethir",
                  "metric": "gross_issuance_tokens", "value": [2.87e6, 0.0],
                  "source": ["schedule:config", "schedule:config:declared"], "tier": 1})}
    bw._measured_emissions_views(groups)
    rel = groups[("Aethir", "pool_release_tokens")].sort_values("date")
    assert list(rel.value) == pytest.approx([6.6e6, 8.4e6 + 2e6])          # the 10-03 step lands in (10-02, 10-04]
    assert rel.source.iloc[0].startswith("aethir_page:release[supplier + staker rewards][RELEASED")
    assert "[span=2d]" in rel.source.iloc[1]
    assert list(groups[("Aethir", "gross_issuance_tokens")].value) == [0.0]   # the schedule's old rows hidden
