def test_routine_fetches_ask_only_for_days_since_the_last_stored_one(monkeypatch):
    """A, Jake 2026-10-05: history once, then incremental. CoinGecko asks for the days since the
    newest stored price plus OVERLAP_DAYS; growthepie is not downloaded when every metric is held
    through yesterday; DefiLlama (no date parameter) is read at most once a day per project."""
    import fetch.coingecko as cg
    from fetch.base import OVERLAP_DAYS, today
    asked = []

    class H:
        min_interval = 0

        def get(self, url, params=None, headers=None):
            if "market_chart" in url:
                asked.append(params["days"])
                return {"prices": [], "market_caps": [], "total_volumes": []}
            return []
    c = cg.CoinGecko(last_dates={("Aethir", "price_usd"): str((today() - pd.Timedelta(days=2)).date())})
    c.http = H()
    c.run([config.PROJECT_BY_NAME["Aethir"]], 30, FetchOutput())
    assert asked == [str(2 + OVERLAP_DAYS)]
    from fetch.growthepie import GrowThePie
    p = config.PROJECT_BY_NAME["Plume"]
    yday = str((today() - pd.Timedelta(days=1)).date())
    gp = GrowThePie(last_dates={("Plume", m): yday for m in p["growthepie"]["metrics"]})
    gp._fundamentals = lambda url: (_ for _ in ()).throw(AssertionError("must not download"))
    out = FetchOutput()
    gp.run([p], 30, out)
    assert {("Plume", m) for m in p["growthepie"]["metrics"]} <= out.current
    # DefiLlama: a project read complete today is not called again today
    from fetch.llama import DefiLlama
    monkeypatch.delenv("TOKEN_METRICS_DAILY_CHECKS", raising=False)
    ll = DefiLlama()
    calls = []

    def fake_project(proj, wd, o):
        calls.append(proj["name"])
        o.add(pd.DataFrame([{"date": today().normalize() - pd.Timedelta(days=1), "project": proj["name"],
                             "metric": "fees_usd", "value": 1.0, "source": "defillama", "tier": 1}]),
              "defillama", proj["name"], "", 1)
    ll._project = fake_project
    ll.rwa = lambda *a, **k: None
    u = config.PROJECT_BY_NAME["Uniswap"]
    ll.run([u], 30, FetchOutput())
    out2 = FetchOutput()
    ll.run([u], 30, out2)
    assert calls == ["Uniswap"] and ("Uniswap", "fees_usd") in out2.current


def test_geod_stake_wallet_verdict_and_blockworks_dates_in_every_unit():
    """Jake, 2026-10-05: seven holder-export candidates against Blockworks' geod_total_stake. Dates
    parse in s/ms/us/ns, as numbers or numeric strings or text; the date column is chosen by what
    parses, not by its name; a wallet tracks only within 10% on >= 80% of >= 10 months with the
    same peak month; the candidates in the probe are the ones in config, unwired."""
    import check_offline_items as c
    nov = pd.Timestamp("2025-11-01")
    assert c._bw_days([1_761_955_200, "1761955200.0", 1_761_955_200_000_000, 1_761_955_200_000_000_000,
                       "2025-11-01 00:00:00.000 UTC"]).tolist() == [nov] * 5
    df, col, _ = c._bw_frame([{"updated_time": 5, "day_ts": "1761955200000", "geod_total_stake": "12000000"},
                              {"updated_time": 6, "day_ts": "1762041600000", "geod_total_stake": "11900000"}])
    assert col == "day_ts" and df["geod_total_stake"].tolist() == [12_000_000.0, 11_900_000.0]
    months = list(pd.date_range("2025-06-01", "2026-10-01", freq="MS"))
    series = {m: 12e6 - abs((m - nov).days) * 20_000 for m in months}
    good = {m: v * 1.03 for m, v in series.items()}
    flat = {m: 3.0e6 for m in months}
    ver = c.stake_wallet_verdict({"a": good, "b": flat}, series)
    assert ver[0]["label"] == "a" and ver[0]["tracks"] and not ver[1]["tracks"]
    assert ver[0]["peak_wallet"] == nov == ver[0]["peak_series"]
    assert c.GEOD_STAKE_CANDIDATES == config.PROJECT_BY_NAME["GEODNET"]["staking_wallet_candidates_2026_10_05"]["addresses"]
    assert "staking_wallet_polygon" in config.PROJECT_BY_NAME["GEODNET"]["contracts"], "the tracking wallet is wired"


def test_a_declared_absent_defillama_call_is_remembered_by_the_adapter(monkeypatch):
    """Jake's run 10:49: Plume's "Fees for plume not found" (HTTP 400) came back every run. The
    adapter records the failure day itself; the call is skipped until recheck_days pass, its
    revenue legs are not tried after the refusal, and a success clears it."""
    from fetch.llama import DefiLlama
    monkeypatch.delenv("TOKEN_METRICS_DAILY_CHECKS", raising=False)
    plume = config.PROJECT_BY_NAME["Plume"]
    calls = []
    ll = DefiLlama()

    def chart(slug, dt):
        calls.append((slug, dt))
        raise RuntimeError("HTTP 400 — Fees for plume not found")
    ll._summary_chart = chart
    out = FetchOutput()
    ll.fees(plume, 30, out)
    assert calls == [("plume", "dailyFees")], "refused once; the revenue legs are not tried"
    out2 = FetchOutput()
    ll.fees(plume, 30, out2)
    assert len(calls) == 1 and any("KNOWN ABSENT (declared)" in e.message for e in out2.log)
    ll._today = str((pd.Timestamp(ll._today) + pd.Timedelta(days=7)).date())
    ll.fees(plume, 30, FetchOutput())
    assert len(calls) == 2, "re-checked after recheck_days"


