def test_monthly_dune_rows_never_occupy_dates_the_daily_burn_series_covers():
    """Jake, 2026-10-05: since the 365-day archive backfill GEODNET's daily burn starts 2025-10, but
    Dune 8683175's monthly rows for 2025-10..2026-08 sat on the 1sts — the daily burn of each 1st
    could never be stored (unreconciled_flow) and a rederive --apply would have replaced each month
    with one day. Monthly rows whose month starts on/after the daily series' first day are the
    CROSS-CHECK (gross_burn_tokens_dune_monthly): routed there by the Dune adapter, moved there at
    read time, and the series sums each month once."""
    import os
    import build_workbook as bw
    from fetch.dune import Dune, daily_series_start
    SUM = config.GEODNET_BURN_SUM_POINT + ":delta"
    days = pd.date_range("2025-10-01", "2025-10-31")
    daily = [(str(d.date()), "GEODNET", "gross_burn_tokens", 90_000.0, SUM) for d in days]
    stored = pd.DataFrame([{"date": pd.Timestamp(d), "project": p, "metric": m, "value": v, "source": s}
                           for d, p, m, v, s in daily])
    assert daily_series_start(stored, "GEODNET", "gross_burn_tokens", "dune:8683175") == pd.Timestamp("2025-09-30")
    # the real store: the 1st is hidden by the Dune row, so the daily rows start on the 2nd — still Oct
    assert daily_series_start(stored[stored.date > pd.Timestamp("2025-10-01")], "GEODNET", "gross_burn_tokens",
                              "dune:8683175") == pd.Timestamp("2025-10-01")
    # the Dune adapter routes a covered month to the cross-check metric
    os.environ["DUNE_API_KEY"] = "test-key"
    d = Dune(stored_long=stored)
    d.http = _Rows([{"month": "2025-09-01", "tokens_burned": 800_000.0, "sol_tokens_burned": 100_000.0},
                    {"month": "2025-10-01", "tokens_burned": 2_700_000.0, "sol_tokens_burned": 63_001.0}])
    out = FetchOutput()
    d.run([config.PROJECT_BY_NAME["GEODNET"]], None, out)
    f = out.frame()
    burn = f[f.metric == "gross_burn_tokens"]
    cross = f[f.metric == "gross_burn_tokens_dune_monthly"]
    assert list(burn["date"]) == [pd.Timestamp("2025-09-01")] and burn.value.iloc[0] == 900_000.0
    assert list(cross["date"]) == [pd.Timestamp("2025-10-01")] and cross.value.iloc[0] == 2_763_001.0
    # read time: a stored monthly row inside the daily span is moved, the month counts once
    g = _grp(daily + [("2025-09-01", "GEODNET", "gross_burn_tokens", 900_000.0, "dune:8683175"),
                      ("2025-10-01", "GEODNET", "gross_burn_tokens", 2_763_001.0, "dune:8683175")])
    # the stored collision: the Dune row holds 2025-10-01, so the daily 1st is absent
    g[("GEODNET", "gross_burn_tokens")] = g[("GEODNET", "gross_burn_tokens")].drop_duplicates("date", keep="last")
    bw._monthly_leg_views(g)
    s = g[("GEODNET", "gross_burn_tokens")]
    assert pd.Timestamp("2025-09-01") in set(s["date"]) and (s[s.date == pd.Timestamp("2025-09-01")].value == 900_000.0).all()
    oct_ = s[s["date"].dt.to_period("M") == pd.Period("2025-10")]
    assert set(oct_["source"]) == {SUM}, "October is the daily series only, never Dune's month beside it"
    assert set(g[("GEODNET", "gross_burn_tokens_dune_monthly")]["value"]) == {2_763_001.0}
    assert config.monthly_crosscheck_metric("GEODNET", "actual_buyback_tokens") is None


def _clf_log(data_words=None, data_hex=None, ts="2026-10-03", block=100, idx=0, topics=None, tx="0xaa"):
    data = data_hex or "0x" + "".join(f"{w:064x}" for w in data_words)
    return {"address": "0x0", "topics": topics or ["0x0"], "data": data, "blockNumber": block,
            "timeStamp": int(pd.Timestamp(ts).timestamp()) + 3600, "transactionHash": tx, "logIndex": idx}


def test_chainlink_fee_line_decoders_read_each_events_own_layout():
    """Jake, 2026-10-05: the lines that bypass the fee aggregator, decoded from each contract's event
    layout (sources pinned in fetch/chainlink_fees.py): CCIP 1.2/1.5 feeToken/feeTokenAmount (words 8/9),
    CCIP 2.0 receipts (gross = all, premium = the last, network-fee receipt), VRF v2.5 payment + native
    flag, Automation v2.3 premiumInJuels x linkUSD (8 decimals)."""
    import fetch.chainlink_fees as cf
    from eth_abi import encode
    link = 0x514910771AF9Ca656af840dff83E8264EcF986CA
    w = [0x20, 1, 2, 3, 4, 5, 0, 7, link, 12 * 10 ** 17] + [0] * 6
    tok, amt = cf.decode_ccip_legacy(_clf_log(w))
    assert tok == "0x514910771af9ca656af840dff83e8264ecf986ca" and amt == 12 * 10 ** 17
    receipts = [("0x" + "11" * 20, 1, 2, 3 * 10 ** 17, b""), ("0x" + "22" * 20, 1, 2, 5 * 10 ** 17, b""),
                ("0x" + "33" * 20, 0, 0, 2 * 10 ** 17, b"")]
    raw = encode(["address", "uint256", "bytes", "(address,uint32,uint32,uint256,bytes)[]", "bytes[]"],
                 ["0x" + "44" * 20, 0, b"msg", receipts, []])
    tok2, gross, prem = cf.decode_ccip_v2(_clf_log(data_hex="0x" + raw.hex()))
    assert tok2 == "0x" + "44" * 20 and gross == 10 ** 18 and prem == 2 * 10 ** 17
    pay, native = cf.decode_vrf(_clf_log([123, 25 * 10 ** 16, 1, 1, 0]))
    assert pay == 25 * 10 ** 16 and native is True
    usd = cf.decode_automation(_clf_log([0, 0, 0, 2 * 10 ** 18, link, 15 * 10 ** 8, 0, 0]))
    assert abs(usd - 30.0) < 1e-9, "2 LINK of premium at $15.00 (8-decimal feed) = $30"
    # OnRamps from the Router's OnRampSet history: live until a lane's next set
    spans = cf.onramp_spans([(10, 1, "0xA"), (50, 1, "0xB"), (20, 2, "0xA"), (60, 2, "0xC")])
    assert spans == {"0xa": (10, 60), "0xb": (50, None), "0xc": (60, None)}


def test_chainlink_fee_lines_store_complete_priced_days_and_refuse_an_incomplete_chain(tmp_path, monkeypatch):
    """The adapter scans each chain's VRF coordinator, Automation registry and every OnRamp its Router
    ever set, and stores a line's day only when every chain is scanned and every event is priced;
    days with no events are measured zeros. A chain whose scan fails stores nothing for that line."""
    import fetch.chainlink_fees as cf
    from fetch.base import today
    spec = config.PROJECT_BY_NAME["Chainlink"]["chainlink_fee_lines"]
    d1 = str((today() - pd.Timedelta(days=2)).date())
    link = 0x514910771AF9Ca656af840dff83E8264EcF986CA

    class Ex:
        def __init__(self, fail_chain=None):
            self.fail_chain = fail_chain

        def configured(self, cid):
            return ["etherscan"]

        def start_budget(self, s):
            pass

        def clear_budget(self):
            pass

        def block_at(self, cid, ts):
            return 1000

        def get_logs(self, cid, address, topics, frm, to):
            from fetch.explorer import ExplorerRefused
            if cid == self.fail_chain:
                raise ExplorerRefused("etherscan: down")
            t = topics[0]
            if t == cf.TOPICS["onramp_set"]:
                ramp = "0x" + "0" * 24 + "ab" * 20
                return [_clf_log(data_hex=ramp, topics=[t, "0x" + "0" * 63 + "1"], block=900)], {}
            if t == cf.TOPICS["ccip_legacy"] and cid == 1:
                return [_clf_log([0x20, 1, 2, 3, 4, 5, 0, 7, link, 2 * 10 ** 18] + [0] * 6, ts=d1, block=1100)], {}
            if t == cf.TOPICS["vrf"] and cid == 1:
                return [_clf_log([1, 10 ** 18, 1, 1, 0], ts=d1, block=1200, idx=1)], {}
            if t == cf.TOPICS["automation"] and cid == 42161:
                return [_clf_log([0, 0, 0, 10 ** 18, link, 15 * 10 ** 8, 0, 0], ts=d1, block=1300, idx=2)], {}
            return [], {}
    prices = {(d1, "ethereum:0x514910771af9ca656af840dff83e8264ecf986ca"): (15.0, 18),
              (d1, "coingecko:ethereum"): (4000.0, 18)}
    c = cf.ChainlinkFees(explorer=Ex(), prices=prices, cache_file=tmp_path / "clf.json")
    # A ROUTINE RUN BEFORE THE SEED reads nothing and says why (Jake, run 2026-10-05 14:35)
    out0 = FetchOutput()
    c.run([config.PROJECT_BY_NAME["Chainlink"]], 30, out0)
    assert out0.frame().empty and c.seed_complete() is None
    assert any(e.status == "skipped" and "seed not complete" in e.message
               and "--seed chainlink_fees" in e.message for e in out0.log)
    out = FetchOutput()
    c.run([config.PROJECT_BY_NAME["Chainlink"]], 30, out, unbounded=True)       # the seed
    assert c.seed_complete() and any("seed COMPLETE" in e.message for e in out.log)
    f = out.frame()
    leg = f[f.metric == "customer_revenue_ccip_legacy_usd"].set_index("date")["value"]
    assert leg[pd.Timestamp(d1)] == 30.0 and len(leg) == int(spec["days"]) and (leg.drop(pd.Timestamp(d1)) == 0).all()
    vrf = f[f.metric == "customer_revenue_vrf_usd"].set_index("date")["value"]
    assert vrf[pd.Timestamp(d1)] == 4000.0, "a native-paid VRF fulfilment priced at the native coin"
    auto = f[f.metric == "customer_revenue_automation_premium_usd"].set_index("date")["value"]
    assert auto[pd.Timestamp(d1)] == 15.0
    # a routine run after the seed re-reads nothing new and counts each log once
    out2 = FetchOutput()
    c.run([config.PROJECT_BY_NAME["Chainlink"]], 30, out2)
    f2 = out2.frame()
    assert f2[f2.metric == "customer_revenue_ccip_legacy_usd"].set_index("date")["value"][pd.Timestamp(d1)] == 30.0
    # one chain failing: the line is not stored at all
    c3 = cf.ChainlinkFees(explorer=Ex(fail_chain=1), prices=prices, cache_file=tmp_path / "clf3.json")
    out3 = FetchOutput()
    c3.run([config.PROJECT_BY_NAME["Chainlink"]], 30, out3, unbounded=True)
    assert "customer_revenue_vrf_usd" not in set(out3.frame().get("metric", pd.Series(dtype=str)))
    assert any("NOT STORED" in e.message for e in out3.log)
    assert c3.seed_complete() is None, "a REQUIRED chain unread: not complete; routine runs keep skipping"
    # AN OPTIONAL CHAIN UNREAD (Base behind Blockscout's limits, Jake 2026-10-05): stored PARTIAL, named,
    # its part-read events left out, and the seed complete on the required chains
    c4 = cf.ChainlinkFees(explorer=Ex(fail_chain=8453), prices=prices, cache_file=tmp_path / "clf4.json")
    out4 = FetchOutput()
    c4.run([config.PROJECT_BY_NAME["Chainlink"]], 30, out4, unbounded=True)
    f4 = out4.frame()
    vrf4 = f4[f4.metric == "customer_revenue_vrf_usd"]
    assert len(vrf4) and vrf4["source"].str.contains(":PARTIAL").all() \
        and vrf4["source"].str.contains("base not covered").all()
    assert c4.seed_complete()["partial_chains"] == ["base"]
    assert any("PARTIAL, missing: base" in e.message for e in out4.log)


def test_chainlink_fee_seed_reads_in_passes_saving_after_each_and_resumes(tmp_path):
    """--seed chainlink_fees has no overall budget: a stream that runs out of a pass's time keeps the
    whole blocks it read, moves its cursor to the explorer's resume point, saves, and continues — so
    an interrupted seed resumes there and no log is counted twice."""
    import fetch.chainlink_fees as cf
    from fetch.base import today
    from fetch.explorer import ExplorerTimeout
    d1 = str((today() - pd.Timedelta(days=3)).date())
    link = 0x514910771AF9Ca656af840dff83E8264EcF986CA
    vrf_addr = config.PROJECT_BY_NAME["Chainlink"]["chainlink_fee_lines"]["chains"]["ethereum"]["vrf_v2_5"].lower()
    vrf_logs = [_clf_log([1, 10 ** 18, 0, 1, 0], ts=d1, block=b, idx=0, tx=f"0x{b:x}") for b in (1100, 1200, 1300)]

    class Ex:
        calls: list = []

        def configured(self, cid):
            return ["etherscan"]

        def start_budget(self, s):
            pass

        def clear_budget(self):
            pass

        def block_at(self, cid, ts):
            return 1000

        def get_logs(self, cid, address, topics, frm, to):
            if cid == 1 and address.lower() == vrf_addr and topics[0] == cf.TOPICS["vrf"]:
                Ex.calls.append(frm)
                rows = [x for x in vrf_logs if x["blockNumber"] >= frm]
                if len(Ex.calls) == 1:              # the first pass runs out of time after block 1100
                    e = ExplorerTimeout("budget")
                    e.partial, e.resume_from = rows[:1], 1200
                    raise e
                return rows, {}
            return [], {}
    prices = {(d1, "coingecko:chainlink"): (20.0, 18)}
    c = cf.ChainlinkFees(explorer=Ex(), prices=prices, cache_file=tmp_path / "clf.json")
    out = FetchOutput()
    c.run([config.PROJECT_BY_NAME["Chainlink"]], 30, out, unbounded=True)
    assert Ex.calls == [1000, 1200], "the second pass starts at the resume point, not the window start"
    vrf = out.frame()
    vrf = vrf[vrf.metric == "customer_revenue_vrf_usd"].set_index("date")["value"]
    assert vrf[pd.Timestamp(d1)] == 60.0, "three 1-LINK payments at $20, each counted once"
    import json as _json
    st = _json.loads((tmp_path / "clf.json").read_text())
    assert st["streams"][f"ethereum:vrf:{vrf_addr}"]["next"] == 1301 and st["seed_complete"]


def test_explorer_calls_share_one_pacer_per_host_across_instances(monkeypatch):
    """c) Jake, run 2026-10-05 14:35: base.blockscout.com answered 429 to chainlink_fees while other
    adapters read it too. Every ExplorerLogs in the run now waits on ONE pacer per host."""
    from fetch.explorer import ExplorerLogs
    monkeypatch.setenv("BLOCKSCOUT_API_KEY", "k")
    waits = []

    def nap(sec):
        waits.append(sec)
    a = ExplorerLogs(http=_ExplorerHttp({}), pace_sleep=nap)
    b = ExplorerLogs(http=_ExplorerHttp({}), pace_sleep=nap)
    a.get_logs(8453, "0x" + "11" * 20, ["0x" + "22" * 32], 0, "latest")
    b.get_logs(8453, "0x" + "33" * 20, ["0x" + "22" * 32], 0, "latest")
    assert waits and waits[-1] > 0.2, "the second adapter waits on the first one's call to the same host"
    assert config.EXPLORERS["blockscout"]["rate_per_s"] <= 5 and config.EXPLORERS["etherscan"]["rate_per_s"] <= 5


def test_chainlink_customer_revenue_is_the_aggregator_core_plus_the_lines_that_bypass_it():
    """Jake, 2026-10-05: customer_revenue_usd = fees_usd (aggregator core) + requests + CCIP 1.2/1.5 + VRF
    v2.5 + Automation v2.3 premium, summed only on days every leg holds; the stored DefiLlama listing
    sum is not read; CCIP 2.0 fees are never a leg."""
    import build_workbook as bw
    legs = ["fees_usd", "customer_revenue_requests_usd", "customer_revenue_ccip_legacy_usd",
            "customer_revenue_vrf_usd", "customer_revenue_automation_premium_usd"]
    rows = []
    for d in ("2026-10-02", "2026-10-03"):
        for i, m in enumerate(legs):
            rows.append((d, "Chainlink", m, 100.0 * (i + 1), "x"))
    rows.append(("2026-10-04", "Chainlink", "fees_usd", 999.0, "x"))           # other legs missing
    rows.append(("2026-10-03", "Chainlink", "ccip_v2_fees_usd", 7_777.0, "x"))
    rows.append(("2026-10-03", "Chainlink", "customer_revenue_usd", 123.0, "defillama:sum(chainlink services)"))
    g = _grp(rows)
    bw._customer_revenue_views(g)
    s = g[("Chainlink", "customer_revenue_usd")].set_index("date")["value"]
    assert list(s.index) == [pd.Timestamp("2026-10-02"), pd.Timestamp("2026-10-03")]
    assert (s == 1500.0).all(), "core + four lines, never ccip_v2, never the retired listing sum"
    assert "ccip_v2" not in str(config.PROJECT_BY_NAME["Chainlink"]["customer_revenue_components"]["plus"])


def test_spot_checks_compare_our_figure_with_a_live_reference_and_never_pass_without_one(monkeypatch, capsys):
    """Jake, 2026-10-05: `check_offline_items.py spot_checks` — OUR figure, an INDEPENDENT live reference,
    the % gap and PASS/CHECK against a stated tolerance. A same-source read checks freshness only (FRESH,
    never PASS); a reference that cannot be fetched prints where to look and is MANUAL, never PASS."""
    import check_offline_items as coi
    asof = pd.Timestamp("2026-10-05")
    rows = {
        "Hyperliquid|market_cap_usd": {"now": 27.7e9, "latest_date": "2026-10-04"},
        "Hyperliquid|price_usd": {"now": 92.75},
        "Hyperliquid|circulating_supply_first_party": {"now": 298.67e6},
        "Aethir|arr_usd": {"now": 62.49e6}, "Aethir|locked_tokens": {"now": 1.79e9},
        "Aethir|customer_revenue_usd": {"q0": 14.0e6, "q0_covered_days": 84.0},
        "Uniswap|gross_burn_tokens": {"q0": 5.7e6, "q0_covered_days": 90.0},
        "Pendle|locked_tokens_shares": {"now": 60.0e6}, "Pendle|locked_tokens": {"now": 62.0e6},
        "Pendle|locked_tokens_legacy_vependle": {"now": 33.9e6}, "Pendle|locked_tokens_virtual": {"now": 5.0e6},
        "Pendle|pendle_distributed_tokens": {"q0": 1.4e6, "q0_events": 6.0},
        "Sky|actual_buyback_usd": {"q0": 5.2e6}, "Sky|actual_buyback_tokens": {"q0": 84.1e6},
    }
    monkeypatch.setattr(coi, "_spot_ours", lambda: (None, rows, asof))
    day = int(pd.Timestamp("2026-09-01").timestamp())
    arr_html = 'self.__next_f.push([1,"{\\"arr\\": 62490000.0}"])'
    staked_html = 'self.__next_f.push([1,"{\\"totalStaked\\": 1790000000.0}"])'

    def polite(url, method="GET", **kw):
        if "hyperliquid" in url:
            if kw["json"]["type"] == "spotMeta":
                return {"tokens": [{"name": "HYPE", "tokenId": "0xabc"}]}, ""
            return {"circulatingSupply": "298670000.0", "markPx": "93.10"}, ""
        if "api.coingecko.com" in url:
            return [{"market_cap": 20.6e9, "current_price": 93.0, "circulating_supply": 222e6}], ""
        if "demand-metric" in url:
            return arr_html, ""
        if "onchain-metric" in url:
            return staked_html, ""
        if "api.llama.fi" in url:
            return {"totalDataChart": [[day, 600_000.0]]}, ""
        if "coins.llama.fi" in url:
            return {"coins": {"coingecko:uniswap": {"prices": [{"timestamp": day + 3600, "price": 6.0}]}}}, ""
        if "pendle" in url:
            return {"totalStakedInSpendle": str(int(60.1e6 * 1e18))}, ""
        return None, "unexpected"
    monkeypatch.setattr(coi, "_polite", polite)
    monkeypatch.setattr(coi, "_render_once", lambda url: (None, "robots.txt disallows (test)"))
    coi.spot_checks()
    out = capsys.readouterr().out
    # a) market cap against tokenDetails circulating x markPx: inside ±5%; ASXN not read -> MANUAL
    assert "[PASS] market cap: ours $27.70bn" in out and "tokenDetails" in out
    assert "[FRESH] first-party circulating" in out
    assert "[MANUAL] market cap vs ASXN" in out and "hyperscreener.asxn.xyz" in out
    assert "the gap is the circulating basis" in out
    # b) Aethir: stored vs a fresh read of the same dashboard is FRESH, never PASS
    assert "[FRESH] ARR (stored) vs dashboard arr" in out and "[FRESH] locked_tokens vs dashboard totalStaked" in out
    assert "customer revenue annualised vs dashboard arr" in out
    # c) 5.7M UNI vs $600K / $6 = 100K UNI: far outside ±30% -> CHECK, source named
    assert "[CHECK] UNI burned (90d)" in out and "DefiLlama dailyHoldersRevenue" in out
    # d) Pendle: shares inside 1%; no hub total and no last epoch in the answer -> MANUAL with where to look
    assert "[PASS] sPENDLE shares vs totalStakedInSpendle" in out
    assert "[MANUAL] shares + legacy vePENDLE" in out and "Total PENDLE Staked" in out
    # e) Sky: financial.skyeco.com not read live -> Jake's last reading is shown, but MANUAL, not PASS
    assert "[MANUAL] SKY bought (USD, 90d) vs Revenue Allocation" in out and "not live, so not a PASS" in out
    summary = out[out.index("SPOT CHECKS — SUMMARY"):]
    lines = {l.split(":")[0].split(None, 1)[1]: l.split()[0] for l in summary.splitlines()[1:] if l.strip()[:1] in "PCM" and ")" in l}
    assert lines["a) Hyperliquid market cap"] == "PASS"
    assert lines["c) Uniswap burn (last 90 days, 100M one-off excluded)"] == "CHECK"
    assert lines["e) Sky buybacks (flapper Exec)"] == "MANUAL", "no live reference is never a PASS"
    assert set(coi.SPOT_TOLERANCE_PCT) >= {"hl_mcap_first_party", "uni_burn_vs_holders_revenue", "sky_buyback_vs_allocation"}


def test_spot_checks_like_with_like_manual_record_and_ascii_output(monkeypatch, capsys):
    """Jake's first spot_checks run (2026-10-05): (1) the Uniswap reference was computed over 81 priced
    days but printed MANUAL — ours is now summed over the SAME priced days; (2) Sky died on a cp1252
    console — every line is ASCII-safe; (3) Pendle's 2026-09-08 epoch vs Jake's screenshot (82,545) is
    printed as a manual PASS, and lastEpochBuybackAmount = 0 keeps the automatic line MANUAL."""
    import io
    import check_offline_items as coi
    asof = pd.Timestamp("2026-10-05")
    days = pd.date_range("2026-07-08", "2026-10-05")                      # 90 days in (asof-90, asof]
    rows = [(d, "Uniswap", "gross_burn_tokens", 64_000.0) for d in days]  # 5.76M over 90 days
    rows += [(pd.Timestamp("2026-08-25"), "Pendle", "pendle_distributed_tokens", 120_000.0),
             (pd.Timestamp("2026-09-08"), "Pendle", "pendle_distributed_tokens", 82_550.0)]
    long = pd.DataFrame(rows, columns=["date", "project", "metric", "value"])
    aggs = {"Uniswap|gross_burn_tokens": {"q0": 5.76e6, "q0_covered_days": 90.0},
            "Pendle|locked_tokens_shares": {"now": 60.0e6}}
    priced = list(days[:81])                                             # 9 days unpriced

    def polite(url, method="GET", **kw):
        if "api.llama.fi" in url:
            return {"totalDataChart": [[int(d.timestamp()), 64_000.0 * 6.0] for d in days]}, ""
        if "coins.llama.fi" in url:
            return {"coins": {"coingecko:uniswap": {"prices": [{"timestamp": int(d.timestamp()) + 60, "price": 6.0}
                                                               for d in priced]}}}, ""
        if "pendle" in url:
            return {"totalStakedInSpendle": str(int(60.0e6 * 1e18)), "lastEpochBuybackAmount": "0",
                    "sPendleHistoricalData": {"timestamps": [], "buybackAmounts": [], "aprs": []}}, ""
        return None, "unexpected"
    monkeypatch.setattr(coi, "_polite", polite)
    spot = coi._Spot()
    coi._spot_uniswap(spot, aggs, asof, long)
    coi._spot_pendle(spot, aggs, long)
    out = capsys.readouterr().out
    assert "9 day(s) unpriced, left out" in out and "ours over the same 81 priced day(s): 5.18M UNI" in out
    assert "[PASS] UNI burned (81 priced days of 90)" in out and "gap +0.0%" in out
    assert "lastEpochBuybackAmount reads 0" in out and "[MANUAL] last epoch" in out
    assert "[PASS (manual record)] epoch 2026-09-08 distributed vs 'Last Epoch Distribution'" in out
    assert "82.55K PENDLE vs 82.55K PENDLE" in out and "Jake's screenshot" in out
    # every symbol this script prints survives a cp1252 console
    buf = io.TextIOWrapper(io.BytesIO(), encoding="cp1252", errors="strict")
    s = coi._AsciiStream(buf)
    s.write("a → b — ± ÷ “q” … ∋ 中\n")
    buf.flush()
    assert buf.buffer.getvalue().decode("ascii") == 'a -> b - +/- / "q" ...  contains  ?\n'
    src = open(coi.__file__, encoding="utf-8").read()
    assert "setattr(sys, name, _AsciiStream(getattr(sys, name)))" in src


